window.__D("text/likkutei-sichot/c106",{"p":[[1300161284,"<h3>משפטים ד</h3>\nא. פון פסוק1 „מי בעל דברים יגש אליהם\" לערנט אפ די גמרא2, אז „אין נזקקין אלא לתובע תחלה\" — דער „בעל דברים\" (תובע) „יגיש דבריו אליהם\".\nאיז מפרש דער ש\"ך3, אז דאס מיינט — ווי פשטות הלשון4 — אז ב\"ד הערט אויס פריער די טענות פון תובע און נאכדעם די רייד פון נתבע; און א נפק\"מ לפועל (וועמענס טענות מ'הערט אויס פריער) איז אין פאל פון א מודה במקצת:\nדער דין5 איז, אז ווען הייסט דער נתבע א מודה במקצת און איז מחוייב א שבועה דאורייתא — נאר דעמאלט ווען זיין הודאה (במקצת) קומט נאכדעם ווי דער תובע האט ביי אים געמאנט (דעם גאנצן סכום): אויב אבער דער נתבע „הודה בנ' ואח\"כ תבעו התובע בק\"ו\"6, איז ער ניט קיין מודה במקצת און איז פטור פון א שבועה (דאורייתא):\nדער טעם פון דער הלכה איז: דער נתבע האט געדארפט אפצאלן דעם „מקצת\" (וואס ער איז מודה) נאך איידער מ'האט אים תובע געווען בב\"ד: און וויבאלד ער האט ניט געטאן וואס ער האט געדארפט טאן און איז גע־בליבן א נתבע (בב\"ד), איז דערפאר נזקקין לתובע תחלה (בכדי ער זאל זיין מחוייב א שבועה דאורייתא).\nווייטער זאגט די גמרא2 „פעמים שנזקקין לנתבע תחלה והיכי דמי דקא זילי נכסי\". איז דער ש\"ך3 מבאר (בהמשך צו זיין פירוש אין נזקקין לתובע תחלה): אויב די סיבה פארוואס דער נתבע האט ניט באצאלט דעם „מקצת\", איז (ניט ווייל ער האט עס גע־וואלט פארהאלטן, נאר) ווייל אין יענעם זמן זיינען די נכסים געווען „זילי\" (ביליג) — אדער דאס גופא וואס ער וויל זיי פארקויפן במהירות (כדי צו קענען אפצאלן) וואלט זיי געמאכט ביליג — דאן איז נזקקין לנתבע תחלה.\nב. ווי גערעדט שוין פיל מאל, זיינען אלע ענינים אין נגלה דתורה פאראן אויך אין עבודה רוחנית, ואדרבה — ווי־באלד אז תורה איז בתחילה געווען חמדה גנוזה7 למעלה ומשם נסעה וירדה כו' עד שנתלבשה כו' בעניני עוה\"ז8 — די ענינים ווי זיי זיינען ברוחניות ובפנימיות זיינען דער מקור פון וואנען זיי ווערן נשתלשל אין „נגלה\". און נאכמער: כמה ענינים פון „נגלה\" קען מען פארשטיין לתכליתם נאר דורך זייער ביאור אין רוחניות העניינים9.\nועד\"ז איז בענינינו: בפשטות איז דער פירוש פון ש\"ך ניט אינגאנצן גלאטיק: פון לשון רז\"ל „נזקקין .. לתובע תחלה\" (תובע סתם) איז משמע, אז דאס איז אן",[["1","1","פרשתנו כד, יד."],["2","2","ב\"ק מו, ב."],["3","3","חו\"מ ס' כד סק\"א. ובאו\"ת (אורים סק\"ז), חידושי הפלאה ועוד שם הקשו על פירושו. ואכ\"מ."],["4","4","וכמפורש בירושלמי סנהדרין פ\"ג ה\"ח. תוספתא שם פ\"ו, ג. ועוד (ראה ש\"ך שם)."],["5","5","חו\"מ ס' פח סט\"ו־טז. ש\"ך שם סקל\"א."],["6","6","לשון הש\"ך סכ\"ד שם. ועד\"ז ספ\"ח שם."],["7","7","שבת פח, סע\"ב."],["8","8","<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>."],["9","9","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191222\" data-slug=\"likkutei-sichot\" data-id=\"1300191222\">לקו\"ש חי\"ט ע' 209</a> (והערה 16)."]]],[1300161285,"ענין כללי וואס איז א נפק\"מ לפועל אין כו\"כ אופנים פון תביעה10, און לויט פירוש הש\"ך קומט אויס, אז די נפק\"מ לפועל איז נאר אין דעם סוג תביעה וואס דער נתבע איז א מודה במקצת?\nלויטן ביאור פנימי אין דעם מאמר איז עס אבער פארשטאנדיק. ווארום בעבודה רוחנית איז רובם ככולם פון תובע ונתבע פארבונדן מיט „מודה במקצת\".\nג. דער „תובע\" פון א אידן איז דער יצר הרע, וואס פריער ברענגט ער אים ער זאל דורכפאלן אין חטא ר\"ל11 — אדער עכ\"פ צו א מצב פון „חטא\" מלשון חסרון12 — און דערנאך איז ער „תובע\"11, אז וויבאלד ער האט דעם אידן מכשיל געווען, דארף מען דעם אידן „איבערגעבן\" לרשותו.\nאויף דער תביעה פון יצר הרע, איז א איד, דער „נתבע\", נאר „מודה במקצת\": אמת טאקע אז ער איז נכשל געווארן ר\"ל אין א חטא, „הכל\" — כולו איז ער אבער ניט אריינגעטאן אין דעם חטא, ניט מיט זיין גאנצן מהות ח\"ו — זיין עצם הנשמה איז בכלל העכער פון חטא, ווייל גם בשעת החטא היתה באמנה אתו13; נאכמער: אפילו מצד זיינע כוחות — ניט נאר מצד עצם הנשמה — האט יעדער איד טוב אין זיך, און נאך מער — אפילו פושעי ישראל מלאי מצות כרמון14, וואס דער אמת'ער מושג פון „מלאין\" איז דאך כפשוטו: זיי זיינען אינגאנצן פול (מיט מצוות). דאס הייסט, אז וועגן וואס פאר א איד עס זאל זיך נאר ריידן, איז ביי אים ניט שייך די מציאות פון אינגאנצן15 רע ח\"ו.\nאון דער ענין, אז אלע דרגות פון אידן, סיי א צדיק, וואס „אין צדיק בארץ אשר יעשה טוב ולא יחטא\"16 (עכ\"פ חטא מלשון חסרון<sup data-n=\"17\">17</sup>, סיי א רשע, וואס (אויך) פושעי ישראל מלאין מצות כרמון, זיינען אין דער בחי' פון „מודה במקצת\" — איז מרומז אין פסוק פון וואנעט מ'לערנט אפ דעם דין פון מודה במקצת, „(על כל דבר פשע גו') אשר יאמר כי הוא זה\"18:\nלויטן אויסטייטש פון פסוק אין עבודה רוחנית19 איז די תביעה, סיי „על כל דבר פשע\" — ווען איינער איז פושע ומועל ר\"ל אין זיין שליחות אין עוה\"ז, און סיי „על כל אבדה\" — ווען ס'איז נאר אין אן אופן פון „אבדה\" וחסרון, ער",[["10","10","להעיר מסמ\"ע חו\"מ סכ\"ד סק\"א: וכתבו עליו פירושו זה בכה וזה בכה וכולן אמת לדינא• משום הכי סתם המחבר ללמדינו שבכל ענין קאמרי."],["11","11","כמאמר חז\"ל (ב\"ב טז, א) „יורד ומתעה ועולה ומרגיז כו' הוא שטן הוא יצה\"ר כו'\"."],["12","12","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>. ובארוכה — ד\"ה ע\"כ יאמרו תרצ\"א (סה\"מ קונט' ח\"א). ועוד."],["13","13","<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא ספכ\"ד</a>."],["14","14","עירובין יט, א. חגיגה בסופה."],["15","15","וברשע ורע לו (ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310016\" data-slug=\"tanya\" data-id=\"3401310016\">תניא ספי\"א</a>) — בכדי שלא יוקשה ממחז\"ל דמלאים מצות — י\"ל שאינן פועלות בו. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370211\" data-slug=\"torah-or\" data-id=\"3901370211\">תו\"א מו, ג</a> והגהות הצ\"צ לשם (אוה\"ת ויחי כרך ו' — תתשל, ב). דרך חיים קי, ג."],["16","16","קהלת ז, כ. וראה סה\"מ קונט' ח\"ב שב, סע\"ב ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380615\" data-slug=\"likkutei-torah\" data-id=\"4001380615\">לקו\"ת בלק (עד, ב</a>. וש\"נ) דחטאים של צדיקים פוגמים יותר כו'."],["17","17","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא רפל\"ה (מד, סע\"א</a>)."],["18","18","פרשתנו כב, ח. ב\"ק קו, סע\"ב ואילך. ב\"מ ה, א. שבועות לט, ב. מכילתא• ורש\"י עה\"פ."],["19","19","ראה בארוכה פירוש פסוק זה בעבודת האדם (מיוסד על מאמר הצ\"צ) — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011169\" data-slug=\"likkutei-sichot\" data-id=\"1300011169\">לקו\"ש ח\"א ע' 155</a> ואילך. •) ראה גם רא\"ש ב\"ק שם. •) אבל לכמה נוסחאות (נסמנו במכילתא מהדורת האראוויטץ) — „ממין הטענה\"."]]],[1300161286,"דערטוט ניט וויפל ער וואלט געקענט אויפטאן אין זיין שליחות, ובמילא ווערט פארלארן ר\"ל א טייל פון די כוחות פון נפש האלקית [און די פיר פרטים — „על שור על חמור על שה על שלמה\" — זיינען די פיר סוגים אין נפש הבהמית וואס דערפירן צו „כל דבר פשע .. אבדה\"] —\nאיז אויף די תביעות („על כל דבר פשע .. על כל אבדה\") ענטפערט א איד („אשר יאמר\") „כי הוא זה\" — אז וואס מ'זאל ביי אים מאנען איז עס נאר „זה\" — דער מקצת, ער איז (נאר) א מודה במקצת כנ\"ל.\nד. דער פסק דין פון תורה איז, אז א מודה במקצת איז חייב שבועה, דוקא דורך דער שבועה גלויבט מען אויף דעם חלק וואס ער איז ניט מודה — אין עבודה רוחנית מיינט עס:\nוויבאלד ער איז שוין דורכגעפאלן און א „מקצת\" אריין אין רשות היצר, דארף ער האבן א תוספת כח צו אפהיטן זיך אז ער זאל מער ניט אריינפאלן לרשותו (אויך ניט — דורך ניט וועלן זיין ומודה (ועוזב) ירוחם<sup data-n=\"20\">20</sup>; און צוליב דעם איז מען אים משביע — שבועה פון לשון שובע21 — מ'זעטיקט אים אן מיט נאך און העכערע22 כוחות, אז זיין צווייטער טייל זאל בלייבן אין רשות הקדושה.\nס'איז אבער ידוע•22 חומר הענין פון א שבועה — ביים נעמען אויף זיך א שבועה שטעלט מען זיך איין: אויב מ'נוצט ניט אויס כדבעי די כוחות נוספים, איז ניט בלויז וואס ביי אים פעלט דאס וואס עס דארף צוקומען, נאר עס קומט אים נאך אן עונש, וואס (אויך) העכערע כוחות גייען ביי אים לאיבוד ר\"ל; וואס דאס איז דער טעם פארוואס חז\"ל23 זיינען שטארק מזהיר קעגן געבן א שבועה דארט וואו מען קען אויסקומען אן דעם, אפילו ווען מ'איז „נשבע באמת\".\nדערפאר איז די גמרא ממשיך, אז עס איז פאראן די עצה (און פאל וסדר) פון „נזקקין לנתבע תחלה\", וואס דורכדעם ווערט מען פטור פון (דעם אופן העבודה וואס פאדערט) א שבועה — און דאס איז ווען מ'טענה'ט „קא זילי נכסי\".\nה. וועט מען דאס פארשטיין בהקדים דעם ביאור אין דעם סיפור הגמרא24 וועגן ר' יוחנן בן זכאי, וואס האט געוויינט פאר זיין פטירה און האט געזאגט, אז די סיבה פון זיין בכי' איז דאס וואס — „יש לפני שני דרכים אחת של גן עדן ואחת של גיהנם, ואיני יודע באיזו מוליכים אותי, ולא אבכה (בתמי\")\".\nאיז ידוע די קשיא25: ווי קומט עס אז ריב\"ז, וואס ער איז געווען פון די גדולי התנאים — און ווי חז\"ל זיינען בכמה",[["20","20","משלי כח, יג."],["21","21","קיצורים והערות לתניא ס\"ע נז ואילך. ובכ\"מ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011041\" data-slug=\"likkutei-sichot\" data-id=\"1300011041\">לקו\"ש ח\"א (ס\"ע 41</a> ואילך) לענין השבועה דמודה במקצת."],["22","22","שזהו גם ענין השבועה כפשוטו, שניתוסף עוד ענין, וענין חמור. •22) כמו שהאריכו חז\"ל — שבועות לט, א. ובכ\"מ."],["23","23","גיטין לה, א. תנחומא ויקרא ז'. תנחומא ובמדב\"ר ר\"פ מטות. ועוד."],["24","24","ברכות כח, ב."],["25","25","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380089\" data-slug=\"likkutei-torah\" data-id=\"4001380089\">לקו\"ת ויקרא ג, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380685\" data-slug=\"likkutei-torah\" data-id=\"4001380685\">מסעי צ, ב</a>. מאמר אדה\"ז — נעתק באוה\"ת ר\"פ פינחס ורד\"ה אך בגורל תרכ\"ו. ד\"ה אל תצר לאדמו\"ר האמצעי (ע' 73 (מאמרי אדהאמ\"צ דברים ח\"א ע' עט). וש\"נ). קיצורים והערות שם ע' מו־ז. רד\"ה אשרנו תרפ\"ח ותרצ\"ו (בסה\"מ קונט' ח\"ב). ועוד. וראה מפרשי העי\"ש שם."]]],[1300161287,"מקומות26 מפליג אין דער גדלות פון ריב\"ז, און ער איז דאך געווים געווען נזהר בתכלית אין סור מרע ועשה טוב — זאל ביי אים זיין א ספק צי ער גייט אין גן עדן אדער אין גיהנם?!\nאויך דארף מען פארשטיין: פארוואס האט דאס אים אזוי דערנומען דוקא סמוך לפטירתו? הן אמת, די „שני דרכים אחת של גן עדן ואחת של גיהנם\" זיינען פארבונדן מיטן שכר ועונש פון דער נשמה נאך איר פטירה מן העולם — עס איז אבער שווער צו פארשטיין:\nס'איז פשוט, אז דאס וואס עס האט אים בעיקר געוארט אין דעם „איני יודע וכו'\" איז (ניט בנוגע דעם ענין פון שכר ועונש פאר זיך, נאר) בשייכות צו מצבו ומדרגתו — צי ער געפינט זיך אין א מצב פון (ראוי לג\"ע) קדושה אדער ח\"ו להיפך — איז עס דאך א זאך וואס מ'דארף זיך דערויף מצטער זיין כל זמן ווען ס'איז א ספק בזה — ניט נאר בשעת הפטירה, נאר במשך פון גאנצן לעבן.\nו. איז איינער פון די ביאורים אין דעם27:\nיעדן אידן איז געגעבן געווארן א שליחות ותפקיד וואס ער דארף ממלא זיין במשך חיים חיותו בעלמא דין: און כדי צו קענען אויספירן די שליחות האט מען אים געגעבן די נייטיקע צאל טעג און באשטימטע כוחות, וועלכע זיינען נויטיק אויף צו קענען אויספירן די שליחות כדבעי, ניט מער און ניט ווייניגער.\nבשעת א איד נוצט ניט אויס א טאג, א שעה, אדער אפילו א רגע אויף צו ממלא זיין די שליחות זיינע — איז דאס ניט נאר א חסרון, וואס ער איז ניט נתעלה געווארן אויף וויפל ער האט געקענט און געדארפט, נאר יעדער רגע ורגע וואס ער טוט ניט אין זיין שליחות — אפילו ווען ער טוט אן ענין טוב כו', ס'איז אבער ניט א זאך וואס איז שייך צו זיין שליחות — פעלט בא אים די רגע במילוי שליחותו, אויך איז ער משנה, מועל ח\"ו בשליחותו של מלך מלכי המלכים הקב\"ה28.\nר' יוחנן בן זכאי איז יעדע רגע גע־וועען אינגאנצן פארנומען און אריינגע־טאן אין זיין עבודה ושליחות — לימוד התורה, קיום המצוות: ער איז געווען אריינגעטאן מיט אזא התעסקות אין אויספירן זיין שליחות כדבעי בעלמא דין29, אז ער האט ניט געהאט קיין צייט אויף צו אפשטעלן זיך און זיך אריינ־טראכטן וואס טוט זיך מיט אים, וואס איז זיין מצב בכלל.\nווארום, ווי אזוי זאל ער זיך אפ־שטעלן און טראכטן וועגן זיך, וועגן זיינע מדריגות — בשעת ער מוז אט דעם זמן אויסנוצן אויף מילוי שליחותו!\nדוקא סמוך לפטירתו, ווען ער האט געהאלטן ביים פארענדיקן זיין שליחות בעלמא דין30, האט ער מפסיק געווען31",[["26","26","ראה לדוגמא: סוכה כח, א. ר\"ה לא, סע\"ב. ועוד. הובאו כמה מהם ב(רוב ה)מקומות שצויינו בהערה הקודמת."],["27","27","ראה עוד ביאורים במקומות הנ\"ל."],["28","28","ראה זהר שצויין לקמן הערה 42."],["29","29","להעיר מקיצורים והערות שם: כשהי' בחיים חיותו בכל יום ויום הי' שמח בתכלית .. גברה בו שמחה של מצוה בהמשכת אוא\"ס ב\"ה ע\"י קיום כל מצוה ומצוה כו'."],["30","30","ראה עד\"ז קיצורים והערות שם."],["31","31","להעיר מסיפור חז\"ל (שבת ל, ב) ע\"ד אופן פטירת דוד, רבה בר נחמני (ב\"מ פו, א) — שרק כשהגיע עת פטירתם הי' יכול מלאך המות להפסיקם מגירסתם."]]],[1300161288,"כדי צו מאכן דעם חשבון צדק (ווארום אם לא עכשיו אימתי) — און דאס האט ביי אים ארויסגערופן די בכי'.\nז. אט דעם אופן אין ממלא זיין די שליחות — אז מען טראכט ניט וועגן זיך, נאר בלויז וועגן דער שליחות — איז אן ענין עיקרי וכללי אין עבודת ה', וואס ווערט געמאנט פון יעדער איד. וי\"ל אז דאס איז אויך מרומז ומודגש אין פנימיות'דיקן תוכן הפסוקים דלהלן אין דער היינטיקער פרשה: נאך די ווער־טער „ועבדתם את ה' אלקיכם גו'\"32, וואס דערמיט ווערט געמיינט כללות ענין העבודה [סיי די עבודה פון אהבה33 (דלית פולחנא כפולחנא דרחימותא<sup data-n=\"34\">34</sup> סיי די עבודה פון יראה33 (עבודת עבד<sup data-n=\"35\">35</sup>], איז דער פסוק36 ממשיך „לא תהי' משכלה ועקרה בארצך את מספר ימיך אמלא\":\n„משכלה ועקרה\" אין עבודה רוחנית מיינט, אז די עבודה (פון אהבה ויראה כו') האט ניט קיין קיום ותולדות, און די סיבה אויף דעם איז — „בארצך\"37 (פון לשון רצון<sup data-n=\"38\">38</sup>: בשעת א איד האט אן אייגענעם רצון39, א שביעת רצון פון זיין עבודה, וואס דאס ווייזט אז ער איז מרגיש זיין מציאות — ער איז עובד ה', ער האט אהבה ויראה כו'40 — דאס קען גורם זיין ער זאל דערנאך אראפפאלן ח\"ו.\nד.ה. — פריער איז זיין עבודה מיט א מדידה והגבלה — (נאר) אויף וויפל ער האט פון זיין עבודה א שביעת רצון; און נאכדעם ברענגט עס דערצו אז ער מאכט א חילוק צווישן איין עבודה און א צווייטער: די עבודה אין וועלכער ער האט א חוש איז ער גרייט צו טאן, אבער ניט אן אנדער סוג עבודה41, ביז ער איז נופל ממדריגתו כו'.\nאיז די עצה אז לא תהי' גו' — „את מספר ימיך אמלא\": בשעת ער איז זיך מתבונן אז „ימים יוצרו\"42, אז ס'איז אים באשטימט געווארן א מספר מסוים פון טעג אין וועלכע ער דארף אויספירן זיין שליחות בעלמא דין, און יעדער רגע וואס ער פארנוצט אויף עפעס אנדערש איז ער משנה און באגייט א מעילה אין דער שליחות פון ממה\"מ הקב\"ה — גיט ער זיך א טרייסל, און ער פארלירט דעם הרגש פון זיין מציאות43; ער ווערט אזוי אריינגעטאן מיט זיין גאנצער מציאות אין מילוי שליחותו, אז ער פילט ניט אפילו אז ער איז דער ממלא פון דעם אויבערשטנ'ס שליחות — עס הערט זיך ביי אים נאר די שליחות גופא.\nואדרבה: בשעת מען פרואווט אים דערמאנען וועגן „ארצך\" (וועגן זיין",[["32","32","כג, כה."],["33","33","שכל אדם צ\"ל בשתי בחי' ומדרגות כו' (<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א — נז, א</a>)."],["34","34","ראה זח\"ב נה, ב. ח\"ג רסז, א. וראה בארוכה קונט' העבודה פ\"א, פ\"ג ואילך."],["35","35","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא שם (נו, סע\"ב</a> ואילך). וראה קונט' העבודה פ\"ב."],["36","36","שם, כו. וראה בארוכה (בהבא לקמן) ד\"ה לא תהי' משכלה — תו\"א, תו\"ח ואוה\"ת בפרשתנו."],["37","37","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370350\" data-slug=\"torah-or\" data-id=\"3901370350\">תו\"א שם עט, א</a>. אוה\"ת שם ע' א'רנו. — ושם נת' באו\"א מהמבואר בפנים."],["38","38","ב\"ר פ\"ה, ח ובמ\"כ שם."],["39","39","דלא כמחז\"ל (אבות פ\"ב מ\"ד) בטל רצונך כו', או עכ\"פ עשה רצונך כרצונו."],["40","40","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370349\" data-slug=\"torah-or\" data-id=\"3901370349\">תו\"א שם עח, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550856\" data-slug=\"torat-chaim\" data-id=\"2300550856\">תו\"ח שם תלא, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520010\" data-slug=\"or-hatorah-hb\" data-id=\"8316520010\">אוה\"ת שם (בריש העמוד</a>)."],["41","41","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370350\" data-slug=\"torah-or\" data-id=\"3901370350\">תו\"א שם עט, א</a>. אוה\"ת שם ס\"ע א'רנו."],["42","42","תהלים קלט, טז. וראה זח\"א רכד, א. תו\"ח שם פ\"ז ואילך. וראה תו\"א שם, ב-ג. אוה\"ת שם ס\"ע א'רסא ואילך. ועוד."],["43","43","להעיר מלקו\"ת מסעי שם (ועוד): לא הי' יודע ריב\"ז אם נתפעל באוי\"ר מאחר שלא הרגישם כלל כו'."]]],[1300161289,"מצב רוחני), ענטפערט ער מיט צע־בראכנקייט: וואס מיר רצון אדער תענוג!44 ס'איז דאך „ימים יוצרו\", דארף מען שטיין על המשמר אז קיין רגע זאל ניט פארלארן ווערן, און ניט טראכטן וועגן „מדריגות\".\nאון בשעת א איד פועלט ביי זיך די אויסגעגעבנקייט און ביטול בכל מהותו צו דעם אויבערשטן און זיין שליחות, ווערט מקוים „את מספר ימיך אמלא\" (לשון הבטחה): אפילו אויב עס זיינען געווען טעג אין וועלכע ער האט ניט געטאן זיין שליחות, אדער אפילו געטאן ענינים של היפך ר\"ל, איז — „את מספר ימיך אמלא\" (ולא נאמר מי) — עצמותו ומהותו ית' (וואס איז העכער פון יעדן שם, און פון דעם אז עס זאל אנרירן א פגם) איז מבטיח45 אז ער וועט ממלא זיין און משלים זיין די פארפעלטע טעג, און אלע זיינע טעג וועלן זיין גאנץ, בשלימות46.\nח. דאס איז אויך דער ביאור פנימי אין דער הלכה, אז אין פאל פון „קא זילי נכסי\" איז מען פטור פון דער שבועה (דמודה במקצת):\nדי יארן און כוחות וואס דער אוי־בערשטער גיט א אידן דורכצופירן זיין שליחות בעלמא דין, דאס זיינען די נכסים פון א אידן. איז בשעת א איד פועל'ט ביי זיך דעם ביטול בתכלית, אז זיין גאנצע מציאות איז נאר וואס ער איז א שליח פון אויבערשטן, זיין גאנצע צייט און אלע כוחות זיינען פארנומען מיט טאן דעם אויבערשטנ'ס שליחות — לעשות לו ית' דירה בתחתונים — האט ער במילא קיין צייט ניט „צו גיין אויף א „דין־תורה\" מיט'ן יצר הרע\"\n— ווארום אויב ער וועט די צייט און כוחות אויסנוצן אויף אויס'טענה'ן זיך מיטן יצה\"ר, וועט דאך זיין „זילי נכסי\"47 — דער זמן וכוחות וואס דער אויבערשטער האט אים געגעבן וועלן ווערן „ביליג\", ניט אויסגענוצט אויף דברים הכי יקרים (קיום התומ\"צ) —\nדערפאר נעמט מען אן זיין טענה און ער איז פטור פון א שבועה. ווארום ניט נאר איז מען זיכער אז ער וועט ניט אריינפאלן לרשותו של היצר ח\"ו, נאר אדרבה — עס וועט זיין „את מספר ימיך אמלא\", אז אויך דאס וואס ער האט פריער פארפעלט וועט נתמלא ווערן בשלימות.\n(משיחת ש\"פ משפטים תשט\"ו, ד\"ה לא תהי' משכלה תש\"ב)",[["44","44","להעיר מהמבואר (ד\"ה ויכנעו עמי תרנ\"א. החלצו תרנ\"ג ס\"ג (סה\"מ תרנ\"ט ע' סג-סד)) דלגבי גדולת ורוממות א\"ס ב\"ה גם העבודה האמיתית דצ\"ג היא כלא ממש ואדרבה כחטא יחשב כו'."],["45","45","ע\"ד המבואר ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010124\" data-slug=\"or-hatorah-hb\" data-id=\"8159010124\">אוה\"ת</a> (פרשתנו ד\"ה ועבדתם — ע' א'ריט ואילך) לענין „והסירותי גו'\" (שנאמר בפסוק שלפנ\"ז)."],["46","46","להעיר מד\"ה ויכנעו שם, שע\"י המרירות כו' (ע\"ז שעבודתו כמו חטא יחשב כו') מעורר הרחמים והקירוב שמצד העצמות ממש (שמשם נמשך סליחת עונות כו')."],["47","47","להעיר מפי' הב' ברש\"י (ב\"ק שם) ב„זילי נכסי\" — „שקרקעותיו זלות ע\"י תביעה זו כו'\"."]]],[1300161290,"<h3>משפטים ה</h3>\nא. בסיום הסדרה, אויף די ווערטער „בתוך הענן“ זאגט רש״י „ענן זה כמין¹ עשן הוא וכו׳“ (כדלקמן סעיף ב׳).\nאיז אין דעם ניט מובן:\nענן ווערט, בכלל, געטייטשט — וואלקן, און עשן מיינט — רויך, וואס דאס זיינען צווי באזונדערע זאכן, און נאך מער, זיי זיינען פארקערט איינער פון צווייטן: „ענן“ ווערט געשאפן פון מים² און „עשן“ — פון אש³. היינט: א) פון וואנעט נעמט רש״י טייטשן דא ענן אנדערש ווי איבעראל? ב) וואס איז דא בכלל שווער אין פשוטו של מקרא, וואס רש״י דארף עס מפרש זיין?\nב. ווייטער איז רש״י ממשיך „ועשה לו הקב״ה למשה שביל בתוכו“.\nדער מקור פון דעם ענין איז אין גמרא⁴, אבער דארט קומט עס אלס א תירוץ⁵ אויף דער סתירה צווי פסוקים — „כתיב⁶ ולא יכול משה לבוא אל אהל מועד כי שכן עליו הענן וכתיב ויבא משה בתוך הענן כו׳ דבי רבי ישמעאל תנא כאן בתוך ונאמר להלן⁷ ויבואו בני ישראל בתוך הים מה להלן שביל דכתיב והמים להם חומה אף כאן שביל“.\nאבער אין פירוש רש״י דא קען מען ניט לערנען אז ער איז אויסן דערמיט צו פארענטפערן די סתירה — ווייל די סתירה ווערט ערשט שפעטער, אין פסוק „ולא יכול משה גו׳“ (אין פ׳ פקודי), האט רש״י געדארפט פארענט־פערן די סתירה ווען זי ווערט דארטן.\nמוז מען זאגן, אז דאס וואס רש״י דארף באווארענען ווי אזוי האט משה געקענט אריין אין דעם ענן („עשה לו הקב״ה למשה שביל כו׳“) איז ניט דער־פאר וואס שפעטער זאגט דער פסוק „ולא יכול משה לבוא גו׳ כי שכן עליו הענן“, נאר ווייל מען פארשטייט דא אז מען קען ניט אריינקומען אינעם ענן — איז תמוה:\nרש״י איז מפרש פריער⁸ די ווערטער „ומשה נגש אל הערפל“ אז דאס מיינט „לפנים משלש מחיצות חשך ענן וערפל“, ד.ה. אז משה איז דורכגעגאנ־גען ניט בלויז דורך חשך וענן, נאר אויך דורך ערפל⁹ וואס איז (ווי רש״י טייטשט דארטן) „עב הענן“, און פונדעסטוועגן באווארנט ניט רש״י¹⁰ ווי אזוי ער האט",[["8","8","יתרו כ, יח."],["9","9","אף שבכתוב נאמר רק „נגש אל הערפל“. וראה רמב״ן (שם, טו)."],["10","10","ודוחק גדול לתרץ שהוא לפי דיעה הא׳ שהביא רש״י בפירושו לפנ״ז (כד, טז) ד„ויכסהו הענן“ — אלו ששה ימים שמר״ח, „ויקרא אל משה ביום השביעי לומר עשה״ד“, שלפ״ז י״ל ד„ויבא משה בתוך הענן“ הוא אותו המאורע ד„ומשה נגש אל הערפל“ שבס״פ יתרו; ולכן אין רש״י מפרשו שם, כמו שמצינו בכו״כ פרטים ע״ד ההכנה למ״ת וכו׳ שנאמרו דוקא בפרשתנו (כד, א ואילך ובפרש״י), ולא בפ׳ יתרו — כי [נוסף ע״ז שעדיין אינו מיושב לדיעה הב׳ שבפרש״י הנ״ל, ד„ויכסהו הענן למשה ו׳ ימים לאחר"],["1","1","בדפוס שני ובכמה כת״י רש״י: כמו עשן."],["2","2","מלבד כשמפורש באחרת. ולדוגמא באחרי (טז, יג) „וכסה ענן הקטורת“."],["3","3","להעיר מפרש״י בשלח יד, כד (ד״ה בעמוד). ובפרש״י שה״ש (ג, ו ד״ה מי): והי׳ הענן והעשן כו׳."],["4","4","יומא ד, ב."],["5","5","כן פי׳ בעיון יעקב לע״י יומא שם. וכן משמע בחדא״ג מהרש״א שם."],["6","6","פקודי מ, לה."],["7","7","בשלח יד, כב."]]],[1300161291,"דארטן¹¹ געקענט דורכגיין¹².\nאיז דערפון מוכח, אז ביים בן חמש למקרא איז עס מעיקרא קיין קשיא ניט ווי משה קען דורכגיין דעם ענן — און ווי מ׳זעט בפשטות אז מ׳קען דורכגיין אן ענן אפי׳ אז ס׳איז נישטא קיין שביל — היינט פארוואס דארף ער עס באווארענען ביי ענן אין אונזער פסוק¹³?\nג. והביאור בזה: די קשיא וואס שטעלט זיך דא אין פשוטו של מקרא:\nוויבאלד דער פסוק זאגט פריער¹⁴ „ויכס הענן את ההר“, אז דער הר איז געווען באדעקט מיטן ענן, איז דאך מובן מעצמו אז ווען „ויעל (משה) אל ההר“ איז ער אריין אינעם ענן — צוליב וואס דארף מען מקדים און מפרט זיין אז „ויבא משה בתוך הענן“?\n[דאס וואס דער פסוק חזר׳ט דא איבער „ויעל אל ההר“¹⁵ (נאכדעם ווי עס שטייט שוין פריער „ויעל משה אל ההר ויכס הענן“) י״ל לויט די ביידע דיעות וואס רש״י ברענגט אין פריער־דיקן פסוק: לויט דער ערשטער דיעה — וויבאלד אז „ויבא משה גו׳ ויעל גו׳“ איז געווען אינעם טאג פון מ״ת¹⁶, דארף דער פסוק דאס איבער׳חזר׳ן ווייל אינ־מיטן האט דער פסוק מפסיק געווען מיט דעם זמן פון פאר מ״ת („ויכסהו גו׳ ששת ימים (מר״ח) ויקרא גו׳ ביום",[["","","עשה״ד“ ולפ״ז „ויבא משה בתוך הענן“ לפי פשטות סדר הכתוב הוא ביום השביעי כאשר „ויקרא אל משה ביום השביעי מתוך הענן“ (וצ״ע בחדא״ג יומא שם ד״ה עלה בענן)] לא יתכן לומר שרש״י לא יתרץ קושיא המתעוררת אצל התלמיד על אתר וסומך על פירושו בס״פ שלאח״ז (משא״כ זה שלא נאמר במקום הא׳ כל הפרטים כו׳, ובפרט שמפורש שם בפרש״י (יט, יא): (שעשה משה) כל הענין האמור בפ׳ ואלה המשפטים ואין מוקדם ומאוחר כו׳)."],["11","11","וכן אין מתרצו בפרשתנו (כד, ב) שפי׳ „ונגש משה לבדו“ — „אל הערפל“ [ובזה פשיטא שאין לתרץ כהקס״ד בהערה שלפנ״ז, שהרי מדובר שם בד׳ סיון, כפרש״י שם לפנ״ז (וצ״ע בראּים שם)]. ואף שאין מפורש שם שנכנס בתוך הערפל כבפירושו בס״פ יתרו, מובן הוא שכן היא הכוונה גם בפירושו בפרשתנו, מכיון שכבר פי׳ כן בפ׳ יתרו."],["12","12","ויתרה מזו: בפ׳ יתרו שם לפנ״ז (יט, יח) נאמר „והר סיני עשן כולו מפני אשר ירד עליו ה׳ באש“ (ולאח״ז שם, כ) „ויקרא ה׳ למשה אל ראש ההר“ — ואין רש״י מבאר איך נכנס משה לתוך (האש ועכ״פ לתוך) העשן."],["13","13","ודוחק לתרץ דבפרשתנו, מכיון שנאמר „ויבא משה בתוך הענן“•, משמעו שנכנס בתוכו ונשאר שם ולכן הוצרך רש״י לבאר ש„עשה לו הקב״ה למשה שביל בתוכו“ שבו הי׳ כל משך הארבעים יום (וכן משמע קצת להנ״א שבפרש״י כאן „חופה“••): משא״כ בשאר מקומות הנ״ל שרק עבר דרך הענן, או שעכ״פ הי׳ שם רק זמן מועט ביותר לשמוע ציווי ה׳ ע״מ למסור לישראל. •) להעיר מהגירסא באי׳ מכת״י רש״י (הא רמב) שמעתיק בהדיבור המתחיל גם התיבות „ויבא משה“. ••) בא׳ מכת״י רש״י (הא קיב?) איתא בסוף פרש״י „ונכנס בו“."],["14","14","כד, טו."],["15","15","ראה אלשיך כאן „או יאמר כו׳“."],["16","16","שעלה בכדי לקבל הלוחות כהמשך הכתוב ויהי משה בהר גו׳ — ראה יומא שם (ע״ב) „בשלמא לר׳ עקיבא“ ובפרש״י שם. ב״ח שם אות א׳ (וראה חדא״ג שבהערה 10). וצ״ע ברבינו בחיי כאן, שמפרש: ויכסהו הענן ששת ימים זהו מר״ח סיון עד ששי בו (כדעת רע״ק, אבל ממשיך) ואז נתנה התורה (דלא כרע״ק שס״ל בז׳ ניתנה, כבגמרא שם•) ויקרא אל משה ביום השביעי זהו למחרתו אחר מ״ת כו׳ (דכפשוטו הוא דלא כמאן (ר״ע וריה״ג). וממשיך) וששת ימים שהי׳ מכוסה בענן היו בכלל ארבעים כו׳ (כביאור הגמ׳ בדעת ריה״ג, וממשיך להקשות) למה הוצרכה קריאה זו, אבל מצינו בזה לרז״ל דעות כו׳ בפ״ק דיומא: ויקרא וכו׳ לא בא הכתוב אלא לחלוק כבוד למשה דברי רבי עקיבא כו׳ [דכפשוטו פי׳ (כפרש״י בש״ס ובכתוב כאן) היינו יום הז׳ באמירת עשה״ד]. ואולי יש לו פי׳ אחר בכל המשך הגמ׳. או שטה״ד בדברי הבחיי, ויש שם השמטת דברים. וצ״ע. •) אבל עד״ז כתב במאירי יומא שם: ולד״ה בששה בסיון נתנו עשה״ד."]]],[1300161292,"השביעי גו׳“); ועאכו״כ לויט דער צווי־טער דיעה, וואס די צווי מאל „ויעל“ זיינען ניט די זעלבע. דער ערשטער רעדט וועגן עליית משה להר גלייך נאך מ״ת, און דער „ויבא משה בתוך הענן ויעל אל ההר“ — איז געווען אין דעם „יום השביעי“ נאך מ״ת¹⁷].\nאיז דערפון¹⁸ משמע, אז מיט „בתוך הענן“ מיינט דער פסוק זאגן — אז דער ענן וואס שטייט דא איז ניט דער זעלבער ענן וואס ווערט דערמאנט אין די פריערדיקע פסוקים¹⁹. ווערט דאך די שאלה: וואס איז געווען אט דער ענן? זאגט רש״י „ענן זה (פון דעם פסוק) כמין עשן הוא“:\nדעם „ענן“ וואס ווערט דערמאנט אין די פריערדיקע פסוקים און פרשיות דארף רש״י ניט מפרש זיין, ווייל ס׳איז מובן בפשטות: ס׳איז געווען אן ענן כפשוטו אין וועלכן ס׳איז געווען אנגע־טאן כבוד ה׳; און ווי ס׳איז געווען דער עמוד הענן, אז „וה׳ הולך לפניהם יומם“ מיט אן „עמוד הענן“²⁰ („ולילה בעמוד אש להאיר להם“) — ענן כפשוטו.\nמשא״כ דער „ענן“ שבפסוק זה, וואס מ׳מוז זאגן, כנ״ל, אז דאס איז געווען אן אנדער מין ענן, דארף רש״י מפרש זיין אז „(ענן זה) כמין עשן“.\nד. דער הכרח פון רש״י׳ן אז „ענן זה כמין עשן“ איז פון די פסוקים גופא:\nצווישן „ויקרא אל משה גו׳“ און „ויבא משה בתוך הענן“ איז דער פסוק „ומראה כבוד ה׳ כאש אוכלת בראש ההר גו׳“. איז ניט פארשטאנדיק: דער פסוק האט געדארפט שטיין פאר „ויקרא אל משה“ בהמשך צו „וישכון כבוד ה׳“, אפטייטשנדיק אז דער מראה פון „כבוד ה׳“ איז געווען „כאש אוכלת“ — פאר־וואס שטייט עס ערשט נאך „ויקרא אל משה ביום השביעי מתוך הענן“?\n[לא מיבעי לויט דער דיעה אז „ויקרא אל משה גו׳“ איז געווען ביום השביעי נאך מ״ת, ווען דער אויבערשטער האט גערופן משה׳ן ער זאל ארויפגיין מקבל זיין די לוחות — און „ויבא משה גו׳“ איז געווען דער ענטפער אויף דער",[["17","17","ראה עד״ז ב׳ הדיעות בהכתובים וביאורים בבאר יצחק לפרש״י כאן (פסוק א׳ וט״ז)."],["18","18","בבאר יצחק שם פסוק א׳ בסופו מבאר (וראה גם גו״א כאן) להדיעה שויכסהו הענן מר״ח לפני מ״ת, דזה שחוזר לספר מפסוק טז ואילך ע״ד הסדר שקודם מ״ת, לאחר שהפרשה (פסוק יב ואילך, כפרש״י שם) מדברת בהעלי׳ כו׳ לאחר מ״ת, ובפסוק האחרון חוזר לענין הא׳ העלי׳ שלאחר מ״ת — כי בג׳ פסוקים אלו (פסוק טז ואילך) מספר מגדולת ההר שעלה בו משה וקדושתו. וצ״ע שהרי תוכן דפסוק יח אינו בגדולת וקדושת ההר, כ״א ע״ד עליית משה כו׳."],["19","19","ע״פ פי׳ החדא״ג שם ד״ה והא אסתלק הי׳ אפשר לומר, שההכרח שהענן שבכתוב זה אינו הענן שבכתובים שלפנ״ז הוא מפני שלב׳ הדיעות נסתלק הענן לאחרי ששה ימים, למר כדאית לי׳ (לריה״ג לאחר ו׳ ימי פרישה לאחר מ״ת), ולמר כדאית לי׳ (לרע״ק „בו׳ שקבלו התורה נסתלק מלכסות“). אבל (נוסף לזה שלפי׳ רש״י לדיעה הב׳ (ריה״ג) פי׳ „ויכסהו הענן“ היינו „למשה“, וא״כ אין לנו ראי׳ שנסתלק הענן מההר•, הרי) לכל הדיעות•• מפורש בכתוב שלפנ״ז „ויכס הענן את ההר“ שהמדובר לאחר מ״ת ואינו מפרט בזה זמן מסוים•••. •) וראה תוס׳ ישנים יומא שם. אברבנאל כאן (השאלה הי״ד בסופה ובהביאור לפסוקים אלו ד״ה ויאמר ה׳), באר יצחק. ועוד. ••) ראה פרש״י תענית כא, ב ד״ה אל מול: לא נסתלקה שכינה עד לוחות האחרונות. אבל בפרש״י עה״ת (יתרו יט, יג) קול ארוך הוא סימן כו׳ הם רשאין לעלות. •••) כי דוחק לפרש ב„ויכס הענן את ההר“ שזה הי׳ רק בשעה ש„ויעל משה אל ההר“, דאז הול״ל"],["20","20","בשלח יג, כא. בסדר הפוך „ויכס הענן את ההר ויעל משה אל ההר“."]]],[1300161293,"קריאה — האט דאך קיין ארט ניט²¹ צו מפסיק זיין צווישן „ויקרא אל משה“ און „ויבא משה“ (זיין אויספאלגן די קריאה) מיטן פסוק „ומראה כבוד ה׳“²².\nנאר אפילו לויט דער ערשטער דיעה, אז „ויקרא אל משה“ איז געווען „לומר עשרת הדברות ומשה וכל בני ישראל עומדים אלא שחלק וכו׳“ (ניט אז דער אויבערשטער האט גערופן משה׳ן ארויפצוגיין אויפן הר) און „ויבא משה בתוך הענן“ איז אן ענין ניט פארבונדן מיט „ויקרא אל משה גו׳ מתוך הענן“ — פונדעסטוועגן איז אויך מער מתאים אז דער תיאור ענין פון „ומראה כבוד ה׳ גו׳“ זאל שטיין גלייך בהמשך צו „וישכון כבוד ה׳ על הר סיני“].\nדעריבער לערנט רש״י, אז דער פסוק „ומראה וגו׳“ איז א הקדמה צום פסוק „ויבא משה בתוך הענן גו׳“: ער איז מרמז מיט וואס דער ענן איז אנדערש פונדעם ענן וואס שטייט פריער אין פסוק (וואס דערפאר דארף דער פסוק מדגיש זיין „ויבא משה בתוך הענן“): דער ענן איז א תוצאה פון דעם „אש אוכלת“: ער איז „כמין עשן“ וואס איז געקומען פון דעם „אש אוכלת“ וואס שטייט אין פריערדיקן פסוק²³.",[["21","21","כמו שהקשה באלשיך כאן."],["22","22","באברבנאל פקודי בסופו ד״ה וראיתי, מפרש שביום ז׳ כאשר ויקרא אל משה ביום השביעי מתוך הענן נבקע הענן ואז ראו ישראל כבוד ה׳ שהי׳ כאש אוכלת לעיניהם (ועד״ז הוא במלבי״ם כאן). אבל זהו לפי פירושו שם ד„ויכסהו הענן“ היינו שכיסה את ה„כבוד“ הנזכר לפניו, אבל לפי פירש״י שהביא (רק) ב׳ הדיעות (אם קאי על ההר, או על משה) אין מקום לפי׳ זה."],["23","23","לפי הגירסא שלפנינו בגמ׳ ובע״י משמע (וכן מפורש במאירי שם) דפלוגתת ריה״ג ורע״ק הוא גם בפסוק „וישכון כבוד ה׳“, דלדעת ריה״ג „זה הי׳ מעשה אחר עשה״ד ורע״ק אומר וישכון כבוד ה׳ מר״ח כו׳“. אבל בפרש״י עה״ת כאן פי׳ פלוגתתם רק ב„ויכסהו הענן“ וב„ויקרא אל משה ביום השביעי“, וא״כ י״ל דלכו״ע ההמשך „וישכון כבוד ה׳“, „ומראה כבוד ה׳ כאש אוכלת“ הוא בזמן אחד, ונמשך זה כל הזמן לאחר מ״ת (ראה לעיל הערה 19 בשוה״ג הא׳ והב׳). אבל גם את״ל שגם לפרש״י פלוגתתם היא בהזמן ד„וישכון כבוד ה׳“, הרי מזה שהכתוב מפסיק ב„ומראה כבוד ה׳ כאש אוכלת“ מובן שזוהי הקדמה ל(תאר תוכן) „הענן“ שבהכתוב שלאח״ז. וראה ראב״ע פסוק טז ואילך. אלשיך שם. ועוד."],["24","24","באברבנאל פרשתנו שם (ובארוכה פ׳ פקודי שם) ועוד — ביאור ע״ד החקירה והדרוש."],["25","25","ראה יומא כא, ב."],["26","26","שמות ג, ב. שמו״ר פ״ב, ה. וראה ד״ה וה״ס עשן תרס״ב. לקמן בפנים. ה. דערמיט ווערט אויך מובן דער דיוק הפסוק — „כאש אוכלת“. דלכאור־רה איז ניט פארשטאנדיק: צו מתאר זיין די מראה פון כבוד ה׳ איז בלויז נוגע צו זאגן אז עס האט אויסגעזען ווי פייער: צוליב וואס דארף דערביי צוגעגעבן ווערן אז דאס איז געווען ווי אן אש „אוכלת“²⁴? וע״פ הנ״ל איז דאס פארשטאנדיק בפשטות: היות אז דער מכוון אין דעם פסוק דא איז צו מסביר זיין דעם פירוש פון דעם פסוק שלאחריו „ויבא משה בתוך הענן“ — אז דער ענן איז געווען אן עשן וואס האט זיך געשאפן פון דעם וואס „מראה כבוד ה׳“ איז געווען „כאש“ — דעריבער איז דער פסוק מוסיף ומדגיש „(כאש) אוכלת“, ווייל אן עשן ווערט ניט פון אש אלייין, נאר פון אן אש וואס איז „אוכלת“ (מכלה, פארברענט) די זאך אין וועלכער זי איז נאחז. [ויש להוסיף: בכלל איז דער אש שלמעלה ניט קיין „אש אוכלת“²⁵, ווי מען האט שוין געלערנט פריער ביים סנה: „וירא גו׳ בלבת אש גו׳ והסנה איננו אוכל“²⁶; דערפאר דארף דער פסוק מדייק זיין, אז דא איז יע געווען אן „אש אוכלת“, וואס דערפאר האט זיך"]]],[1300161294,"דערפון געשאפן אן „(ענן . . כמין עשן“)].\nו. ע״פ כל הנ״ל וועט ווערן פאר־שטאנדיק פארוואס רש״י דארף באווא־רענען „ועשה לו הקב״ה למשה שביל בתוכו“ דוקא אין אונזער פסוק (און בהמשך צו זיין פירוש „ענן זה כמין עשן הוא“):\nווען דער ענן דא וואלט געווען דער זעלבער ווי אין די פריערדיקע פסוקים, פאדערט זיך ניט צו באווארענען ווי אזוי משה איז אריין „בתוך הענן“ (ואדרבה, ווי גערעדט פריער, איז משה „נגש (אפילו) אל הערפל“ — „עב הענן“)²⁷;\nוויבאלד אבער אז „ענן זה כמין עשן הוא“, וואס רויך האט אין זיך די טבע (דורך דעם „פיח“²⁸ אין אים פונעם דבר הנשרף) צו פארורויכערן, שווארץ מאכן דעם וואס געפינט זיך אין אים און זיינע לבושים — ווערט די תמי׳: היתכן אז אזוי איז דאס געווען ביי משה רבינו און אזוי האט ער אויסגעזען בעת ער איז ארויף אויפ׳ן הר צום אויבערשטן אויף צו מקבל זיין די לוחות — היפך הכבוד כו׳²⁹!",[["27","27","ואין רש״י צריך לפרשו כמו שא״צ לפרש לפנ״ז (יתרו יט, כ) ב„ויקרא ה׳ אל משה אל ראש ההר“ (המקום „אשר ירד עליו ה׳ באש“ (שם, יח)) „ויעל משה“, דבדבר שנוגע לפועל, מובן מעצמו שהקב״ה עשה נס שיוכל לקיים ציווי ה׳, לעלות, ועד״ז בערפל. וכ״ה בנדו״ד שאין קושיא איך נכנס משה בפועל בכמין עשן מצד העדר האויר כו׳."],["28","28","ראה פרש״י וארא ט, ח."],["29","29","ובמכ״ש מהא ד(שבת נ, ב) „רוחץ אדם פניו ידיו ורגליו בכל יום בשביל קונו“, „לכבוד קונהו דכתיב (נח ט, ו) כי בצלם אלקים עשה וגו׳“ (פרש״י שם ד״ה בשביל). ובשו״ע אדה״ז או״ח סוס״ד (מהדו״ק): „בשביל כבוד קונו“ (כגי׳ הע״י). •) והא שהשמיט אדה״ז שם „ידיו“ (וראה ויק״ר פל״ד, ג. חדא״ג שבת שם) — י״ל שהרי כבר הביא דעריבער איז רש״י ממשיך „ועשה³⁰ לו הקב״ה שביל בתוכו“, און משה איז געגאנגען אין דעם שביל, באופן אז דער עשן האט אים ניט בארירט. ז. עס בלייבט אבער ניט פאר־שטאנדיק: (א) פארוואס זאגט רש״י „ענן זה כמין עשן הוא“ — ולפי הנ״ל איז עס דאך געווען אן עשן פון אש³¹, עשן ממש? (ב) פארוואס זאגט דער פסוק „ויבא משה בתוך הענן“ און ניט „בתוך העשן“? איז דער ביאור בזה: דער הר סיני איז מדבר סיני, ובפרט דער „ראש ההר“ (וואו עס איז געווען דער „מראה כבוד ה׳ כאש אוכלת“), איז דאך ניט אן ארט וואו עס וואקסן אילנות ודשאים ועש־בים³², נאר א מקום פון אבנים ועפר³³; און סיבת עשן איז דוקא אז דער פייער איז אוכל ומכלה א דבר הנשרף³⁴ (ווי אילנות וכו׳), וואס דאס איז ניט שייך ביי דומם (אבנים ועפר), דעריבער זאגט ---"],["30","30","בא׳ מכת״י רש״י (הא רל) „שעשה“."],["31","31","לכאורה י״ל שאין זה עשן באמת רק „כמין עשן“, כי לא הי׳ אש בפועל (כביתרו שם, יח — אשר ירד עליו ה׳ באש), כ״א רק „מראה“ של אש, כדיוק לשון הכתוב „ומראה כבוד ה׳ כאש אוכלת גו׳“ (ועד״ז הוא ע״פ דרוש כו׳ — ראה אברבנאל אלשיך ועוד). אבל מזה שהכתוב מדגיש „כאש אוכלת“ מובן שהי׳ אש כפשוטו כבפ׳ יתרו (שהרי זה שאוכלת אינו שייך ל„מראה“)."],["32","32","משא״כ בנוגע להר עצמו — ראה לעיל ע׳ 223־4 והערה 9, די״ל שע״פ פשש״מ היו שם אילנות ועשבים כו׳."],["33","33","כבאלשיך יתרו שם. וראה לעיל שם בשוה״ג."],["34","34","„כי אין אש שלמעלה חלוק בזה מאש שלמטה שנאמר דאש של מעלה הנה הוא בעצמו מעלה עשן“ (ד״ה וה״ס עשן תש״ח בתחלתו). וראה בהנסמן שם. ולהעיר מד״ה וה״ס עשן תרס״ב. לפנ״ז חיוב נטילת ידים (שחל עליו לפני רחיצת פניו ורגליו), והרי דין זה הוא בסיום דהל׳ נט״י בשחרית. וראה לקו״ש חל״א ע׳ 186 ואילך."]]],[1300161295,"רש״י אז דא איז ניט געווען עשן ממש, נאר בלויז „כמין עשן“, דער ענן פון אוכלת (שריפת) הדומם אויפן הר סיני איז געווען אזוי ווי אן עשן (סתם וואס ווערט פון א צומח וואס ווערט פאר־ברענט פונ׳ם אש).\nאון מהאי טעמא — ווייל דאס איז ניט געווען אן עשן טבעי — רופט עס אן דער פסוק בשם „ענן“.\nח. מיינה של תורה אין דעם פירוש רש״י:\nדער ענין העשן בהר סיני ביי מ״ת שטייט מפורש אין דער תורה בפ׳ יתרו³⁵, „והר סיני עשן כולו מפני אשר ירד עליו ה׳ באש“.\nמשא״כ בפרשתנו שטייט דער לשון „ענן“.\nוי״ל הביאור בזה: אז³⁶ עשן כפשוטו נעמט זיך פון דעם דבר הנשרף — מצד דעם וואס דער דבר הנשרף איז א חומר גשמי, און דער אש וואס איז מכלה דעם גשם איז דער כליון גורם — זיינע תוצאות זיינען — עשן.\nאון דערפאר זיינען אין עשן פאראן חילוקים וועלכע זיינען תלוי אין דעם מהות פון חומר הנשרף: ווען דער דבר הנשרף איז א חומר דק (ווערט ער פאר־ברענט שנעלער און דאן) איז אויך דער עשן „איידעלער“ און שיטערער; משא״כ ווען דער דבר הנשרף איז א חומר עב וגס, איז דאן דער עשן געדיכטער און גרעבער (און גרעסער) —\nפון דעם איז פארשטאנדיק, אז אין דעם עשן פון יעדער זאך איז ניכר (זאגט זיך ארויס) אויף וויפל דער חומר פון דער זאך איז גס, דאס קומט לידי גילוי בכליון הדבר.\nאזוי ווי דאס איז בגשמיות, אזוי איז דאס אויך ברוחניות, אין דעם ביטול וכליון פון דברים דלמטה צו אלקות³⁷: דורך דעם גילוי אש שלמעלה ווערט „נאכל“ ונכלה די ישות פון וועלט און עס ווערט אין איר אויפגעטאן דער ביטול וכליון צו אלקות.\nאון דאס איז (ברוחניות) דער ענין העשן, וואס ווייזט אויף כליון פון ישות און ביטול פון וועלט.\nט. און דאס איז דער חילוק צווישן די צווי פסוקים הנ״ל:\nדער פסוק „והר סיני עשן כולו“ רעדט זיך וועגן זמן מ״ת, און היות דער גילוי אלקות פון מ״ת איז געווען בדרך מלמעלה למטה, (ווי דער פסוק איז ממשיך „מפני אשר ירד עליו ה׳ באש“ — דער גילוי איז געווען מצד למע־לה³⁸) און דער עולם איז נאך דאן געווען א גשמי וחומרי וואס איז ניט מזוכך³⁹ — דעריבער האט דער גילוי אלקות דאן אויפגעטאן דעם ביטול און כליון פון וועלט אין אן אופן פון „והר סיני עשן כולו“, וואס דער ריבוי וגודל ה„עשן“ ווייזט אז די חומריות העולם איז ניט געווען דק ומזוכך.",[["35","35","יט, יח."],["36","36","בהבא לקמן — ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370422\" data-slug=\"torah-or\" data-id=\"3901370422\">תו״א צד, א</a>. רד״ה וכל העם תש״ד. ועוד."],["37","37","וכידוע בפי׳ עשן ר״ת עולם שנה נפש „כמבואר בספרי הקבלה ובפי׳ הראב״ד לספר יצירה“ (אוה״ת יתרו ד״ה וה״ס עשן — ע׳ תתטז), והיינו עליית עולם שנה ונפש. וראה בהמאמר שם בארוכה בפי׳ וה״ס עשן כולו (וכן בד״ה שלאח״ז ע׳ תתכג ואילך. ע׳ תתכט ואילך). ובמקומות שנסמנו בהערה 34. ועוד."],["38","38","ראה גם ד״ה וה״ס תרס״ב. ובסוף ההמשך (דתרס״ב) שם."],["39","39","ראה המשך תער״ב ח״ב ע׳ תתקל ואילך. ובכ״מ."]]],[1300161296,"משא״כ בפרשתנו, וואו עס רעדט זיך וועגן דעם זמן פון נאך מ״ת, נאך דעם ביטול והזדככות וואס מ״ת האט גע־פועל׳ט בעולם, איז שוין דאן די מציאות פון וועלט ניט אזויפיל גס⁴⁰.",[["40","40","עפ״ז אולי יש לבאר גם השינוי שבפרשתנו מפורש „כאש אוכלת“, משא״כ בפ׳ יתרו נאמר „מפני אשר ירד עליו ה׳ באש“ סתם ואינו מפרט „אוכלת“ (שמלשון זה משמע, שהעשן נעשה מהאש עצמו ולא מכליון דבר הנשרף, כהקושיא ברד״ה וה״ס עשן תש״א ותש״ח. ועוד): כי מצב העולם בזמן מ״ת גס כ״כ עד שאינו ראוי גם להיות נכלה ונשרף ע״י אש (בדוגמת הדומם כפשוטו*, כבאלשיך ומאמרים הנ״ל) ולכן אין העשן שייך כ״כ לכליון ההר כנ״ל [ולהעיר מד״ה וה״ס תרס״ב שם לענין בחי׳ דומם שבדומם שאינו עולה ע״י האש]. משא״כ בפרשתנו, שהי׳ לאחרי ביטול היש והזדככותו במ״ת, הרי נעשה דק יותר וראוי שיהא נאכל ונשרף ע״י האש שלמעלה. *) וי״ל שזהו גם טעם הפנימי, שדומם אינו כלה בטבעו באש כי הוא בריחוק הערך לגמרי ממהות האש, ואינו שייך לומר גם זה שהוא בניגוד והיפך טבעו לאש, כמו שאומרים בנוגע לצומח כו׳. ועפ״ז אולי יש לומר מה שבד״ה וה״ס תש״ח בסופו מבאר שינוי טבע הבריאה שנעשה בעת מ״ת, דה״ס „אם היותו אבנים ואינו שייך בו הכליון בשריפה להיות עשן בכ״ז כולו הופך טבעו, מפני אשר ירד עליו ה׳ באש הופך טבעו בטבע העליון“, דמוכח מזה, דשינוי טבע ההר לא הי׳ מספיק שיפעול ירידת האש, כ״א צריך לעוד ענין בשינוי טבע הבריאה, שינוי טבע האש; כי מכיון שהדומם מצד עצם מהותו הוא בריחוק הערך ממהות האש (דוגמת דומם ומדבר — ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670073\" data-slug=\"torat-chaim\" data-id=\"2300670073\">תו״ח בראשית יט, ג</a>. המשך תרס״ו ריש ע׳ קטו (ועוד) דאש הוא בחי׳ מדבר) לכן גם לאחר שנתחדש בו ענין הכליון, צריך להיות גם שינוי טבע האש, דוגמת הנפש וגוף שעם היות שאברי הגוף בטלים לנפש ואברי הגוף הם בציור שם הוי׳ כו׳, צ״ל כח המפליא לעשות לחבר הנפש עם הגוף (ד״ה אחרי מות תרמ״ט בתחלתו. ובכ״מ). או י״ל ע״פ (וע״ד) המבואר בד״ה אחרי שם (סעיף ו) ובכ״מ דירידת האור היא מצד מעלת שורש הכלים, ומכיון שב(נדו״ד) ענין הכליון שנעשה בו הוא היפך טבעו הוא דבר נוסף בו (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171089\" data-slug=\"likkutei-sichot\" data-id=\"1300171089\">לקו״ש חי״ז ע׳ 89</a>, <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181251\" data-slug=\"likkutei-sichot\" data-id=\"1300181251\">חי״ח ע׳ 242</a> — ע״ד ב׳ סוגי ניסים), לכן אין דעריבער האט דער „מראה כבוד ה׳ כאש“ גורם געווען ניט אן ענין פון עשן ממש, נאר „לרוב דקותו לא נקרא בתורה בשם עשן כ״א בשם ענן“⁴¹, וואס ענן ווייזט ניט אויף דער כליון ועלי׳ מלמטה למעלה⁴². אויף דעם איז רש״י — מיינה של תורה — מגלה, אז „ענן זה כמין עשן הוא“: היות אז ענינו איז ניט דער גילוי אלקות מלמעלה ווי דער ענן וואס ווערט דערמאנט אין די פסוקים פריער, נאר דאס קומט פון דעם מראה כבוד ה׳ כאש אוכלת, ווי אלקות פועלט דער ביטול אין מציאות העולם, איז — „כמין עשן הוא“: אויך אין דעם איז דא אן ענין פון עשן — עפרורית ועכרורית (וואס קומט פון דעם כליון החומר). ווארום וויבאלד אז דער מכוון ענין התורה איז כדי צו מאכן פון וועלט א דירה לו ית׳ בתחתונים, איז דערפאר „ענן זה“ — דער ענן, אין וועלכן משה האט געדארפט אריינגיין כדי צו מקבל זיין לוחות (ותורה) און אראפברענגען זיי למטה — איז „כמין עשן הוא“, עס איז א גילוי מלמעלה וואס פועלט כליון וביטול החומר פון נבראים — [ס׳איז נאר וואס זייענדיג נאך דעם גילוי פון מ״ת וואס האט אויפגעטאן א הזדככות וביטול כללי אין חומר העולם, איז דערפאר ניט געווארן „עשן (כולו)“ (ווי בעת דעם התחלת גילוי פון מ״ת), נאר בלויז „כמין עשן“ כנ״ל — אבער אן „עשן“ מוז זיין]. ---"],["41","41","לשון התו״א שם."],["42","42","וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370074\" data-slug=\"torah-or\" data-id=\"3901370074\">תו״א טז, א</a>. מתגלה ע״י שרש הכלי (כח הגבול), כי א״ז ביטול הכלי מצד ענינו הוא, ולכן ירידת האש היא חידוש. ואכ״מ."]]],[1300161297,"יו״ד. די הוראה מהנ״ל בעבודתנו:\nעס זיינען פאראן אזעלכע ענינים וואס טענה׳ן, מה לי ולדברים התחתונים? אויב שוין יע אראפלאזן זיך, איז גענוג די ירידה אין אזעלכע ענינים וואס זיי־נען אין דער בחי׳ פון „חי“, אדער אפילו נידעריקער — „צומח“: אבער ניט האבן צו טאן אויך מיט די זאכן אין וועלט וואס זיינען אין סוג פון „דומם“, א מציאות חומרית ביותר אין וועלכער עס זעט זיך ניט קיין שום חיות, ביז אז אפילו ווען ס׳איז מאיר אש הוי׳, איז ער (מצד טבעו) ניט קיין כלי דערצו און ס׳איז אין אים ניט נאחז דער אש⁴³ (עס דארף זיין פריער דער ענין פון „מבט־שין לי“⁴⁴).\nזאגט מען זיי, אז מען מוז פועל׳ן אן עשן והעלאה אויך אין דעם נידע־ריקסטן סוג פון „דומם“ אין וועלט, ווייל מיט דעם איז פארבונדן דער תכלית פון מ״ת, אז דער ענין ה„עשן“, דער כליון און עלי׳ פון חומר העולם, זאל אויפ־געטאן ווערן ניט נאר אינעם צומח, נאר אויך אין „הר“ — דומם.\nקענען זיי קומען מיט נאך א טענה — ס׳איז דאך „המתאבק עם מנוול מתנוול ג״כ“⁴⁵, דורך דער עבודה צו פועל זיין אן „עשן“ אין דברים תחתונים וועט דאך גורם זיין מ׳זאל זיך „איינריכטן“ — איז דאך גלייכער מען זאל זיך ניט פאר־נעמען מיט זיי? אויף דעם איז דער ענטפער:\nא) „עשה לו הקב״ה (למשה) שביל בתוכו“: די בחי׳ „משה“ וואס איז דא אין דער נשמה פון יעדן אידן⁴⁶, זי וועט זיך ניט „איינריכטן“, זי וועט בלייבן ריין, ווייל זי גייט דורך א „שביל“ — זי איז אלעמאל באמנה אתו ית׳⁴⁷.\nב) נאכמער: בפנימיות הענינים, וועלן אויך די כחות הגלויים ניט „פאר־שמירט“ פון דעם „עשן“. ווייל אין אמת׳ן איז עס גאר ניט קיין עשן, ס׳איז בלויז כמין עשן — עס איז אן ענן וואס זעט נאר אויס ווי אן עשן.\nד.ה. דאס וואס די וועלט איז מעלים ומסתיר אויף אלקות איז עס נאר כמין פון א מציאות צוליב דעם ענין פון בחירה. אויב מען וואלט געזען דעם אמת, וואלט דאן ניט געווען קיין ארט אויף בחירה.\nאון נאכמער: וויבאלד אז דער העלם קומט (צוליב א תכלית) פון קדושה איז עס באמת גאר אן „ענן“ (קדושה): ער קוקט טאקע אויס ווי „עשן“, ווי א דבר חומרי וואס אפילו נאך זיין כליון ועלי׳ בלייבט איבער עפרורית — אבער דאס איז בלויז וואס נראה לעיני בשר; בפנימיות איז עס אן „ענן“ של קדושה, ווארום דער גאנצער תכלית זיינער איז בשביל תוספת אור בקדושה.\nאון דאס איז די הוראה, אז מען מוז אריינגיין און דורכגיין דעם „עשן“. דורך דעם איז מען מקבל תורה⁴⁸. משה רבינו — ובכאו״א, בחי׳ משה בנפשו — האט מקבל געווען די תורה נאך דער הקדמה פון „ויבא משה בתוך הענן“, וואס „ענן זה כמין עשן הוא“ (און ער מוז אנקומען צו א „שביל בתוכו“).",[["43","43","ראה לעיל הערה 40 בשוה״ג."],["44","44","ראה זהר (ח״ג קסח, א) — הובא ונתבאר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא רפכ״ט</a>."],["45","45","<a class=\"ft-cite\" href=\"#/read/tanya/3401310033\" data-slug=\"tanya\" data-id=\"3401310033\">תניא ספכ״ח (לה, ב</a>)."],["46","46","<a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ״ב</a>."],["47","47","<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא ספכ״ד</a>."],["48","48","ראה גם ד״ה ויבא משה תרנ״ד בסופו."]]],[1300161298,"כאטש דאס איז לשעה ובחיצוניות און ענין פון העלם, אבער דורך דעם קומט מען צו „ויהי בהר ארבעים יום וארבעים לילה“ און מען האט תורה בשלימותה:\nאון דערנאך איז דאס יעדער ממשיך אין גופו וחלקו בעולם, וואס דאס איז דער המשך פון (נאך) פ׳ משפטים (אין פ׳ תרומה) — „ועשו לי מקדש ושכנתי\nבתוכם“⁴⁹,\nפון די דברים גשמיים, זהב וכסף גו׳, מאכט מען א מקדש לו ית׳, וואס דורך דעם פירט זיך אויס די כוונה פון נת־אווה הקב״ה להיות לו ית׳ דירה בתחתונים.\n(משיחת ש״פ משפטים תשכ״ה)",[["49","49","תרומה כה, ח."]]],[1300161299,"<h3>תרומה</h3>\nא. אין התחלת הסדרה איז רש״י מעתיק פון פסוק די ווערטער „ויקחו לי תרומה” און איז מפרש „לי לשמי”.\nוואס איז דא שווער אין די ווערטער, וואס רש״י דארף בכלל מפרש זיין? — זאגן מפרשים¹:\nדער פשוט׳ער טייטש פון „ויקחו לי” איז „צו מיר” — ד.ה. צו געבן דאס דעם אויבערשטן, און דאס קען מען דאך ניט זאגן כלפי דעם אויבערשטן, ווארום: א) ווי איז שייך זאגן אז מ׳גיט אים עפעס אדער ער דארף צו דעם אנקומען² — ס׳איז דאך „לה׳ הארץ ומלואה”³, אלץ באלאנגט דאך צו אים און „אם ארעב לא אמר לך”⁴. ב) דער ווארט „לי” ווייזט אז די שייכות פון דער זאך „צו מיר” איז דורך (קיחה) לקרב — און דאס פאסט בלויז בנוגע צו א דבר גשמי, משא״כ בא דעם אויבערשטן, וואס „אינו גוף כו׳ ואין לו שום דמות וצורה כו׳”⁵.\nאון דעריבער דארף רש״י מפרש זיין אז „לי” מיינט „לשמי”.\nעס איז אבער שווער אזוי צו איינ־לערנען, ווארום [נוסף אויף דעם וואס דעמאלט איז ניט פארשטאנדיק פאר־וואס רש״י איז מעתיק פון פסוק אויך די ווערטער⁶ „ויקחו” און „תרומה”⁷, ווי־באלד די שווערקייט און דער ביאור פון רש״י איז נאר אין ווארט „לי”⁸]\nמען געפינט אזעלכע לשונות, מיטן זעלבן מכוון (בשייכות צו דעם אויבערשטן) אין פריערדיקע פסוקים „עשר אעשרנו לך”⁹, „קדש לי כל בכור”¹⁰ וכיו״ב, און רש״י באווארנט דארט ניט¹¹ אז דאס מיינט ניט, כפשוטו, „צו” אדער „צוליב” דעם אויבערשטן.\nפון דעם איז מוכח אז ניט דאס איז ביי רש״י שווער אין פשש״מ און ער דארף ניט שולל זיין דעם פירוש הנ״ל. און דאס איז פארשטאנדיק בפשטות, ווייל ווען מ׳איז (מעשר) מקדיש א זאך פאר דעם אויבערשטן מיינט עס ניט אז דער אויבערשטער דארף צו דעם ח״ו אנ־קומען וכיו״ב.",[["1","1","ראה רא״ם, ספר זכרון, פי׳ מהרי״ק, גו״א, באר מים חיים, דבק טוב. ועוד."],["2","2","שני הענינים שבפנים, שאין שייך שיתנו לו, ושאין צריך לשום דבר — הם לכאורה ב׳ ענינים שתלויים בפי׳ „ויקחו לי”, אם מפני שהנתינה היא לו (אליו) או מפני שהנתינה היא לצרכו כביכול; וע״ז הובאו ב׳ הפסוקים דלקמן לענין הא׳ לה׳ הארץ ומלואה ולענין הב׳ אם ארעב גו׳. ובמפרשים הנ״ל מדגישים בעיקר ענין ופי׳ הב׳ (ספר זכרון, באר מים חיים, פי׳ מהרי״ק. ועד״ז בדקדוקי רש״י כאן). ובלבוש האורה ושפ״ח הוא בענין הא׳ דהכל שלו. ול״ע ברא״ם „לא כסתם לי שבמקרא המורה להבאת דבר אל העצם” ומביא פסוק הב׳ (אם ארעב גו׳). ובגו״א הביא ב׳ הפסוקים."],["3","3","תהלים כד, א."],["4","4","תהלים נ, יב."],["5","5","דקדוקי רש״י (באר רחובות) כאן."],["6","6","כי אין לומר שזהו בכדי לציין התחלת הסדרה — כי כמדובר כמ״פ אין דרכו של רש״י בכך (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121078\" data-slug=\"likkutei-sichot\" data-id=\"1300121078\">לקו״ש חי״ב ע׳ 78</a> הערה 2)."],["7","7","ובדפוס א׳ דרש״י, וא׳ מכת״י רש״י — לא העתיק תיבת תרומה בהד״ה."],["8","8","וכמודגש גם בזה שמעתיק בפירושו (עוה״פ) „לי לשמי”. ולהעיר שבדפוס א׳ ובאחדים מכת״י רש״י לא העתיק תיבת „לי” עוה״פ בפירושו. אבל בדפוס שני וברוב הדפוסים וכת״י הוא כבפנים."],["9","9","ויצא כח, כב."],["10","10","בא יג, ב."],["11","11","כמו שהקשה במשכיל לדוד עה״פ."]]],[1300161300,"ב. לכאורה קען מען זאגן אז „ויקחו לי” איז ניט גלייך צום לשון „עשר אעשרנו לך”, „קדש לי” וכיו״ב, ווארום אין „ויקחו לי” שטייט ניט אז מ׳זאל דאס מקדיש זיין צום אויבערשטן וכיו״ב, נאר — „נעמען”; און דאס פאסט ניט¹² מצד די טעמים הנ״ל¹³. דעריבער מוז רש״י זאגן „לי לשמי”. און דערמיט ווערט אויך פארשטאנדיק פארוואס רש״י איז מעתיק אויך דעם ווארט „ויקחו”¹⁴.\nאבער לפ״ז וואלט געווען גלאטער ווען רש״י איז מפרש אז „ויקחו לי” מיינט: זיי זאלן מקדיש זיין (צו מיר¹⁵).\nג. אנדערע מפרשים¹⁶ לערנען אז רש״י׳ן איז דא שווער דער לשון „ויקחו לי”: עס האט געדארפט שטיין „ויתנו לי”¹⁷, און אויף דעם זאגט רש״י „לי לשמי”, און ער מיינט דערמיט צו מרמז זיין אז דורך תרומה נעמט מען דעם אויבערשטן, ע״ד ווי מאמר המדרש¹⁸, אז כאטש לה׳ הארץ ומלואה, וויל ער משכין זיין שכינתו צווישן אידן, אותי אתם לוקחים¹⁹. אבער מ׳קען דאך ניט זאגן אז מ׳נעמט דעם אויבערשטן אליין, ווארום „השמים ושמי השמים לא יכלכלוך גו׳”²⁰, דעריבער זאגט רש״י „לי לשמי”, אז שמו ית׳ איז חל עליהם דורך דער תרומה ובנין הבית (ע״ד „ושמו את שמי על בני ישראל”²¹).\nאבער ווי גערעדט שוין פיל מאל איז רש״י׳ס פירוש וביאור געשריבן אין א קלארן סגנון ביז אז אויך א בן חמש (למקרא) זאל עס קענען פארשטיין (פון זיינע ווערטער גופא, און ניט דארפן אריינקוקן אין מפרשי רש״י). אויב רש״י וואלט געמיינט דעם תוכן הנ״ל, וואלט ער עס מפרש געווען ברור און ניט דורך א רמז מיט׳ן ווארט „לשמי”²².",[["12","12","ואין להקשות מהלשון „קחה לי” (לך טו, ט) שלא ביארו רש״י איך יתכן לגבי הקב״ה — כי י״ל, שמובן הוא מפרש״י שם „ג׳ עגלים רמז לג׳ פרים פר יוהכ״פ כר״י”, וכן בפרש״י לפנ״ז „בזכות הקרבנות כר״י”, שמזה מובן שגם „קחה לי” הוא כענין של קרבן*. וראה ת״א שם „קריב קדמי”, ולא כמו שתרגם בכ״מ „סב”** וכיו״ב. ובתיב״ע שם „סב לי תקרובתין וקריב קדמי”. ועד״ז בפסוק יו״ד שם. וראה פרש״י שם יוד: ואין המקרא יוצא מידי פשוטו לפי שהי׳ כו׳. — ובהפסוקים דפ׳ במדבר (ג, יב־יג. מא. מה) שנאמר לשון לקיחה לי על הלוים, כבר מובן ענינו שהרי נאמר שזה תחת כל בכור ש„הקדשתי לי”. וראה פרש״י בפסוקים הנ״ל. וראה הערה הבאה."],["13","13","משא״כ לשון „לי הוא” — בא שם — שפרש״י „לעצמי קניתים”. ועד״ז במשפטים (כב, ל) „תהיון לי” ופרש״י „הרי אתם שלי” — אין רש״י צריך לבאר, כי לא נאמר ענין של קיחה וכיו״ב."],["14","14","להעיר מהגירסא בדפוס א׳ וכת״י רש״י (הנ״ל הערה 7). ובעוד כת״י (ה״א קלא. ה״א קעג) מעתיק רש״י בהד״ה „ויקחו לי תרומה”, ומפרש „ויקחו לי לשמי”. *) שהוא לה׳ כמפורש כבר בתורה לפנ״ז — מתחיל מקרבן קין כו׳ „מנחה לה׳” (בראשית ד, ג). ועוד. **) בפרשתנו ב„תקחו את תרומתי” — תסבון, וזאת התרומה אשר תקחו מאתם — תסבון. משא״כ בפעם הא׳ „ויקחו לי תרומה” תרגם „ויפרשון קדמי” (וראה הערה 23). אבל בתיב״ע תרגם בכולם „יסבון”, „תסבון”, „תסבון”."],["15","15","ראה לעיל הערה 12."],["16","16","משכיל לדוד בפרש״י. וראה בפי׳ מהרי״ק."],["17","17","ראה גם לבוש האורה, באר מים חיים בפרש״י (אלא שלפירושם קאי על ההפרשה לשמי (וראה לקמן הערה 23))."],["18","18","יל״ש עה״פ (רמז שסג) ממדרש אבכיר."],["19","19","וראה שמו״ר פל״ג, א. שם, ו."],["20","20","מלכים א ח, כז."],["21","21","נשא ו, כז."],["22","22","להעיר שבדפוס ב׳ דרש״י (ועד״ז באחדים מכת״י רש״י) בסיום פרש״י ד״ה תרומה איתא: ומדרש אגדה ויקחו תרומה אין כתיב כאן אלא ויקחו לי כביכול אותי אתם לוקחים שאדור ביניכם."]]],[1300161301,"ד. ווי דערמאנט פריער, איז רש״י דא מעתיק פון פסוק אויך דעם ווארט „תרומה”. און דערפון איז מוכח אז דער הכרח לפירושו „לי לשמי” איז ניט פון די ווערטער „ויקחו לי” אליין נאר אויך פון דעם ווארט „תרומה”. ובהקדים, אז בשעת רש״י׳ס הכרח אויף א פירוש איז פון זיין פירוש אויף א שפעטערדיקן ווארט אין פסוק, איז ער דאן פריער מפרש דעם שפעטערדיקן ווארט פאר זיין פירוש אויפן פריערדיקן ווארט (ווי־באלד אז זיין פירוש המאוחר איז דער יסוד צום פירוש המוקדם).\nולפ״ז: וויבאלד אז דער הכרח אויף „לי לשמי” איז (אויך) פון דעם ווארט „תרומה”, און רש״י איז מפרש „תרומה” נאך זיין פירוש אויפן ווארט „לי”²³, איז דערפון משמע אז דער הכרח אויף „לי לשמי” פון דעם ווארט תרומה איז ניט פארבונדן מיט רש״י׳ס פירוש אויף אט דעם ווארט; ד.ה. ווי מ׳זאל נאר טייטשן דעם ווארט תרומה (אפילו ניט ווי פירוש רש״י — „הפרשה”) וועט עס מכריח זיין אז „לי” מיינט „לשמי”.\nה. דער ביאור אין דעם:\nבפשטות לערנט מען „ויקחו לי”, מ׳זאל דאס מקדיש זיין צום אויבערשטן, ד.ה. אז עס ווערט הקדש, און דאס איז רש״י שולל מיטן מעתיק זיין „ויקחו לי תרומה”.\n„ויקחו” כפשוטו מיינט, אז א זאך ווערט גענומען פון איין ארט אין א צווייטן ארט אדער פון איין רשות אין א צווייטן רשות²⁴.\n„תרומה” קען מען טייטשן, ע״פ פשוטו של מקרא, אויף צוויי אופנים²⁵:\nא) ווי רש״י טייטשט „הפרשה”. עס ווערט אפגעשיידט פון דעם רשות התורם, פון דעם אידן׳ס בעל הבתי׳שקייט, און דורך דער הפרשה (פאר הקדש) באקומט עס א שייכות²⁶ צו הקדש.\nב) הרמה והגבהה. וואס בעת אזא לשון ווערט גענוצט ניט בשייכות צו א גשמיות׳דיקער הרמה, נאר אין מושג פון בעלות וכיו״ב, הייסט עס אז די זאך איז געקומען אין א העכערער רשות ובעלות (וע״ד פרש״י²⁷ אויף „ויקם שדה עפרון” — „תקומה היתה לו שיצא מיד הדיוט ליד מלך”). און בנדו״ד: די זאך איז פריער געווען אין דער בעלות פון א אידן און איז איצט געקומען אין דער בעלות פון הקדש.",[["23","23","לכאורה י״ל דהפירוש ברש״י „תרומה, הפרשה יפרישו לי כו׳” הוא המשך באותו הד״ה „ויקחו לי תרומה”. ולכן בתחילה מפרש תיבת „לי — לשמי”, ואח״כ מפרש „תרומה — הפרשה”. ולאח״ז ממשיך פי׳ הענין „יפרישו לי כו׳” — ע״ד מ״ש בלבוש האורה כאן עה״פ („והי״ק מה היא הלקיחה שנופל עליו לשון לי הוא הפרשה ר״ל בעת שלוקח ומפריש מכיסו מממונו נדבה תהי׳ אותו הלקיחה וההפרשה מכיסו לשמי כו׳”), אבל לפ״ז הוצרך רש״י לומר „יפרישו לשמי”. ומזה שכתב רש״י „יפרישו לי כו׳” מוכח קצת, שהוא פי׳ בפ״ע בתיבת תרומה, ופי׳ „לי — לשמי” בהפסוק הוא ענין בפ״ע, כדלקמן."],["24","24","בריש מס׳ קידושין „גמר קיחה קיחה משדה עפרון כו׳ וקיחה איקרי קנין” — אבל לא הובא בפרש״י עה״ת."],["25","25","אף שעדיין לא למד הבן חמש למקרא תיבת „תרומה” בחומש — הרי הובא בפרש״י משפטים כב, כח. ובכלל הרי״ז תיבה רגילה בלשון הקודש."],["26","26","ויתירה מזו (ע״ד ההלכה עכ״פ) שע״י ההפרשה עצמה נעשה הקדש, ו„כל היכא דאיתי׳ בבי גזא דרחמנא איתא” (ר״ה ו, א. חולין קלט, א). ועד שלדעת ר״ל קדשי „בדק הבית גמרן בהפרשתו ואי משום דלא הביאו ליד גזבר הכל גזברין הן דלה׳ הארץ” (פרש״י חולין שם ד״ה דמיחסר הקרבה)."],["27","27","חיי שרה כג, יז."]]],[1300161302,"עפ״ז איז מובן, אז מ׳קען ניט לערנען אז מיט דעם ווארט (ויקחו) לי מיינט די תורה דאס אוועקגעבן צו הקדש, ווארום די שייכות צו הקדש שטייט שוין אין די ווערטער „ויקחו” „תרומה” וואס מיינען אז דאס באלאנגט איצט צו הקדש (— תרומה) ס׳געפינט זיך אין רשות פון הקדש (— ויקחו)²⁸.\n[דער חילוק אין דעם בהתאם צו די צוויי פירושים אין תרומה איז נאר: אויב „תרומה” איז מלשון הרמה והגבהה — דאן שטייט דער ענין אז דאס ווערט אין דער בעלות פון הקדש נאר אין דעם ווארט „תרומה” און „ויקחו” וועט מיינען נאר דעם ענין פון שינוי רשות, אז דאס געפינט זיך אין רשות פון הקדש; און אויב דער פירוש „תרומה” איז מלשון הפרשה, דעמאלט דארף מען זאגן²⁹ אז „ויקחו” מיינט ניט נאר דעם שינוי רשות, נאר — דורך דעם ווערט אויך די שלימות הבעלות פון הקדש].\nאון דעריבער זאגט רש״י אז „לי” דא מיינט ניט אז עס ווערט דעם אויבערשטנ׳ס הקדש (ע״ד ווי „קדש לי” וכיו״ב), נאר ס׳איז א נייער באזונדערער ענין³⁰ — אז עס דארף זיין „לשמי”. דאס הייסט, אז נוסף אויף דער נתינה צו הקדש, זאל זיין נאך אן ענין: כוונה לשמה (ע״ד די כוונה לשמה ביי גט, ס״ת וכו׳) — אז ביים געבן צו הקדש זאל מען מכוון זיין אז מ׳גיט עס „לשמי”.\nו. עפ״ז יש לומר — אין די „ענינים מופלאים” ע״ד ההלכה שברש״י — אז אין דעם ענין הנ״ל (אז ביי די תרומות הנ״ל איז דא א דין פון כוונה „לשמי”) גייט רש״י לשיטתו בפירושו על הש״ס:\nעס שטייט אין משנה³¹ „אחד קדשי מזבח ואחד קדשי בדק הבית אין משנין אותן מקדושה לקדושה”. איז דא אין דעם א פלוגתא פון רמב״ם מיטן ראב״ד³²: דער רמב״ם לערנט אז דער דין איז אויך בנוגע צו בדק הבית גופא — „אם הקדיש לבדק ההיכל לא ישנה לבדק המזבח³³ וכן כל כיוצא בזה”; דער ראב״ד אבער קריגט אויפן רמב״ם און האלט — „אין שינוי בין קדשי היכל לשאר עזרות ולא למזבח”, און ער איז מבאר אז דער דין אין משנה איז נאר ביי קדשי מזבח, אז „קדשי מזבח אפילו מקדשים קלים לחמורים אין משנים ואין ממעטים באכילת קדשים, אבל בדק הבית מה יש בין זה לזה”.",[["28","28","ולהעיר מרע״ב וצדה לדרך כאן דקושיית רש״י דמלת לי היא מיותרת, אלא שהרע״ב מפרש (וראה צדה לדרך) „להשמיענו שתהא התרומה לי כלומר מקודשת לשמי”, היינו שיהי׳ בשביל הקדש ולא הפרשה סתם, ועד״ז בלבוש האורה. ועוד. משא״כ המבואר לקמן בפנים."],["29","29","אבל לא להנ״ל הערה 26."],["30","30","בפי׳ מהרש״ל (הובא בצדה לדרך כאן): „שקשה לרש״י שאין הלשון ויקחו נופל על לשון דבר אל בני ישראל אלא הול״ל קחו לכן פירש ויקחו לי לשמי כלומר לא על עצם הקיחה הוא רק שיהי׳ הקיחה לשמו”. אבל לפ״ז: א) לא הול״ל לרש״י להעתיק גם תיבת „תרומה”. ב) הול״ל לפרש בפירושו „ויקחו לי לשמי”, וכהגירסא בהערה 14."],["31","31","תמורה לב, א."],["32","32","הל׳ תמורה פ״ד הי״א."],["33","33","בגדר קדושת היכל י״ל שלהרמב״ם נכללה גם מחיצת העזרה — ראה רמב״ם הל׳ בית הבחירה (פ״א ה״ה): „ועושין מחיצה אחרת סביב להיכל רחוקה ממנו כעין קלעי החצר שהיו במדבר וכל המוקף במחיצה זו שהוא כעין חצר אהל מועד הוא הנקרא עזרה”. דלכאורה מחיצה זו היא בשביל העזרה (מקום שבו עומד המזבח) ולמה קוראו „מחיצה אחרת סביב להיכל” כו׳, ובפרט שהוא מיותר לכאורה? וי״ל דדינא קמ״ל בזה דמחיצה זו היא בשביל ההיכל וא״כ קדושת היכל נכלל בה. ואם הקדיש לבדק היכל נכלל בזה גם מחיצה זו, ועפ״ז גם ע״ז הדין דלא ישנה לבדק המזבח (וראה כס״מ הל׳ תמורה שם)."]]],[1300161303,"רש״י בפירושו על הש״ס איז מפרש די משנה הנ״ל: „דקדשי בדק הבית שהקדישם למזבח לא עשה כלום) ובקדשי מזבח אין משנין מקדושת עולה לשלמים ומשלמים לעולה” — אבער ניט אין קדושת בדק הבית גופא (כשיטת הראב״ד).\nויש לומר אז דאס איז אויך פארבונדן מיטן דין הנ״ל³⁴ אז די נתינה³⁵ דארף זיין „לשמי”³⁶: וויבאלד ער איז מכוון אז ער גיט עס „לשמי” — פארן אויבערשטן — איז דא ניט (אזוי) נוגע דער ענין פרטי אויף וועלכן ער האט דאס מקדיש געווען, אבי עס איז „לשמי” עס „קומט אן” צום אויבערשטן. און דערפאר, אויב ער איז דאס מקדיש פאר בדק ההיכל, מעג מען דאס משנה זיין צו בדק המזבח וכיו״ב, ווייל די כוונה „לשמי”³⁷ איז דאס (ניט קיין „לשמי” פרטי פון היכל, נאר) א כוונה כללית „לשמי” פון בדק הבית.\nז. אויף דעם דין הנ״ל — אז מען דארף מכוון זיין ביי דער נתינה „לשמי” — קען מען אבער פרעגן:\nצווישן די תרומות וועגן וועלכע עס רעדט זיך אין דעם פסוק איז דאך אויך תרומת המזבח לקנות מהן קרבנות צבור (ווי רש״י זאגט אויפן פסוק — „אמרו רבותינו ג׳ תרומות אמורות כאן”); ולכ־אורה: בנוגע צו תרומת המזבח איז דער דין³⁸ אז מ׳נעמט עס בעל כרחו און ממשכנין על השקלים, היינט ווי זאגט מען אויף דעם אז עס דארף זיין „לשמי” — א נתינה בע״כ איז דאך ניט מיט זיין כוונה בכלל, ופשיטא — ניט מיט דער כוונה „לשמי”³⁹?\nאויך: עס בלייבט נאך שווער די קושיית המפרשים הנ״ל — פארוואס שטייט דא „ויקחו לי” און ניט „ויתנו לי”?\nויש לומר, אז די קשיות ווערן פאר־ענטפערט חדא בחבירתא: דער דין פון „לשמי” (בנוגע צו תרומת המזבח עכ״פ) איז ניט אין דער נתינה — אז דער איד",[["34","34","דתרומת המשכן (המדובר בפרשתנו) הוא של בדק הבית (ראה מגילה כט, ב). ואף שבפרשתנו מדובר בתרומת המשכן (בדק הבית) סתמית, משא״כ ברמב״ם שם שאיירי בהקדיש (בפירוש) לבדק ההיכל כו׳ — מ״מ י״ל דגם בזה מהני לדעת רש״י הכוונה ד„לשמי” כבפנים."],["35","35","ראה לקמן סעיף ז׳."],["36","36","ואף שפירש״י להלן (ד״ה תקחו): ג׳ תרומות אמורות כאן א׳ תרומת בקע לגולגולת שנעשו מהם האדנים כו׳ ואחת תרומת המזבח כו׳ ואחת תרומת המשכן (וא״כ „ויקחו לי” נאמר רק בתרומה הא׳ — תרומת האדנים) — הרי (אף את״ל דרש״י חשבן כפי הסדר שהם כתובים בתורה (כבירוש׳ שקלים פ״א ה״א) ו„ויקחו לי תרומה” קאי על תרומת האדנים (ראה משכיל לדוד) —) דוחק לומר שהדין ד„לשמי” הוא רק בתרומת האדנים. ועוד ועיקר: הרי כתב רש״י ע״ז (ד„ג׳ תרומות אמורות כאן”) „אמרו רבותינו”, אבל בפשטות, הפרשה כאן מדבר ע״ד תרומת המשכן וע״ז קאי גם „ויקחו לי תרומה”. וראה מפרשי רש״י פסוק ג׳."],["37","37","בנוגע להשינוי מתרומה א׳ לב׳ (כגון: מתרומת המשכן (בדק הבית) ל(שקלים עבור) קרבנות צבור) — יל״ע בדעת רש״י בפשש״מ אם גם בזה מהני הדין ד„לשמי” שאפשר לשנות או לא. ע״ד ההלכה — ראה: רמב״ם וראב״ד הל׳ שקלים פ״ד ה״י (וצפע״נ שם וה״ח). ספ״ב מהל׳ ערכין ובמפרשי הרמב״ם שם. צפע״נ שם. מפרשי הירושלמי ספ״ה דשקלים. ועוד. ולהעיר מפרש״י ריש פרשתנו (פסוק ג׳ בסופו): ושאר הכסף הבא שם בנדבה עשאוה לכלי שרת. וראה כתובות קו, ב ובתוד״ה וכי שם. נ״כ הרמב״ם הל׳ שקלים שם ה״ב. ואכ״מ."],["38","38","שקלים פ״א מ״ג. מ״ה. אבל לא הובא בפרש״י כאן או בפ׳ תשא."],["39","39","בפשטות הכתובים אינה קשיא כי הג׳ תרומות רק נרמזו בהג׳ לשונות דתרומה. אבל בפשטות מדבר בהתרומה למלאכת המשכן (כנ״ל הערה 36) שבאה בנדיבות לבו של כ״א."]]],[1300161304,"דארף עס געבן „לשמי” — נאר אין דעם „ויקחו”, אין דער „לקיחה” פון די גזברי ההקדש, אז זיי דארפן עס נעמען פון די אידן „לשמי”⁴⁰.\n[וואס דאס זיינען די צוויי לשונות, „דבר אל בני ישראל ויקחו לי תרומה מאת כל איש גו׳”: „דבר אל בני ישראל” גייט אויף די וואס האבן גענומען די תרומות — די גזברין, און „כל איש גו׳” אויף אלע אידן וואס גיבן כו׳].\nאון דערפאר איז ניט קיין סתירה ווען די נתינה פון דעם אידן איז בע״כ — ווייל דער „ויקחו” די לקיחה פון די גזברין, איז „לשמי”.\nח. מען דארף נאך אבער פארשטיין בפנימיות הענינים:\nוויבאלד אז די תרומה (מחצית השקל) קען זיין אויך בע״כ פון דעם נותן, הייסט עס דאך, אז ביי דער תרומה זיינען ניט נוגע קיין כוונות (ניט ווי ביי דער תרומה למלאכת המשכן וואס ווערט געגעבן בלויז בנדיבות הלב), ס׳איז בלויז נוגע אז ס׳זאל אנקומען צו הקדש, היינט פארוואס דארף מען דערביי דעם „לשמי” פון די גזברים וואס נעמען די תרומות?\nבפשטות י״ל, אז דאס איז ע״ד מאמר רז״ל⁴¹ אז „פרנס אל יטיל אימה על הצבור שלא לשם שמים”: וויבאלד אז זייער ארבעט איז נעמען ביי די אידן די תרומות (אפילו) בע״כ, איז דערביי במיוחד וויכטיק אז עס זאל זיך ביי זיי ניט אריינמישן קיין שום פני׳, דארף מען דעריבער באווארענען זייער לקיחה אז זי זאל זיין „לשמי”, פאר דעם אויבערשטנ׳ס וועגן.\nדאס איז אבער ניט גלאטיק: לפ״ז איז דער ענין פון „לשמי” ניט נוגע צו (דער לקיחה פון) דער תרומה, נאר צו די גזברין, אז ביי זיי דארף עס זיין לש״ש; פון פשטות הלשון והענין איז אבער משמע אז ס׳איז נוגע אין (דער לקיחה פון) דער תרומה אז זי זאל זיין „לי — לשמי”.\nט. איז דער ביאור אין דעם:\nדי נתינת התרומה איז געווען פאר דעם משכן און די קרבנות, אויף מאכן אין דעם משכן א דירה לו ית׳ ועל ידו — בכל העולם כולו.\nאין דער עשי׳ פון א דירה, זי זאל זיין ראוי פאר א דירת מלך, דארפן זיין צוויי ענינים „צריכים לפנות ההיכל מכל לכלוך . . ואח״כ לסדר שם כלים נאים”⁴². וואס אין עבודת ה׳ זיינען דאס די צוויי ענינים פון סור מרע ועשה טוב. דער חילוק צווישן זיי איז: די עבודה פון סור מרע איז (נאר) א הכנה והקדמה צו עשיית הדירה; די עשיית הדירה בפועל — די המשכת אלקות אין דברים גשמיים זיי זאלן ווערן א דירה פאר דעם אויבערשטן — דאס איז דורך „ועשה טוב”⁴².\nאון דעריבער איז דא א חילוק צווישן דעם אופן העבודה פון סור מרע ועשה טוב, כמבואר אין חסידות⁴³: אין דער עבודה פון סור מרע איז נוגע בעיקר דער בפועל, ס׳איז ניט אזוי נוגע אין וואס פאר אן אופן ער פועל׳ט בא זיך",[["40","40","ראה אברבנאל, ספורנו עה״פ. וראה העמק שאלה לשאילתות ריש פרשתנו."],["41","41","ר״ה יז, א. ספר חסידים סי׳ קמה."],["42","42","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו״ת בלק ע, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380459\" data-slug=\"likkutei-torah\" data-id=\"4001380459\">וראה שם שלח לו, ד</a>. ובכ״מ."],["43","43","ד״ה ויחלום תש״ח פ״ג ואילך."]]],[1300161305,"ניט צו עובר זיין אויפן רצון העליון, אפילו אויב ער טוט עס לגרמי׳ ומיראת העונש וכיו״ב; משא״כ בא ועשה טוב איז וויכטיק אז דאס זאל זיין לשמה, ער זאל עס טאן מיט דער שלימות׳דיקער כוונה פאר דעם אויבערשטן, ניט צוליב זיך, וויבאלד אז דורך דעם איז ער ממשיך אלקות למטה, ער מאכט א דירה לו ית׳ בתחתונים, דארף די מעשה זיין ווי עס דארף זיין עס זאל אין דעם שורה זיין אלקות (ובמילא טאר זיך אין דעם ניט אריינמישן קיין פני׳ ח״ו).\nאון דעריבער זאגט מען⁴⁴ „לעולם יעסוק אדם בתומ״צ אע״פ שלא לשמה שמתוך שלא לשמה בא לשמה”, אז דער טעם וואס עס דארף זיין דער עסק אפילו שלא לשמה, איז ניט ווייל אויך די עבודה איז מספיק (דהמעשה הוא העיקר⁴⁵), נאר ווייל ער וועט עי״ז סו״ס קומען צום מכוון ותכלית, עבודה לשמה, וואס דעמאלט ווערט די שלימות הדירה בתחתונים⁴⁶.\nיו״ד. כשם ווי דאס איז אין עבודת האדם, עד״ז איז דאס אויך אין עניני הבריאה וואס פון זיי מאכט מען דעם משכן לו ית׳, אז אין דערויף זיינען דא די ביידע ענינים:\nא) דער סור, דאס ארויסגיין פון רשות פון „וועלט” וואס געפינט זיך תחת ממשלת קליפת נוגה⁴⁷ — בדוגמת ענין סור מרע, ב) דאס אריינגיין אין רשותו של הקב״ה, עס ווערט ועי״ז א מקום משכן פאר דעם אויבערשטן — דוגמת ענין ועשה טוב.\nאון עפ״ז איז מובן, אז כאטש ממשכנין על השקלים, די נתינה איז בע״כ של הנותן — ווייל אין דעם ענין פון סור מרע מוז ניט זיין קיין כוונה (לשמי), עס איז בעיקר נוגע דער בפועל, צונעמען פון ממשלת קליפת נוגה — איז אבער די לקיחה, שע״י הגזבר, וואס דורכדעם גייט דאס אריין אין רשות ההקדש, דארף זיין „לשמי”.\nיא. די צוויי ענינים זיינען מבואר אין די צוויי טייטשן אין ווארט „תרומה” (כנ״ל) — הפרשה און הרמה והגבהה:\nהפרשה, וואס מיינט כפשוטו אז עס ווערט אפגעטיילט פון אן אנדער חלק מיט וואס דאס איז געווען מעורב⁴⁸, ווייזט אויף דער פרישה פון עניני חול. און אזוי איז עס אויך בשייכות להאדם, אז דאס ווערט מופרש פון זיין רשות; און דער פירוש פון הרמה והגבהה מיינט כנ״ל, אז דאס ווערט אויפגע־הויבן, גייט אריין אין רשות הקדש.\nאון דאס איז רש״י מרמז מיטן שרייבן „לי לשמי” נאכן מעתיק זיין „ויקחו לי תרומה”, פאר זיין פירוש „תרומה הפרשה” (ומובן, אז פאר זיין פירוש „תרומה הפרשה” טייטשט מען תרומה כפשוטה ממש — לשון הרמה) — ווייל דער ענין פון „לשמי” איז וויכטיק (בעיקר⁴⁹) אין דעם ענין ההרמה, אין דער כניסה לרשות הקדש, און ניט אזוי אין דעם ענין פון הפרשה פון רשות הדיוט.\nיב. די הוראה דערפון אין עבודת ה׳:\nבשעת א איד גייט באווירקן א צווייטן",[["44","44","פסחים נ, ב. וש״נ. הל׳ ת״ת לאדה״ז פ״ד ס״ג."],["45","45","אבות פ״א מי״ז."],["46","46","ראה גם לקו״ש ח״ה ע׳ 245 הערה 37."],["47","47","<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ״ז</a>."],["48","48","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091168\" data-slug=\"likkutei-sichot\" data-id=\"1300091168\">לקו״ש ח״ט ע׳ 168</a>."],["49","49","אבל טובה גם בההפרשה (שנעשית ע״י הגיזברין בלקיחתם) — שלכן קיים הפי׳ „לי לשמי” גם לאחרי שפרש״י „תרומה הפרשה”."]]],[1300161306,"אידן, אים מקרב צו זיין צו תורה ומצוות, ער גייט מקיים זיין די מצוה פון הוכח תוכיח את עמיתך⁵⁰, קען ער ביי זיך טראכטן: בשלמא ווען עס רעדט זיך וועגן זיין אייגענעם קיום התומ״צ איז וויכטיק אז זיין עבודת ה׳ זאל זיין כדבעי „לשמה”: בשעת עס רעדט זיך אבער וועגן פועל זיין אויף א צווייטן, איז דאך נוגע בעיקר דער בפועל — אז יענער זאל אנהייבן לייגן תפלין, זיך אפהאלטן פון אן עבירה, וכיו״ב: אבער דער אופן ווי ער פועל׳ט דאס אויף יענעם איז לכאורה ניט (אזוי) נוגע. קען זיך אין זיין תוכחה אריינמישן א הרגש היפך פון אהבת ישראל, אדער עכ״פ בדקות דער הרגש אז ער איז דער מוכיח, ער איז שענער פארן צווייטן א.ז.וו.\nער ווייסט טאקע אז דאס איז א חסרון אין זיין עבודת ה׳, ער איז נאך ניט קיין מבורר און ביי אים איז נאך דא א הרגש פון ישות — אבער וואס האט עס צו טאן מיטן צווייטן? קבל האמת ממי שאמרו⁵¹, ובפרט בנוגע לסור מרע איז דאך זיכער ניט נוגע די כוונה, כנ״ל.\nאויף דעם איז די הוראה, אז אט דער חשבון איז נאר פארן צווייטן — ער דארף ווילן אנטלויפן פון רע אויף וועלכן וועג ס׳זאל נאר זיין: דער אבער וואס גייט פועל׳ן על זולתו איז אויך ווען עס האנדלט זיך וועגן סור מרע, דארף ער עס טאן „לשמה”, ווייל זיין פעולה אויף א צווייטן איז ביי אים אלעמאל אן ענין פון „ועשה טוב”, אן ענין חיובי וואס דארף זיין „לשמה”: ובפרט נאך אז מ׳זעט אז ווען עס פעלט בא אים דער ריינער „לשמה”, עס מישט זיך אריין אייגענע פני׳ וכיו״ב, דעמאלט פעלט ניט נאר אין זיין עבודה, נאר עס פעלט אויך אין דער פעולה (כדבעי) אויפן צווייטן.\nאון דעריבער איז אל יטיל אימה על הצבור שלא לשם שמים אויך בנוגע צו א זהירות אין סור מרע וכיו״ב, ווייל ווי־באלד ס׳איז אין דעם אריינגעמישט א הרגש הפכי, וועט זיך דורכדעם ניט אויפטאן דער מכוון כדבעי.\nבשעת אבער ער טוט זיין עבודה „לשמי” — אפילו ווען דאס איז בע״כ, פארבונדן מיט א פעולה של כפי׳ — מעשין על הצדקה וכיו״ב — איז „שכרו גדול משכר הנותן שנאמר והי׳ מעשה הצדקה שלום ועל גבאי צדקה וכיוצא בהם אומר ומצדיקי הרבים ככוכבים”⁵², און „גדולה צדקה (כולל גם צדקה זו) שמקרבת את הגאולה”⁵³.\n(משיחת ש״פ תרומה תשכ״ה)",[["50","50","קדושים יט, יז."],["51","51","פיהמ״ש הקדמה לאבות (העתקת קאפח). הרמ״א בהקדמתו למחיר יין."],["52","52","רמב״ם הל׳ מת״ע פ״י ה״ו. מב״ב ט, א."],["53","53","ב״ב יוד, א."]]],[1300161307,"<h3>תרומה ב</h3>\nא. דער ציווי צו נעמען „תרומה” פון אידן (פאר עבודת המשכן) ווערט איבערגעחזר׳ט דריי מאל אין אנהויב פון אונזער סדרה1: „ויקחו לי תרומה”, „תקחו את תרומתי”, „וזאת התרומה אשר תקחו”. זאגן דערויף חז״ל2: ג׳ תרומות נאמרו בפרשה הזאת כו׳ ויקחו לי תרומה וגו׳ זו תרומת אדנים, מאת כל איש אשר ידבנו לבו תקחו את תרומתי זו תרומת שקלים, וזאת התרומה אשר תקחו מאתם זו תרומת המשכן.\nעס איז אבער דא א חילוק ווי די ג׳ תרומות שטייען דא: די ערשטע צוויי שטייען בלויז בכלל וברמז (און די פרטים וועגן זיי — שטייען ערשט אין שפעטערדיקע סדרות<sup data-n=\"3\">3</sup>; אבער תרומת המשכן ווערט דא געזאגט בפרטיות ובאריכות.\nדארף מען פארשטיין: וויבאלד אז אלע ג׳ תרומות זיינען געווען צוליב עבודת המשכן\n[און אפילו תרומת השקלים וואס מ׳האט גענוצט אויף קויפן דערמיט די קרבנות ציבור4 — איז דאך לויטן פסק הרמב״ם5, אז די מצוה פון בנין המקדש איז, אז עס זאל זיין (ניט בלויז) א „בית לה׳” (נאר אז עס זאל זיין) מוכן להיות מקריבין בו הקרבנות”, קומט אויס, אז דער ציווי „ועשו לי מקדש”6 נעמט ארום אויך די הכנות וואס פאדערן זיך צוליב עבודת הקרבנות, כולל אויך דעם נוצן תרומת השקלים אויף צו קויפן די קרבנות ציבור] —\nהאבן דאך אלע דריי תרומות געדארפט שטיין דא בפרטיות ובפירוש?\nאפילו מ׳זאל וועלן פארענטפערן בנוגע תרומת השקלים, אז וויבאלד זי איז פארט ניט פארבונדן מיט בנין המשכן (בפועל), נאר ס׳איז בלויז א הכנה צו דער עבודה במשכן, דערפאר איז ניט דא (אין פ׳ תרומה) דער ארט אויף צו זאגן די פרטים וועגן דער תרומה7 — בלייבט אבער שווער בנוגע תרומת האדנים, וואס זיינען א טייל פון בנין המשכן: פארוואס שטייט ניט",[["1","1","כה, ב־ג."],["2","2","ירושלמי שקלים פ״א ה״א. הובא בפרש״י עה״ת ריש פרשתנו."],["3","3","תרומת האדנים — „כמו שמפורש באלה פקודי” (פרש״י ריש פרשתנו. וראה פקודי לח, כה ואילך): תרומת השקלים — תשא שם, יג ואילך (ובפרש״י שם, טו). ואף שלפרש״י בפרשתנו (עה״פ), ה„כסף” הנמנה כאן הוא המחצית השקל שנתנו עבור תרומת האדנים — הרי לא נמנה כענין (ותרומה) בפ״ע [נוסף לזה, שלא נתפרש (כבפ׳ פקודי) שכ״א מבן עשרים שנה ומעלה גו׳ נתן (רק) מחה״ש ושהי׳ בשביל האדנים], ואדרבה — נזכר כפרט בכללות תרומת המשכן. ואפילו הפרט „וכסף” — כולל ג״כ הכסף שממנו נעשו כלי שרת וכו׳ (פרש״י שם). וראה לקמן ע׳ 429."],["4","4","פרש״י ריש פרשתנו. תשא ל, טו. שקלים רפ״ד. רמב״ם הל׳ שקלים רפ״ד."],["5","5","ריש הל׳ בית הבחירה. ועד״ז בספר המצות מ״ע כ. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111128\" data-slug=\"likkutei-sichot\" data-id=\"1300111128\">לקו״ש חי״א ס״ע 120</a> ואילך."],["6","6","פרשתנו שם, ח."],["7","7","להעיר מפרש״י ריש פרשתנו (בנוגע לתרומת המשכן) „י״ג דברים האמורים בענין כולם הוצרכו למלאכת המשכן או לבגדי כהונה”, ובאוה״ת פרשתנו (ע׳ א׳שצ. א׳שפג. א׳תי. א׳תיד. וראה עד״ז ברע״ב וש״ך עה״ת כאן): „לא מנה רק הדברים השייכים למלאכת המשכן ולכלי המשכן, משא״כ שמן למאור ובשמים אינו מכלי המשכן כ״א ע״ד הקרבנות שבמשכן”."]]],[1300161308,"במפורש ובפרטיות וועגן דער תרומה אין אונזער סדרה?\nב. עס איז דא נאך א חילוק אין לשון הכתוב דא8 ביי די ג׳ תרומות:\nביי תרומת האדנים שטייט „ויקחו לי תרומה”; ביי תרומת השקלים — „תקחו את תרומתי”; און ביי תרומת המשכן — „וזאת התרומה אשר תקחו”. דאס הייסט: ביי דער ערשטער תרומה (האדנים) איז די שייכות פון דער תרומה צום אויבערשטן מודגש אין א באזונדער ווארט — „לי תרומה”; ביי דער צווייטער תרומה (שקלים) — ווערט די שייכות צום אויבערשטן איינגעשלאסן אין דעם ווארט „תרומה” גופא — „תרומתי”9; און ביי דער דריטער תרומה (המשכן) ווערט איבערהויפט ניט דערמאנט אז זי איז תרומה לה׳, עס שטייט סתם „וזאת התרומה”.\nג. אויך א דבר פלא וואס מען געפינט אין מדרש בפרשתנו:\nאויפן פסוק „וזאת התרומה אשר תקחו גו׳ זהב וכסף ונחושת” זאגן חז״ל10: זהב כנגד מלכות בבל כו׳ כסף כנגד מלכות מדי כו׳ ונחושת כנגד מלכות יון כו׳ ועורות אלים מאדמים כנגד מלכות אדום כו׳”.\nאיז תמוה ביותר: וואס פאר א קשר ושייכות איז דא צווישן ד׳ מלכיות און תרומת המשכן? אדרבא — די ד׳ מלכיות האבן דאך געבראכט די ד׳ גליות און דעם חורבן בית המקדש, וואס דאס איז דער היפך פון תרומת המשכן, וואס ענינה איז — ועשו לי מקדש (בנין והקמת המשכן)?\nד. וועט מען דאס פארשטיין בהקדים, אז די עבודה רוחנית פון ועשו לי מקדש (דירה לו ית׳ בתחתונים) — איז איינגעטיילט אין דריי סוגים — עמודים: תורה, עבודה וגמילות חסדים*10.\nאון וויבאלד אזוי איז פארשטאנדיק, אז די דריי סוגים כללים הנ״ל זיינען מרומז אינעם ענין המשכן.\nויש לומר, אז דאס איז דער טעם פנימי11 פארוואס מ׳האט גענומען דריי באזונדערע תרומות — און ניט איין תרומה (כוללת) פאר אלע צרכי המשכן — ווייל די ג׳ תרומות זיינען כנגד די ג׳ עמודים12 תורה עבודה וגמ״ח13:\nדער יסוד ומקור פון אלע עניני עבודת ה׳ איז (דער עמוד פון) „תורה”. אלע פרטי מדריגות און אופנים אין דינען דעם אויבערשטן דורך מצות ומעשים טובים זיינען מיוסד און געבויט אויף תורה, יעדער ענין פון אידישקייט און קיום המצות האט זיין מקור און",[["8","8","משא״כ בפ׳ תשא, שבג׳ התרומות המרומזות שם (ירושלמי שקלים פ״א שם. פרש״י תשא שם) נאמר בהן „תרומה לה׳” או „תרומת ה׳”."],["9","9","להעיר מתקלין חדתין לירושלמי שם (ועד״ז במשכיל לדוד בפרש״י כאן) דלמדין דתקחו את תרומתי קאי על תרומת השקלים (קרבנות לגבוה) מדכתיב „תרומתי כלומר תרומה שלי”."],["10","10","תנחומא פרשתנו ז. וראה שמו״ר פל״ה, ה. *10) אבות פ״א מ״ב."],["11","11","כי בפשטות מובן שידיעת מנין בנ״י אפשרית רק ע״י תרומה בפ״ע."],["12","12","להעיר מרבנו בחיי פרשתנו כה, ב: „שלש תרומות שהעולם נתרומם (נתרם) בהם .. ונרמז במעשה המשכן לפי שהמשכן שקול כבריאת העולם כו׳” — והרי תורה עבודה וגמ״ח הם הדברים שעליהם העולם עומד (אבות שם)."],["13","13","המבואר בפנים בענין ג׳ התרומות הוא ע״פ המובן מאוה״ת ד״ה ויקחו לי תרומה (ע׳ א׳שנט ואילך) ד„ויקחו לי תרומה” קאי על תורה, ו„מאת כל איש אשר ידבנו לבו תקחו את תרומתי” קאי על תפלה. ושם (ע׳ א׳תיג) „פי׳ וזאת התרומה לפי מדרש זה (— המדרש שהובא לעיל סעיף ג) קאי על בירור ק״נ .. ע״י מצות מעשיות כו׳”."]]],[1300161309,"אנהויב אין תורה — און דאס איז מרומז אין תרומת האדנים, וואס זיי זיינען דער יסוד פון משכן.\nתרומת השקלים, פון וועלכער מ׳האט געקויפט קרבנות ציבור, איז דער קו פון „עבודה” (וואס דאס איז עבודת הקרבנות14, און תפלה שבמקום קרבנות תקנום<sup data-n=\"15\">15</sup>;\nאון תרומת המשכן, וואס נעמט ארום די אלע דברים גשמיים (זהב וכסף ונחושת וגו׳) פון וועלכע מ׳האט געבויט דעם משכן, איז כנגד דער עבודה פון מצות (וועלכע מ׳איז מקיים דורך זהב וגו׳) און וואס כללותם איז גמילות חסדים [כידוע16, אז גמילות חסדים איז „כללות המצות”].\nלויט דעם ביאור אין די חילוקים צווישן די דריי עניני עבודה הנ״ל, וועט ווערן פארשטאנדיק דער טעם השינויים הנ״ל (סעיף ב׳) ביי די ג׳ תרומות.\nה. דער אונטערשייד צווישן די דריי קוין — תורה עבודה וגמ״ח — איז:\nתורה איז ואהי׳ אצלו אמון גו׳ שעשועים גו׳ לפניו גו׳17, חמדה גנוזה18 פון דעם אויבערשטן וקדמה לעולם אלפיים שנה19, איידער דער איד לערנט איר (ניט ווי מצות, וואס גדר המצוה איז שייך נאר בצירוף מיט דעם מקיים המצוה; כל ענין המצות (ציווים) איז אן אנזאג צו א מענטש). און אויך ווען תורה קומט אראפ למטה און ווערט געלערנט דורך דעם אדם, בלייבט זי (בלשון חז״ל*<sup data-n=\"19\">19</sup> „דברי כאש” (פון אויבערשטן), וואס ווערט ניט נשתנה דורך דעם וואס זי ווערט נתלבש אין שכל ודבור האדם; זי בלייבט חכמתו של הקב״ה, וואס איז באין ערוך העכער פון דעם אדם הלומד.\nדער ענין פון „עבודה” (קרבנות — תפלות) איז — „אדם20 כי יקריב מכם” דער אדם איז זיך מקרב צום אויבערשטן: כידוע21 אז „קרבן” איז פון לשון קירוב — „דאמאי אקרי קרבן ע״ש שמקרב” — „קירוב הכחות והחושים” צום אויבערשטן. און עבודת התפלה (וואס במקום קרבנות תקנום) — איז דאך עבודה שבלב22, דאס וואס דער אדם הויבט זיך אויף (מיט זיינע כחות) צו אלקות, ביז אז „ראשו מגיע השמימה”23.\nאון וויבאלד אז דאס איז די עבודה פון דעם אדם, איז אע״פ אז ער קען זיך אויפהויבן נאר וויפל דאס איז בכחו פון א נברא, ווערט ער אבער מיוחד מיט דעם אור הקדושה צו וועלכער ער דערגרייכט24.",[["14","14","רש״י, רע״ב ועוד לאבות שם."],["15","15","ברכות כו, ב. וראה רבנו יונה לאבות שם."],["16","16","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380810\" data-slug=\"likkutei-torah\" data-id=\"4001380810\">לקו״ת ראה כג, ג</a>. וראה אגה״ק סי׳ לב: וכל הגוף נכלל בימין."],["17","17","משלי ח, ל."],["18","18","שבת פח, ב."],["19","19","מדרש תהלים צ, ד. ב״ר פ״ח, ב. תנחומא וישב ד. זח״ב מט, א. *19) ירמי׳ כג, כט. ברכות כב, א."],["20","20","ויקרא א, ב. וראה לקו״ת ויקרא ב, ג ואילך."],["21","21","ספר הבהיר סי׳ מו (קט). ועייג״כ זח״ג ה, רע״א. שלי״ה מס׳ תענית (ריא, ב). פע״ח שער התפלה פ״ה. בחיי ויקרא א, ט. וראה רמב״ן שם. ד״ה טעמה תש״ט פ״ב ואילך. ד״ה באתי לגני ה׳שי״ת פ״ב. ובכ״מ."],["22","22","תענית בתחלתה."],["23","23","ויצא כה, יב. וקאי על קרבנות (ב״ר פס״ח, יב) ותפלה (זח״א רסו, ב. זח״ג שו, ב. תקו״ז תי׳ מה)."],["24","24","ע״ד המבואר (ד״ה זכור תרס״ה פ״י (סה״מ תרס״ה ע׳ רכא). ועד״ז ד״ה זה תרנ״ד (סה״מ תרנ״ד ע׳ קצו)) יתרון המעלה בקיום המצות דהאבות שהיו בבחי׳ כלים ממש לאלקות, משא״כ בתורה ומצות שלנו גם אם מכוון כו׳ הז״ז רחוק מאד מהביטול דהאבות וההמשכה שעי״ז הוא „רק אור מקיף לבד בבחי׳ ריחוק כו׳”. וראה שם שזהו ה„הפרש בין מלמטה למעלה ובין מלמעלה למטה”, והרי — זהו החילוק בין תורה ותפלה."]]],[1300161310,"אין די צוויי עבודות — תורה ועבודה — איז דא א צד השווה, אז ביי זיי ביידע איז די התעסקות פון דעם אדם העובד אין און מיט זיך; און אזוי איז אויך זייער אויפטו נאר אין דעם אדם (אז זיין שכל ווערט מיוחד מיט שכל התורה, חכמתו ית׳; און אז ער ווערט דערהויבן ביז „שמימה”) — אבער ס׳איז ניטא אין דעם א התעסקות מיט די דברים גשמיים, אז אויך זיי זאלן ווערן תשמישי קדושה, דבר שבקדושה — א חפץ גשמי זאל ווערן א חפץ מצוה, דורכגעדרונגען מיטן אור הקדושה.\n[אפילו ביי עבודת הקרבנות כפשוטה, וואס מ׳האט מקריב געווען א בהמה גשמית אויפן מזבח, איז דאס אבער ניט אין אן אופן אז מ׳האט מקריב געווען דעם גשם ווי ער איז אין זיין מצב, נאר מ׳האט עס פריער געדארפט מקדיש זיין, דאס הייסט (קדושה פון לשון הבדלה<sup data-n=\"25\">25</sup> אפשיידן און אויפהויבן פון זיין נידעריקייט, און ערשט דאן ווערט ער ראוי להקרבה אויפן מזבח ה׳26].\nאון דאס איז דער יתרון אין דעם דריטן קו — גמילות חסדים, וואס איז כולל קיום כל המצות — צו אויפטאן (בעיקר) אין דעם דבר גשמי (מיט וועלכן מ׳איז מקיים די מצוה), אז אזוי ווי ער איז (בחיצוניות) אין זיין ציור פון דברים תחתונים גשמיים, אין זיין „גשמיות”, זאל ער ווערן א חפץ של מצוה.\nאון מהאי טעמא זיינען מצות במדידה והגבלה דוקא27 — ניט ווי תורה אויף וועלכער שטייט28 „ארוכה מארץ מדה גו׳”, און תפלה וואס איר תכלית השלימות איז ווען מ׳איז עולה דורך איר „השמימה”, וואס דאס איז די עבודה פון „בכל מאדך” פון מס״נ29: העכער פון מדידות והגבלות — ווארום וויבאלד אז מצות זיינען אנגעטאן אין דברים תחתונים גשמיים [ביז אז אויך די מצות פון חובת הלבבות דארף מען מקיים זיין אין אן אופן אז דער לב הגשמי זאל נתפעל ווערן מיט א געפיל פון אהבה ויראה וכו׳, ביז עס זאל זיין ניכר אין דעם בשר הלב30] — האבן זיי א הגבלה.\nו. און דאס איז אויך דער ביאור אין די אויבנדערמאנטע שינויים אין לשון הכתוב:\n„ויקחו לי תרומה” איז מרמז אויף קו התורה31 כנ״ל. וואס מהאי טעמא שטייט דא „ויקחו לי תרומה” — ניט „ויתנו לי תרומה” — אז דער אדם מלמטה גיט להלמעלה, צו לי, כביכול, נאר ויקחו — דער אדם למטה נעמט דאס וואס מ׳גיט עם מלמעלה, דעם לי, כביכול,\nווייל די עבודה פון תורה איז (ניט בדרך מלמטה למעלה, נאר) בדרך מלמעלה למטה — דורך תורה נעמט מען און מען איז ממשיך אלקות (חכמתו ית׳) מלמעלה למטה:\nדי עבודה פון תורה איז אין אן אופן פון „ויקחו” — מען „נעמט” (און מ׳איז ממשיך) אלקות מלמעלה למטה:",[["25","25","<a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ״ו</a>."],["26","26","ראה לקו״ת שלח ד״ה בפ׳ נסכים (ועוד) מביאור מחז״ל (ברכות יד, סע״ב) כל הקורא ק״ש בלא תפלין כאילו הקריב כו׳ בלא נסכים — דקרבנות הן דוגמת ק״ש — העלאה מלמטה למעלה, וצ״ל תפילין (ובקרבנות — מנחה ונסכים). כלל כל התורה והמצות מעשיות, להמשיך דירתו ית׳ בתחתונים. עיי״ש באורך."],["27","27","אגה״ק סי׳ יו״ד. ובכ״מ."],["28","28","איוב יא, ט."],["29","29","לקו״ת שה״ש מט, ריש ע״ב ואילך."],["30","30","ד״ה טעמו וראו תרצ״ד (בספר המאמרים קונט׳ ח״ב) פ״א. ד״ה וכל העם ה׳ש״ת פ״ב. ובכ״מ."],["31","31","ראה בכ״ז <a class=\"ft-cite\" href=\"#/read/tanya/3401310052\" data-slug=\"tanya\" data-id=\"3401310052\">תניא פמ״ז</a>. אוה״ת פרשתנו ע׳ א׳שנא. א׳שנט ואילך."]]],[1300161311,"און וויבאלד אז אורייתא וקוב״ה כולא חד32, דערפאר איז דער פסוק מדייק „ויקחו לי” — וואס ווייזט אויף עצמותו ומהותו ית׳33 — ווייל דורך תורה „נעמט” מען עצמות ומהות אליין, בלשון חז״ל34 „אותי אתם לוקחים”.\nאבער לאידך גיסא, וויבאלד אז דאס וואס א איד „נעמט” עצמות דורך תורה איז (בעיקר) — ניט דער אויפטו פונעם אדם הלומד, נאר) דערפאר וואס דער אויבערשטער האט זיך כביכול „אריינגעשטעלט” אין תורה (אין אן אופן אז תורה איז „דברי כאש”), בלייבט די המשכת העצמות כאילו ווי אפגעטראגן פון דעם אדם הלומד —\n[ביז עס קען זיין א מציאות אז די תורה זאל געלערנט ווערן דורך אן איש בלתי טהור, וואס אויך דאן איז דא דער „ויקחו לי” — די המשכת העצמות שע״י תורה — אבער דער אדם איז ניט בערך כלל אז דער „לי” זאל ביי אים מאיר זיין בגילוי].\nאון דאס איז אויך דער טעם וואס עס שטייט „לי תרומה” — אין צוויי באזונדערע ווערטער — לרמז אז דער „לי” (די המשכת העצמות שבתורה) און די „תרומה” (די עבודה פון לימוד התורה) זיינען ניט איין ווארט — זאך35, ווי־באלד די המשכת העצמות בלייבט אפגעטראגן פון דעם אדם הלומד.\nמשא״כ בתרומת השקלים, ביים קו פון „עבודה” (קרבנות ותפלה), שטייט דער לשון „תרומתי” — ווארום דער קרבן גשמי גופא איז עולה און ווערט נכלל אין זיין מקור ושורש למעלה, אין אלקות; און אזוי אויך דורך עבודת התפלה ווערט דער אדם דערהויבן ביז „שמימה” כנ״ל, דערגרייכט ער צו אזא דרגא וואו דער אור אלקי איז ביי אים מאיר בגילוי — און דערפאר שטייט „תרומתי”, וואס ווייזט אז דער פארבונד פון „תרומה” (עבודה) מיט „לי” (המשכת אלקות דורך דער עבודה) איז אין אן אופן ניכר ונגלה ונרגש אין דער עבודה36.\nמשא״כ ביי דער דריטער תרומה — תרומת המשכן — וואס איז די עבודה מיטן גשם אליין ווי ער איז בגשמיותו, איז די המשכת אלקות אין דער עבודה בהעלם; און דערפאר שטייט „תרומה” סתם, אן דערמאנען בפירוש אז דאס איז תרומה לה׳, ווייל אין דער עבודה איז ניט קענטיק די שייכות להקב״ה.\nז. אע״פ אז מצות זיינען אנגעטאן בדברים גשמיים, ווערט אבער דוקא דורך דער עבודה אויסגעפירט די כוונה פון בריאת העולם, דער ענין פון „נתאוה הקב״ה להיות לו דירה בתחתונים”37, ווי דער אלטער רבי38 איז מדגיש, אז דאס מיינט א „דירה” לו ית׳ אין דעם עולם הזה הגשמי התחתון „שאין תחתון למטה ממנו”:",[["32","32","מובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ״ד</a> ורפכ״ג בשם הזהר. וראה זח״א כד, א. זח״ב ס, א. ולהעיר מתקו״ז ת״ו ותכ״ב."],["33","33","ראה אוה״ת פרשתנו (ע׳ א׳שפא): ור״ל לי היינו עצמות אוא״ס ולכן ארז״ל (ויק״ר פ״ב, ב) כ״מ שנאמר לי אינו זז לעולם לפי שזהו בחי׳ אני ה׳ לא שניתי."],["34","34","תנחומא אמור יז. ויק״ר פ״ל, יג. וראה שמו״ר ריש פרשתנו. פל״ג, ו. תנחומא פרשתנו ג. יל״ש פרשתנו רמז שסד. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310052\" data-slug=\"tanya\" data-id=\"3401310052\">תניא פמ״ז</a>."],["35","35","אף ששכל האדם מתייחד עם שכל התורה, ואדרבה — ביחוד נפלא שאין יחוד כמוהו כו׳ (<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ״ה</a>)."],["36","36","ולאידך, בזה שתיבת „לי” נכללת בתיבת „תרומתי” מרומז, שאי״ז בחי׳ „לי” כמו״ש מצד עצמה, כ״א כמו שמתלבשת ב(תרומת) האדם."],["37","37","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>. ע״פ תנחומא נשא טז. ועוד."],["38","38","תניא שם."]]],[1300161312,"אבער בכדי אז די עבודה זאל זיין כדבעי ובשלימות, מוז ביים אדם זיין אויך דער קו (און יסוד) פון תורה און דער קו פון „עבודה”.\nאון וויבאלד אז אלע עניני עבודת ה׳ זיינען דא אין משכן כנ״ל, איז אויך דער ענין מרומז אין מעשה המשכן — דערמיט, וואס די תורה רעדט בפירוש אין אונזער פרשה נאר וועגן תרומת המשכן, ווייל דאס איז דער עיקר ותכלית הכוונה; און די אנדערע צוויי תרומות דערמאנט ווערן נאר בכלל ובדרך רמז, ווייל זיי זיינען (בהכוונה העיקרית) בלויז א הכנה והקדמה (והשלמה) צו דער עשיית הדירה.\nח. און דאס איז אויך דער ביאור אין דברי המדרש הנ״ל (סעיף ג) אז „זהב וכסף וגו׳” זיינען כנגד די ד׳ מלכיות39:\nוויבאלד אז דער ענין פון תרומת המשכן איז צו מאכן א דירה לו ית׳ בתחתונים (פון די דברים גשמיים מאכן א מקדש ומשכן לה׳) — איז די שלימות פון דעם ענין (ניט אזוי אין בנין המשכן, אין וועלכן מ׳האט געזען בעיני בשר ווי אין זיי איז דא השראת השכינה, נאר) אין דער עבודה בזמן הגלות40, ווען גשמיות העולם איז בתקפו, און דורך דער עבודה צו איבערמאכן אויך אט דעם גשם, איז מען מברר דעם תחתון „שאין תחתון למטה ממנו”:\nאון דער עילוי פון דער עבודה וועט שטיין בגילוי לעתיד לבא, וואס דאן וועט נתגלה ווערן די מעלה פון „מעשה”41, כידוע אז דאן וועט זיין „מעשה גדול” [וואס דערפאר איז דער מקדש (וואס „הי׳ מעין עוה״ב”<sup data-n=\"42\">42</sup> געווען בעיקר פון דומם],\nאון ווי ס׳איז מבואר אין דעם ענין פון יוסף ויהודה, אז יהודה ווייזט אויף דער עבודה פון מעשה (יהודה — פון לשון הודאה וביטול, ווי דומם וואס „יש בו בחי׳ הביטול ביותר”<sup data-n=\"43\">43</sup>, און לעתיד לבא וועט יהודה זיין העכער פון יוסף — „ודוד44 עבדי נשיא להם לעולם”.\n(ממאמר ד״ה ויקחו לי תרומה תשל״ה)",[["39","39","ראה אוה״ת פרשתנו ע׳ א׳תט ואילך."],["40","40","ראה גם לקמן ע׳ 479."],["41","41","בכל הבא לקמן ראה בארוכה תו״א, תו״ח ואוה״ת ר״פ ויגש."],["42","42","לשון ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370198\" data-slug=\"torah-or\" data-id=\"3901370198\">תו״א שם (מג, ד</a>)."],["43","43","לשון ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370199\" data-slug=\"torah-or\" data-id=\"3901370199\">תו״א שם (מד, א</a>)."],["44","44","יחזקאל לז, כה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151426\" data-slug=\"likkutei-sichot\" data-id=\"1300151426\">לקו״ש חט״ו ע׳ 413</a> הערה 12."]]],[1300161313,"א. פון פסוק¹ „ועשו לי מקדש ושכנתי בתוכם” לערנט ארויס דער רמב״ם אין הלכות בית הבחירה:² „מצות עשה לעשות בית ליי׳ מוכן להיות מקריבים בו הקרבנות כו׳ שנאמר ועשו לי מקדש, וכבר נתפרש בתורה משכן שעשה משה רבינו, והי׳ לפי שעה שנאמר כי לא באתם עד עתה וגו׳”³.\nאבער אין הלכות מלכים⁴ לערנט עס ארויס דער רמב״ם פון אן אנדער פסוק: „שלש מצות נצטוו ישראל בשעת כניסתן לארץ וכו׳ ולבנות בית הבחירה שנאמר⁵ לשכנו תדרשו ובאת שמה”. איז ידועה די קשיא: פארוואס בריינגט ער ניט דא דעם זעלבן פסוק וואס ער בריינגט אין אנפאנג הל׳ בית הבחירה?\nדער לחם משנה⁶ ענטפערט אויף דעם, אז דער פסוק „ועשו לי מקדש” רעדט וועגן „משכן המדבר”, און דער פסוק „לשכנו תדרשו” מיינט דעם „משכן שילה” (ווי רש״י טייטשט⁷), און „כי היכא דבשילה ובמדבר היא מצוה ודאי דבבית הבחירה היא מצוה”⁸.\nעס איז אבער ניט פארשטאנדיק: וויבאלד אז בנין „בית ליי׳” רעכנט דער רמב״ם אין הלכות ביה״ב אלס „מצות עשה” — און דאס מיינט א מצוה הנוהגת לדורות — פארוואס בריינגט ער א פסוק וואו דער ציווי איז נאר אויף בנין המשכן?\nאון ס׳איז בכלל קשה להבין, אז אין הלכות בית הבחירה, וואס כשמן כן הן, אז דער גאנצער תוכן איז די מצות עשה לדורות פון (בנין) ביהמ״ק, זאל ער בריינגען א פסוק וואו דער ציווי איז אויפן משכן המדבר — און אין הלכות מלכים, וואס כשמן כן הן, אז עס רעדט זיך בעיקר וועגן מצות (מינוי) מלך, זאל ער בריינגען דעם פסוק „לשכנו תדרשו” וואס רעדט וועגן משכן שילה (און בית עולמים⁹).\nב. לכאורה קען מען פארענטפערן, אז דער רמב״ם בריינגט אין הלכות ביה״ב דעם פסוק „ועשו לי מקדש” (ניט אלס ציווי אויפן משכן, נאר) ווייל פון אים לערנט מען אפ די מצוה (כללית) פון בנין ביהמ״ק, ווי מען געפינט עס אין מדרשים¹⁰. לפי״ז איז אבער צוריק ניט פארשטאנדיק, וואס בײַ מצות בנין בית הבחירה אין הלכות מלכים בריינגט ער אן אנדער פסוק — „לשכנו תדרשו ובאת שמה”.\nוביותר יוקשה אז ס׳איז משמע מסגנון הלשון וכו׳, אז דער מקור פון רמב״ם אין הלכות מלכים איז פון דעם מדרש¹¹",[["1","1","פרשתנו כה, ח."],["2","2","בתחלתו. ובסהמ״צ מ״ע כ. ועד״ז בחינוך מצוה צה."],["3","3","ראה יב, ט."],["4","4","בתחלתו."],["5","5","ראה יב, ה."],["6","6","בהלכות מלכים שם."],["7","7","עה״פ ראה שם. וראה ספרי שם יב, יא. פרש״י שם. אבל בספרי שם לפנ״ז (יב, ה) ולאח״ז (יב, יד) דקאי על ירושלים. וכ״כ ברמב״ן עה״ת קרח טז, כא."],["8","8","וראה שם בסיום דבריו ולפי מ״ש הרא״ם כו׳."],["9","9","ראה לעיל הערה 7."],["10","10","סדר עולם רבה ספ״ו. תנחומא תצא יא (תנחומא באבער שם). פסיקתא דר״כ (באבער) פ״ג (עה״פ והי׳ בהניח גו׳). ועוד. ובהנ״ל משמע שקאי רק על בנין בית הבחירה."],["11","11","תנחומא ופסיקתא שם. אבל בנר״כ הרמב״ם שם כ׳ דמקורו מסנהדרין (כ, ב). וספרי (ראה יב, י), אבל שם לא הובאו הפסוקים כברמב״ם. ולאידך"]]],[1300161314,"וואס בריינגט דעם פסוק „ועשו לי מקדש” אויפן בית המקדש. וז״ל:\n„על שלשה דברים נצטוו ישראל בכניסתן לארץ למנות עליהם מלך ולבנות להם בית הבחירה ולהכרית זרעו של עמלק למנות עליהם מלך דכתיב שום תשים עליך מלך לבנות להם בית הבחירה דכתיב ועשו לי מקדש להכרית זרעו של עמלק דכתיב והי׳ בהניח ה״א גו׳ תמחה את זכר עמלק”, זעט מען דאך אז ביים זעלבן ענין פון די דריי ציוויים איז אין מדרש דער לימוד אויף מצות בנין בית הבחירה פון פסוק „ועשו לי מקדש” — היינט פארוואס איז דער רמב״ם אין הלכות מלכים משנה (פון מדרש און פון הלכות ביה״ב) און בריינגט דעם ציווי פון אן אנדער פסוק?\nג. אויך דארף מען פארשטיין: אויף בנין ביהמ״ק איז דאך פאראן א פסוק און ציווי מפורש (ניט ווי „ועשו לי מקדש” וואס בפשטות רעדט ער וועגן משכן): „והי׳ המקום אשר יבחר ה״א בו לשכן שמו שם גו׳”¹², ווי מ׳געפינט עס אין גמרא¹³ און אין ספרי¹⁴ — איז פאר־וואס בריינגט ניט דער רמב״ם, וואס רעכנט די מצוה לדורות, אט דעם פסוק אנהייבס הלכות בית הבחירה?\nדער כסף משנה¹⁵ פארענטפערט עס, ווייל דער רמב״ם לערנט אז דער פסוק „והי׳ המקום וגו׳” איז ניט געזאגט געווארן אלס ציווי צו בויען א בית המקדש, נאר א „סיפור בעלמא הוא” (— אז מען זאל בריינגען קרבנות למקום אשר יבחר ה׳); און דאס וואס די גמרא (וספרי) בריינגט יאָ דעם פסוק, איז דאס בלויז אלס ראי׳ אז „הכרתת זרעו של עמלק קודמת לבנין בית הבחירה”.\nלפי״ז אבער (איז נוסף אף דער ניט גלאטקייט מצד הכלל הידוע ברמב״ם¹⁶ אז ער בריינגט א דרשה הפשוטה ביותר אע״פ שלא נמצאת בש״ס, ועד״ז דארף זיין בנדו״ד — און דא איז לא כן הוא) וערט די שאלה¹⁷ פארוואס בריינגט עס ניט אויך דער רמב״ם (אין הלכות מלכים¹⁸) אלס ראי׳ אז הכרתת זרעו של עמלק קודמת לבנין הבית?\nד. אויך פאדערט זיך הסברה אין דברי הרמב״ם אין הלכות בית הבחירה, וואס נאכדעם וואס ער איז מסיים אין הלכה א׳ „וכבר נתפרש בתורה משכן שעשה משה רבינו והי׳ לפי שעה שנאמר כי לא באתם עד עתה וגו׳” — איז ער ממשיך אין הלכה ב׳: „כיון שנכנסו לארץ העמידו המשכן בגלגל ארבע עשרה שנה שכבשו ושחלקו ומשם באו לשילה ובנו שם בית של אבנים ופרשו יריעות המשכן עליו ולא היתה שם תקרה. ושס״ט שנה עמד משכן שילה וכשמת עלי חרב ובאו לנוב ובנו שם מקדש וכשמת שמואל חרב ובאו לגבעון ובנו שם מקדש ומגבעון באו לבית העולמים. וימי נוב וגבעון שבע וחמשים שנה”.\nאיז שווער צו פארשטיין: דער רמב״ם איז דאך א ספר פון הלכות — איז למאי נפק״מ להלכה, אט די אריכות, אז מ׳האט אויפגעשטעלט דעם משכן בגלגל",[["","","במדרשים הנ״ל אי׳ ביהב״ח לפני מלחמת עמלק. וראה קרית ספר (הל׳ מלכים) שם. סמ״ג מ״ע קיד־קטו."],["12","12","ראה יב, יא."],["13","13","סנהדרין שם."],["14","14","ראה שם. וכ״כ הסמ״ג במ״ע קסג וברמזי מ״ע שם. וראה לקמן הערה 35."],["15","15","ריש הלכות בית הבחירה."],["16","16","לח״מ הל׳ מלכים שם ה״ב. יד מלאכי כללי הרמב״ם ס״ד."],["17","17","כמו שהקשה בכס״מ ריש הלכות מלכים."],["18","18","שם ה״ב. ועיי״ש בלח״מ."]]],[1300161315,"און דערנאך אין שילה נוב וגבעון — דאס איז דאך לכאורה נאר א סיפור פון דברי ימי ישראל?\nהן אמת, אז דער מקור פונעם סדר הבנינים וכו׳ פון דעם רמב״ם איז פון דער משנה במס׳ זבחים¹⁹ — אבער אין משניות זיינען דא כמה ענינים וואס זיינען ניט הלכות²⁰, משא״כ דער ספר „היד” פון רמב״ם וואס באשטייט נאר פון הלכות פסוקות²¹.\nנאכמער: אויך אין דער משנה וערט ניט דערציילט סתם וועגן סדר הבנינים, נאר בצירוף הלכות ודינים וואס זיינען בזה, אז „באו לגלגל הותרו הבמות ק״ק נאכלין כו׳ באו לשילה נאסרו הבמות כו׳ באו לנוב וגבעון הותרו הבמות” (וואס דאס אלץ איז אויך א הקדמה, אז נאר נאכדעם וואס) באו לירושלים נאסרו הבמות ולא הי׳ להן היתר והיא היתה נחלה”.\nדער רמב״ם אבער דערמאנט דאס אלץ ניט. און דער טעם איז מובן בפשטות, ווייל „מאי דהוה הוה”; און צום דין אין רמב״ם (ה״ג) „כיון שנבנה המקדש בירושלים נאסרו כל המקומות כולן לבנות בהן בית ליי׳ ולהקריב בהן קרבן” זיינען ניט נוגע אז „באו לגלגל הותרו הבמות” און „באו לשילה נאסרו וכו׳” —\nעפ״ז וערט די תמי׳ נאך גרעסער, א) וואס ער בריינגט דעם סדר פון „גלגל וכו׳ ומשם באו לשילה וכו׳” און ב) איז נאך מפרט דעם מספר פון די יארן וואס יעדער פון זיי איז געשטאנען, וואס דאס איז דאך, אפילו בזמן גלגל וכו׳, ניט מער ווי אן ענין פון דברי ימי ישראל, און ג) וואס בריינגט זיך אויך ניט אין דער משנה.\nה. וועט מען דאס פארשטיין בהקדים לבאר דעם טעם, וואס אין הלכות מלכים וואו עס רעדט זיך וועגן דער מצוה פון (מינוי) מלך, בריינגט דער רמב״ם אויך די מצות פון בנין בית הבחירה (און אלע „ג׳ מצות”).\nעד״ז געפינט מען אין ספר המצות: ווען ער רעכנט דארט די מצוה פון בנין בית המקדש²² — „שצונו לעשות בית עבודה כו׳²³ והוא אמרו יתעלה ועשו לי מקדש”, איז ער מוסיף: „ולשון ספרי שלש מצות נצטוו ישראל בעת כניסתן לארץ למנות להם מלך ולבנות להם בית הבחירה ולהכרית זרעו של עמלק”²⁴. איז אויך אין דעם ניט מובן: וואס זיינען די אנדערע צוויי מצות נוגע בא דעם בריינגען מצות בנין ביהמ״ק²⁵?\nאויך דאס וואס ער הויבט אן (כל׳ הגמרא והספרי) „שלש מצות” איז לכאורה א יתור לשון: ער רעכנט דאך גלייך אויס (ווי אין גמרא און ספרי) די דריי מצות בפרט — צוליב וואס דארף ער פריער מקדים זיין זייער מספר, ובלשון הש״ס²⁶: „מנינא למה לי”?*²⁶",[["19","19","קיב, ב. ובגמרא שם קטז, ב ואילך (קיח, ב ואילך). כציון הכס״מ."],["20","20","וכן בגמרא."],["21","21","כמ״ש הרמב״ם בהקדמתו."],["22","22","במ״ע כ׳."],["23","23","כ״ה בסהמ״צ הוצאת קאפח. ועד״ז בהוצאת העליר „לבנות בית עבודה כו׳”. אבל בהוצאה שלפנינו: לבנות בית הבחירה לעבודה. וראה לקמן הערה 34."],["24","24","וכן הביאו במ״ע קפח במצות להכרית זרע עמלק."],["25","25","דבשביל ההמשך „והנה התבאר שבנין בית הבחירה מצוה בפני עצמה” הי׳ מספיק שיאמר „שלש מצות נצטוו כו׳. ולבנות להם בית הבחירה”."],["26","26","שבת סט, א. וש״נ. *26) להעיר מיד מלאכי כללי הרמב״ם סל״ד. אבל יש לחלק בנדו״ד."]]],[1300161316,"מען קען ניט זאגן אז דאס וערט פארענטפערט בפרש״י שם²⁷: להכי נקט שלש הללו שהן תלויות זו בזו לעשותן כסדרן כו׳ מלך ואחרי׳ עמלק ואחרי׳ בית הבחירה,\nוואורום דאס איז מבאר נאר וואס „נקט שלש הללו”, אבער ניט די הקדמה — ג׳ מצות.\nו. דער ביאור בזה: די דריי מצות זיינען (כל׳ רש״י) „תלויות זו בזו”. ד.ה. הגם אז זיי זיינען דריי באזונדערע מצות, איז אבער יעדער מצוה (אויך) א פרט, בריינגט שלימות אין די אנדערע צוויי: שלימות מצות מינוי מלך וערט דערגרייכט ווען ס׳וערן אויך אויס־געפירט די מצות פון להכרית זרעו של עמלק ובנין בית הבחירה²⁷*; און עד״ז ביי די אנדערע, ביז אז שלימות קיום מצות בנין בית הבחירה איז פארבונדן מיטן קיום המצות פון מינוי מלך ומלחמת עמלק²⁸.\nאון בהמשך לזה לערנט מען ווייטער ארויס פון פסוק, אז די שייכות פון „זו בזו” איז אויך בנוגע דעם סדר: פריער מינוי מלך, דערנאך להכרית זרעו של עמלק און נאכדעם דער בנין ביהב״ח.\nד.ה. דא איז ניט נאר א סדר אין זמני החיוב וקיום המצות מצד די אידן — „נצטוו ישראל” (מצד דעם גברא), נאר דאס איז א פרט אין מינוי מלך: מצד דעם גדר פון מלך דארף זיין מלחמת עמלק²⁸* ובנין ביה״ב, און מצד דעם גדר פון בית המקדש, פאדערט זיך אז עס זאל זיין מינוי מלך²⁹ ומלחמת עמלק.",[["27","27","סנהדרין שם ד״ה שלש מצות. *27) מעין זה (אף שאינו ממש אותו ענין): במינוי מלך — מלך ישראל, מבית דוד, נמשח בקרן, על כל השבטים. ועוד. בעמלק — באופן דיהושע, שאול, בימי המן, דכל יחיד. ועוד. בביהב״ח — משכן וכו׳, בית ראשון, כשחסרו בו ה׳ דברים, ב״ש. ועוד. ועד״ז בשאר מצות — ולדוגמא: תש״ר בפ״ע, לאחרי תש״י. ציצית, תכלת בציצית. ואכ״מ."],["28","28","ואפשר שיהי׳ רק לכתחילה, או גם לעכב — וראה הדוגמאות דבהערה הקודמת. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181224\" data-slug=\"likkutei-sichot\" data-id=\"1300181224\">לקו״ש חי״ח (ע׳ 215</a>) די״ל דמ״ש במשנה (מדות פ״א מ״ג־ד) „חמשה שערים היו כו׳” — „שבעה שערים היו” (אף שמפרשם לאח״ז) לרמז שכולם הם מציאות אחת וכ״ז שלא ישנם כל השערים אין לא׳ מהם דין שער (וע״ד מכות ט, ב. שש ערי מקלט כו׳). *28) להעיר שכשבקש משה (פנחס כז, טז־יז) „יפקוד ה׳ אלקי הרוחות גו׳” אמר „אשר יצא לפניהם ואשר יבוא לפניהם גו׳” ובספרי ובפרש״י התורה שהוא למלחמה, ובפרש״י שם „לא כדרך מלכי האומות כו׳ משלחין חיילותיהן למלחמה כו׳, וכדרך שעשה יהושע, וכן בדוד כו׳”. ולהעיר שבגמרא (סנהדרין שם) ובספרי (ראה) שם הביאו לראי׳ שמינוי מלך הוא לפני מלחמת עמלק „כשהוא אומר כי יד על כס י־ה מלחמה לה׳ בעמלק ואין כסא אלא מלך שנאמר כו׳”, והרי ע״ז דרשו רז״ל (נסמן לקמן הערה 75 וראה הערה 76), שהכסא שלם תלוי במחיית עמלק. וראה רמב״ן ס״פ בשלח. לקמן הערה 31."],["29","29","להעיר מזה ש„אין מוסיפין על העיר ועל העזרות אלא במלך כו׳” (שבועות יד, א במשנה. רמב״ם הל׳ ביהב״ח פ״ו הי״א). גם לפי הדיעה בגמרא שם (טז, א) „באחת מכל אלו”, כ׳ הריטב״א (שבועות שם) ד„למצוה בעי׳ כולהו”. וראה צפע״נ לסנהדרין שם. בעיון יעקב לעי׳ סנהדרין שם כ׳, דמשמעות הש״ס דלא קמסתפק כלל אי לבנות ביהמ״ק תחלה קודם העמדת מלך לפי דמילתא דפשיטא דהעמדת מלך קודם כדאיתא בב״ב (ד, א). ועד״ז הוא בשו״ת בית הלוי ח״ב סי״א סק״ח (בהגהה), דפשיטא לי׳ דמלך קודם מצד הנ״ל דא״א לקדש העזרה אלא במלך. אבל בהר״ין לעי׳ שם, דגם בזה מסתפק לי׳. וגם דמשמע מהגמ׳ (ובפרט מפרש״י הנ״ל) דשייכותם הוא גם: א) מצד קיום המצוה — פועל, ב) מצד הנפעל שישנו מלך והכרתת זרעו של עמלק. ולא רק מצד המציאות דמבלי מלך א״א לקדש העזרה וכיו״ב. וראה לקמן הערה 31, 32. ולהעיר ממנ״נ ח״ג פמ״ה. *) וראה רמב״ם שם פ״א ה״ד. ספ״ד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181288\" data-slug=\"likkutei-sichot\" data-id=\"1300181288\">לקו״ש חי״ח ע׳ 279</a> הערה 56."]]],[1300161317,"[און דעריבער בריינגט דארט דער רמב״ם (אין הלכה ב׳) די פסוקים³⁰ „ויהי כי ישב המלך בביתו וה׳ הניח לו מסביב מכל אויביו ויאמר המלך אל נתן הנביא אנכי יושב בבית ארזים וגו׳”, די ראי׳ פון פסוק איז ניט בלויז אויף דעם סדר פון זמן המצות — אויף דערויף וואלט געווען גענוג די (ערשטע) פסוקים וואס די גמרא בריינגט „והניח לכם מכל אויביכם וגו׳ והי׳ המקום אשר יבחר ה׳ גו׳” — נאר (בעיקר) אז דאס איז אן ענין וגדר אין (קיום מצות) „מלך” ומלחמת והכרתת: „ויהי כי ישב המלך בביתו וה׳ הניח לו מסביב גו׳ ויאמר המלך גו׳”]³¹.\nדערמיט וערט פארשטאנדיק וואס דער רמב״ם בריינגט אלע „ג׳ מצות” אין הלכות מלכים און אויך אין דער מ״ע אויף בנין המקדש — ווייל זיי זיינען תלוי און געבונדן זב״ז³².\nז. לפי״ז איז אויך מבואר דער המשך פון די הלכות אין אנפאנג הלכות בית הבחירה: „מ״ע לעשות בית ליי׳ מוכן כו׳ שנאמר ועשו לי מקדש” און איז ממשיך „וכבר נתפרש בתורה משכן שעשה משה רבינו והי׳ לפי שעה כו׳”, ד.ה. אז מצות בנין „בית ליי׳” גייט (אויך) אויף דעם משכן וואס משה רבינו האט געמאכט³³;\nאון וויבאלד אז מצות בנין בית המקדש איז פארבונדן מיט די אנדערע צוויי מצות, אז צום גדר (הקיום) פון בנין המקדש איז נוגע דער (פריער־דיקער) קיום פון מינוי מלך און דער „בהניח” פון מלחמת עמלק — דארף מען זאגן אז אזוי איז געווען בא אלע בתי־מקדש:\nד.ה. הגם אז דאס זיינען „ג׳ מצות” וואס „נצטוו ישראל בשעת כניסתן לארץ”, איז דאס נאר בנוגע דעם ציווי",[["30","30","ש״ב ז בתחלתו."],["31","31","עפמש״כ הרמב״ם בסהמ״צ סוף חלק המ״ע „שהם חובה על הצבור לא על כל איש ואיש כמו בנין בית הבחירה והקמת מלך והכרתת זרעו של עמלק” יל״ע אם הצורך במלך במחיית עמלק ובנין בית הבחירה הוא כיון דאז נעשה השלימות דגדר צבור [ויומתק לפי״ז מה שנצטוו בכניסתם לארץ (דוקא) עפמש״כ בצפע״נ (לרמב״ם הל׳ ברכות פי״א ה״א. מהדת״צ, ב. שו״ת צפע״נ וארשא (נ.י. תשי״ד) סקמ״ג) דכשנכנסו לא״י דוקא נעשו גדר צבור] אבל לפי״ז שונה דין צבור במצות מינוי מלך מבשאר. או דמצות אלו שייכות במיוחד למלך, כפשטות הכתובים שהביא הרמב״ם וכמ״ש ברד״ק (שמואל שם) דעל המלך מוטל לעשות ולצוות את ישראל כו׳ (וראה צפע״נ לסנהדרין שם). ועפ״י דעת היראים סרצ״ט (בהשלם — סתל״ה). רמב״ן ס״פ בשלח — לענין מחיית עמלק דהמלך חייב. ומצד זה נק׳ מצות על הצבור. וראה לשון הרמב״ם רפ״ה מהל׳ מלכים (ובה״ה שם) לענין מלחמת עמלק."],["32","32","ולפי כהנ״ל נמצא דהשייכות דג׳ מצות אלו י״ל בג׳ אופנים: א) מצד הזמן, דזמן חיוב הכרתת זרעו של עמלק הוא לאחר מינוי מלך. וזמן חיוב בנין בית הבחירה הוא לאחר מלחמת עמלק. ב) מצד קיום המצוה, דקיום מצות בנין בית הבחירה הוא לאחר קיום מצות מינוי מלך ומלחמת עמלק (ועד״ז לאידך, דשלימות קיום מצות מינוי מלך היא כאשר מקיימים לאח״ז גם הכרתת זרעו של עמלק ובנין בית הבחירה). ג) שלימות בהחפצא דבית הבחירה כאשר הוא נעשה לאחר מינוי מלך ומלחמת עמלק (וכן לאידך שלימות גדר מלך כאשר לאח״ז הוא מלחמת עמלק ובנין בית הבחירה). ובפרט לפי משנת״ל הערה 29. אבל י״ל דשלימות החפצא אינה תלוי׳ בסדר קיומם, כ״א רק בהמציאות דכל הג׳. ודוגמא בתש״ר — שמספיק ש„כל זמן שבין עיניך יהיו שנים”, או שצ״ל גם „והי׳ לאות על ידך (והדר) ולטוטפות בין עיניך”. ונפק״מ בהקדים תש״ר — האם צריך לחלצו ולהניח תש״י. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191047\" data-slug=\"likkutei-sichot\" data-id=\"1300191047\">לקו״ש חי״ט ע׳ 47</a> ואילך. בסגנון פשוט יותר ג׳ אופנים הנ״ל: א) מצד הפועל, ב) פעולה, ג) נפעל."],["33","33","אלא מכיון שהי׳ לפי שעה מוכח שבזה לא נגמר קיום הציווי ד„ועשו לי מקדש” כפשטות הפס׳ ברמב״ם. *) להעיר משו״ת הרשב״א ח״א סקמ״ח „המלך כצבור שהצבור וכל ישראל תלוין בו”. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191165\" data-slug=\"likkutei-sichot\" data-id=\"1300191165\">לקו״ש חי״ט ע׳ 165</a> ואילך."]]],[1300161318,"פון אלע דריי מצות, וויבאלד אבער אז מצות בנין „בית ליי׳” איז אין ציווי לכל הדורות³⁴ — „ועשו לי מקדש” — וואס איז כולל אלע (אויך די פריערדיקע) בנינים³⁵, איז מובן³⁶, אז אויך ביי יעדן פריערדיקן בנין המקדש (משכן) איז (דאס געווען נאכדעם ווי ס׳איז געווען\nא מלך און „הניח גו׳ מכל אויביך מסביב”, וויבאלד אז „תלויות זו בזו”.\n[נאר כשם ווי די שלימות אין ביהמ״ק עצמו לדורי דורות³⁷ איז געווען דער בנין בית עולמים כ„שנבנה המקדש בירושלים”, אזוי אויך זיינע תנאים וגדרים (אלס הקדמה לזה), מינוי מלך ומלחמת עמלק, אז זייער שלימות³⁸ האט זיך אויפגעטאן דורך דעם בנין המקדש בירושלים דוקא].\nאון מהאי טעמא בריינגט דער רמב״ם דעם פסוק „ועשו לי מקדש” און איז גלייך ממשיך „וכבר נתפרש בתורה משכן שעשה משה רבינו והי׳ לפי שעה”: דער ציווי כפשוטו איז דאך געווען אויפן משכן שעשה משה, וואס אויך דערמיט האט מען מקיים געווען מצות בנין „בית ליי׳” מיט אלע גדרים שבו — וואורום „משה רבינו מלך הי׳”, ווי דער רמב״ם שרייבט³⁹, און ס׳איז געווען לאחר מנוחה פון מלחמת עמלק: „ויחלש⁴⁰ יהושע את עמלק ואת עמו לפי חרב”⁴¹; און פון דעמאלט אן איז דער חיוב הציווי פון „ועשו לי מקדש” — געבליבן אויף אלעמאל.",[["34","34","ולכן כאן כשמדבר בתוכן המ״ע לדורות כ׳ „לעשות בית ליי׳ כו׳”*, משא״כ בריש הל׳ מלכים כ׳ „לבנות בית ליי׳” „לבנות בית הבחירה”. וראה לקמן הערה 54. ולהעיר שבהמצות שהוכתרת להל׳ ביהב״ח כ׳ „לבנות בית המקדש”. ובמנין המצות בריש ספר היד „לבנות בית הבחירה”. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171091\" data-slug=\"likkutei-sichot\" data-id=\"1300171091\">לקו״ש חי״ז ע׳ 91</a> והערה 93. חי״ט ע׳ 140 ואילך ושם ע׳ 143. וש״נ."],["35","35","ראה עד״ז ספרי דבי רב לספרי ראה (פי׳ יד) דועשו לי מקדש הוא ציווי לאותה שעה ולדורות דמאותה שעה חייבים לעשות מקום מקודש כו׳. ובאוה״ח פרשתנו עה״כ. קרית ספר ריש הל׳ ביהב״ח שם. ואולי זוהי כוונת הכס״מ בריש הל׳ ביהב״ח „משמע דהאי קרא כלל הוא לכל מקום הן למשכן שבמדבר בין לשילה ונוב וגבעון בין לבית עולמים”. וראה הר המורי׳ הל׳ ביהב״ח שם סק״ב. משא״כ דעת הסמ״ג, אף שגם הוא הביא הכתוב „ועשו לי מקדש” ברמזי מ״ע (קסג) הרי: א) ממשיך שם „ונא׳ והי׳ המקום אשר יבחר גו׳”. וגם בהכתוב „ועשו לי מקדש” כ׳ „וגו׳ וכן תעשו” (ראה פרש״י עה״פ). משא״כ ברמב״ם. ב) מלשונו שם בפנים „זמן מצוה זו של בנין ביהב״ח לא הגיעה עד ימי דוד כו׳”. משמע שלפנ״ז לא הי׳ מצוה (וראה כס״מ שם). אף שיש לתרץ שכוונתו זמן מצות בנין בית הבחירה דוקא, שהרי קאי בהמשך להתחלה שג׳ מצות נצטוו. אבל מ״מ מזה שבמצות בנין הבית חשיב רק זה (ש„ג׳ מצות נצטוו”) ולא כברמב״ם משמע דלא ס״ל כהרמב״ם."],["36","36","ומכיון דהמ״ע „לעשות בית ליי׳” הוא „מוכן להיות מקריבים בו הקרבנות וחוגגין אליו שלש פעמים בשנה” י״ל דגם במשכן, שילה ונוב וגבעון הי׳ מצות עלי׳ לרגל. וידועים דברי הרמב״ן (ראה טז, ט) או שיבאר כאן שלא יתחייבו לעלות לרגל כו׳ (וראה שם יב, ח). וראה הר המורי׳ הל׳ ביהב״ח בתחלתו סק״א. ועוד. ואכ״מ. *) וכן בסהמ״צ מ״ע כ׳ „בית עבודה כו׳” — ראה הוצאת העליר וקאפח. משא״כ בסהמ״צ לפנינו, כנ״ל הערה 23. *) להעיר מחזקוני ראה יב, ה."],["37","37","ראה לשון הרמב״ם בהל׳ ביהב״ח פ״א ה״ג."],["38","38","שאז נצטוו וקיימו מצות אלו — המעלה באופן הב׳ דלעיל הערה 32. משא״כ באופן הא׳ והג׳. אף שמובן שגם בזה תוס׳ שלימות כי נעשה ע״י קיום המצוה כו׳."],["39","39","הל׳ ביהב״ח פ״ו הי״א. פרש״י (ור״ח) שבועות טו, רע״א. ולהעיר שזה שצריכים מלך כו׳ לקדש העזרה נלמד ממ״ש למשה „ככל אשר אני מראה אותך כו׳” דמשה רבינו מלך הי׳ כבגמרא ורמב״ם שם."],["40","40","בשלח יז, יג."],["41","41","אף שלא הי׳ הכרתת עמלק, הרי גם לפני מקדש ראשון לא נמחה זרעו של עמלק ראה ש״א כז, ח. ל, יז. ועוד. וראה ב״ב כא, סע״א ואילך. ובחדא״ג סנהדרין. ספרי דבי רב שם. וראה צפע״נ סנהדרין שם עד״ז לענין מלך „אך חטאו בזה ועד ימות המשיח לא הוה”."]]],[1300161319,"ח. לויט דעם איז מובן וואס דער רמב״ם איז מאריך, אנהויבנדיק פון „משכן שעשה משה רבינו והי׳ לפי שעה” און איז ממשיך „כיון שנכנסו לארץ העמידו המשכן בגלגל ארבע עשרה שנה שכבשו ושחלקו” — וואס דערמיט איז ער מבאר אז דער ציווי פון „ועשו לי מקדש” ביי משכן משה איז געווען א ציווי לדורות און אז מ׳האט אים מקיים געווען ווען „העמידו המשכן וכו׳”: דער חילוק איז געווען נאר אין דעם אופן הקיום: דער מקדש שעשה משה, וויבאלד ער איז געווען געבויט אין מדבר און אויפגעשטעלט „ממסע למסע”, איז געווען אין אן אופן פון „משכן” (און „אהל”⁴²) — נאר „לפי שעה” — און במילא איז דער אופן החיוב והקיום נמשך געווארן אויך ווען „נכנסו לארץ” כל זמן זיי זיינען דארט געווען אין א סדר פון „לפי שעה” — איידער דעם גמר פון די „ארבע עשרה שנה שכבשו ושחלקו”. און יהושע איז דאך געווען א מלך⁴³.\n„ומשם באו לשילה”: וואס דארט זיינען די אידן געווען אין א מצב פון מנוחה יותר אין ארץ ישראל — ס׳איז דאך געווען לאחר שכבשו ושחלקו⁴⁴ — דעמאלט האט מען דארט געבויט בית של אבנים, ניט קיין אהל, (ווי ביז דאמאלס), נאר „שס״ט שנה עמד משכן שילה”⁴⁵.\nאבער אויך נאכדעם „וכשמת עלי חרב ובאו לנוב ובנו שם מקדש וכשמת שמואל חרב ובאו לגבעון . . וימי נוב וגבעון שבע וחמשים שנה”. ד.ה. אז אויך בנוגע נוב וגבעון זאגט דער רמב״ם: „ובנו שם מקדש” (כאטש דער ארון איז דארט ניט געווען און עס וערט בכ״מ אנגערופן „במה גדולה”⁴⁶), ווייל די מצות בנין המקדש⁴⁷ איז אויך דעמאלט געווען⁴⁸; נאר היות אז ס׳איז ניט געווען קיין מצב פון מנוחה בתכלית פון מלחמה, דעריבער איז ב„ימי נוב וגבעון” ניט „בית עולמים” — „ומגבעון באו לבית עולמים” (וואס דעמאלט איז געווען דער ענין פון „מלך” בשלימות, ביי דוד ושלמה, און אויך שלימות המנוחה פון מלחמת עמלק)⁴⁹.",[["42","42","ראה שמואל ב ז, ו. ובפשטות קאי „אהל” על ה„משכן” ו„משכן” על „שילה”. ועי׳ פרש״י שם. וראה זח״ב רמא, א. ובכ״מ."],["43","43","רמב״ם הלכות מלכים שם ה״ג."],["44","44","ואף שהמצוה היא לאחר מלחמת עמלק, הרי מב׳ הכתובים שבגמרא (ורמב״ם הל׳ מלכים) „והניח לכם מכל אויביכם גו׳ והי׳ המקום כו׳” (ובפרט שבפשטות התחלת הכתוב היא „ועברתם את הירדן וישבתם בארץ גו׳”. וראה פרש״י סנהדרין שם ד״ה בכניסתם לארץ) „וה׳ הניח לו מסביב מכל אויביו” מוכח שבנין הבית שייך למצב דמנוחה. וראה חדא״ג סנהדרין שם. ספרי דבי רב שם. ולהעיר מהגי׳ (הובא בדק״ס שם) „והי׳ בהניח לך ה״א מכל אויביך — הכתוב דפ׳ תצא במחיית עמלק. ובספרי ראה לפנינו (לא הובא המשך הכתוב „והניח לכם גו׳” כ״א התיבות לפנ״ז) אשר ה״א מנחיל אתכם."],["45","45","אבל מוסיף „ופרשו יריעות המשכן עליו ולא היתה שם תקרה”, היינו שעדיין לא הי׳ בית קבוע ממש. וראה לקמן הערה 52."],["46","46","מ״א ג, ד. תוספתא זבחים ספי״ג. וראה מאירי מגילה ט, ב. ובכ״מ."],["47","47","ולכן כתב „ובנו שם מקדש” שמשמע שהי׳ שם בנין אבנים (וכ״כ רש״י פסחים לח, ב), ולא שהקימו שם אוה״מ — המשכן כמ״ש בפיה״מ להרמב״ם במשנה זבחים פי״ד מ״ז. וכדמשמע מכ״מ. וראה תפא״י זבחים שם. הר המורי׳ שם סק״ד."],["48","48","וצ״ע אם גם לזה צריך מלך, ונוב נבנה ע״י שמואל (ראה לשון הגמרא (זבחים קיח, סע״ב ושם״ג) שמלך שמואל, ושנה שמלך שאול ושמואל), וגבעון ע״י (שמואל*) שאול או דוד, ראה ס״פ פי״ג. סדר הדורות ב״א תתעא. הר המורי׳ שם סק״ה. ועוד. ואולי תלוי אם „בנו שם מקדש” (כרמב״ם כאן) שאז צריך למלך. או שרק הקימו האה״מ — המשכן."],["49","49","וכ״ה הסדר דג׳ מצות אלו בבנין בית השלישי כברמב״ם רפי״א מהלכות מלכים המשיח וכו׳ ובונה המקדש. ובה״ד שם: יעמוד מלך *) ע״פ הילקוט שמואל א (כח) מס״ע."]]],[1300161320,"ט. ע״פ הנ״ל וועט וערן פאר־שטאנדיק, וואס אין אנהייב הלכות מלכים רעדט דער רמב״ם וועגן אלע „ג׳ מצות” און פארוואס ער בריינגט דעם פסוק „לשכנו תדרשו ובאת שמה”, ניט דעם פסוק „ועשו לי מקדש” און אויך ניט קיין פסוק מפורש בנוגע בית עולמים⁵⁰ — היות אז ער רעדט וועגן זמן „בשעת כניסתן לארץ” (נאך כיבוש וחילוק), איז שוין דעמאלט געווען דער קיום פון אלע ג׳ מצות שנצטוו וואס זיינען „תלוין זב״ז” (הגם אז זייער תכלית השלימות איז געווען בבנין ביהמ״ק בירושלים)⁵¹:\nס׳איז שוין געווען דער בנין פון א בית (ניט קיין אהל ווי לפנ״ז); נאך די י״ד שנה פון כיבוש וחילוק⁵² איז געווען א מצב פון מנוחה אין ארץ ישראל; און ס׳איז געווען דורך יהושע וואס ער איז נתמנה געווארן למלך (ע״י משה רבינו ובית דינו, ווי די מצוה פון מינוי מלך דארף זיין לדורות), „ע״פ ב״ד של שבעים זקנים ועל פי נביא”⁵³ [משא״כ דער משכן וואס איז געווען לפי שעה אין מדבר (וממסע למסע), ניט אין א מצב פון מנוחה, און משה׳ס מלוכה געפינט מען ניט אז עס זאל זיין ע״י מינוי, ווי די פרטי מצות מינוי מלך]⁵⁴.\nיו״ד. עפ״ז קען מען אויך פאר־ענטפערן די שאלה בנוגע דער הלכה הנ״ל אין הל׳ ביה״ב, און וואס מען קען פון איר ארויסלערנען להלכה בפועל:\nדער רמב״ם פסק׳נט⁵⁵ „ואסור לאדם שיעשה בית תבנית היכל אכסדרא תבנית אולם חצר כנגד העזרה” — איז וויבאלד אז די אלע אויסגערעכנטע בנינים האבן געהאט א דין מקדש ביי יעדן האט מען מקיים געווען די מצוה פון „ועשו לי מקדש”",[["","","כו׳ וילחום מלחמות ה׳ (סתם — כולל מלחמת עמלק ולאחר הכרתת זרעו כו׳ ומצב דמנוחה —) כו׳ „אם עשה והצליח ונצח כל האומות שסביביו” (תיבות אלו נשמטו ע״י הצנזור) — אז — ובנה מקדש במקומו. וראה הר המורי׳ שם סק״ב. אבל בנוגע לבנין בית שני דלא הי׳ שם מלך וכו׳ (רמב״ם פ״ו מהל׳ ביהב״ח הי״ד, וברמב״ם שם „ובמה נתקדשה בקדושה ראשונה כו׳”), אולי י״ל דאין צריך כיון שהוא המשך דבית ראשון. וראה קונטרס דרישת ציון וירושלים בשו״ת שאילת דוד בתחלתו. ולהעיר מרמב״ם הלכות מלכים פי״א ה״א „כיון שנמשח דוד וכו׳ והרי המלכות לו ולבניו כו׳” ובה״ט שם. וראה צפע״נ סנהדרין שם. ועוד. ואכ״מ."],["50","50","ראה ספרי דבי רב שם בסופו."],["51","51","והיינו אף שהרמב״ם מדבר ב„בית הבחירה”, מ״מ לא הביא כתוב מפורש על בית הבחירה, אלא כתוב שבו מרומז משכן שילה. וכדלקמן."],["52","52","ורק כשבאו לשילה נאסרו הבמות (משא״כ בגלגל נוב וגבעון) והיא היתה מנוחה כו׳ (משנה זבחים קיב, ב) וראה גמרא שם קיט, א ואילך. ושם (ובספרי ראה יב, ט) גם דיעה „דנחלה זו שילה”. ובפיה״מ שם „נקרא שילה בית כו׳”. וראה ספרי תבוא (כו, ב) אל המקום אשר יבחר ה״א זה שילה ובית עולמים. רמב״ן שם. ובכ״מ הושוו שילה ובית עולמים. וראה ביאור הריי״פ פערלא לסהמ״צ רס״ג מ״ע פד־פה. ובכ״מ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241079\" data-slug=\"likkutei-sichot\" data-id=\"1300241079\">לקו״ש חכ״ד ע׳ 79</a> ואילך."],["53","53","רמב״ם הל׳ מלכים פ״א ה״ג."],["54","54","עפכהנ״ל מובן שינוי לשון הרמב״ם דבהל׳ ביהב״ח כ׳ הרמב״ם „לעשות בית”, ובהל׳ מלכים „לבנות”, וכ׳ הצפע״נ (מהד״ת ג, ב. עז, א) דל׳ „לעשות” פי׳ „שיהי׳” ול׳ „לבנות” פי׳ ד„המצוה היא הבנין”: בהל׳ ביהב״ח מבאר התוכן דמצות בנין ביהמ״ק (שבכל הזמנים וכמ״ש „בית ליי׳” (כנ״ל הערה 34) מוכן להיות מקריבים בו הקרבנות וחוגגין אליו כו׳) ולכן כ׳ „לעשות”* (ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111128\" data-slug=\"likkutei-sichot\" data-id=\"1300111128\">לקו״ש חי״א ע׳ 120</a> ואילך). משא״כ בהל׳ מלכים שמדבר ב„ג׳ מצות שנצטוו ישראל בשעת כניסתן לארץ” כ׳ „לבנות”, כי הוספת המצוה שם היא לא בעצם (תוכן) מצות בנין הבית, כ״א קיום מצות בנין בית הבחירה שלאחר מצות מינוי מלך, והכרתת זרעו של עמלק (אבל להעיר מצפע״נ שם ג, ב בהמשך דבריו, דכתב שזה החילוק דמשכן ומקדש. ואכ״מ)."],["55","55","הל׳ בית הבחירה פ״ז ה״י. מר״ה כד, א. ע״ז מג, א. מנחות כח, ב. *) וכ״ה בסהמ״צ שם בהוצאת קאפח. משא״כ בדפוסים שלפנינו: „לבנות”."]]],[1300161321,"[ביז אז אויך דער ביהמ״ק, הגם אז זיין ציור און די פרטים פון מדת ארכו ורחבו זיינען געווען אנדערש ווי אין משכן, פונדעסטוועגן זיינען די ענינים העקריים שבו געווען בדוגמת המשכן⁵⁶; ווי דער רמב״ם שרייבט⁵⁷: „ועושין מחיצה אחרת סביב להיכל רחוקה ממנו כעין קלעי החצר שהיו במדבר וכל המוקף במחיצה זו שהוא כעין חצר אהל מועד הוא הנקרא עזרה”⁵⁸],\nאיז י״ל אז דער איסור לעשות „בית תבנית כו׳” איז חל אויך אויפן נאכמאכן דעם תבנית פון משכן⁵⁹, פון משכן שילה⁶⁰\nאון נוב וגבעון.⁶¹",[["56","56","ולהעיר ממ״ש שם פ״א ה״יב „והכל חייבים לבנות כו׳ מקדש המדבר”. ובפ״ו ה״יא שם (הובא לעיל הערה 39). פ״ז ה״יא. ועוד. ולהעיר מפרש״י פרשתנו כה, ט. וברא״ם שם."],["57","57","שם פ״א ה״ה."],["58","58","ועפ״ז הנ״ל צע״ק מ״ש הרמב״ם לפנ״ז „ואלו הן הדברים שהן עיקר בבנין הבית כו׳ והוא הנקרא אולם” מנין שגם אולם הוא עיקר בבנין הבית כיון שלא הי׳ במשכן (ואולי מקורו מגמ׳ הנ״ל לא יעשה אדם בית תבנית — שחשב אולם). וראה קרית ספר שם דהא במשכן לא הי׳ אולם ואע״ג כו׳ אפילו הכי לענין קדושת הבית ליכא שינוי בין משכן למקדש דכמו במשכן ליכא אלא ג׳ קדושות כו׳ עיי״ש. ולהעיר מערובין ב, א. ובכ״מ. תוי״ט כלים פ״א מ״ט ד״ה ההיכל מקודש. וראה הר המורי׳ שם סק״י. ואכ״מ."],["59","59","יריעות העליונות הנעשים מעורות תחשים (פרשתנו כו, יד) א״א לעשות שהרי תחש הי׳ רק בזמן משה (שבת כח, א. פרש״י פרשתנו כה, ה). אבל מוכח בשבת שם דעיקר האהל הוו יריעות התחתונות, ובזה כבר נק׳ המשכן אהל. וראה צפע״נ (הפלאה בהשמטות נד, א) דאם קפל הרוח את היריעות העליונות המשכן כשר. וראה לקמן ע׳ 454־5."],["60","60","במנ״ח מצוה רנד סק״י שקו״ט בזה ורוצה לחדש (דלא כמשמעות הפוסקים ושו״ע) שהאיסור הוא רק בזמנו: בזמן המשכן הי׳ אסור לעשות כתבנית המשכן כיון שהי׳ אז משמש לפניו. וכן כשהי׳ שילה עומד וכן נוב וגבעון הי׳ אסור כ״ר הי׳ אסור לעשות בכ״ז מהזמנים איזה תבנית שהי׳ דוגמת התבנית שהי׳ משמש אז וכן בבית שני כשל בית שני כו׳, אבל האידנא כיון דאין משמשין לפניו אפשר דאין בכלל הלאו הזה. אבל הרי״ז נגד דעת הפוסקים טושו״ע יו״ד סקמ״א ס״ח דאסור גם עכשיו (כמ״ש שם בעצמו), וא״כ י״ל דגם דמות המשכן כו׳ אסור. ובשו״ת בית אפרים או״ח סוי״ד כ׳ דלדעת רש״י והרמב״ם (למסקנא) האיסור הוא גם בתבנית בית ראשון. וגם עפ״י דבריו י״ל שאסור גם בתבנית משכן. והנה במנ״ח שם הקשה דא״א לומר שעכשיו אסור כל הבנינים „דהיו מודיעים לנו חד״ל צורת המשכן שילה ג״כ כדי לידע תבניתו”. אבל מזה גופא שלא מפורש מדתו מוכח שמדת ארכו ורחבו כו׳ הי׳ כמו המשכן וכדמוכח מהיריעות שע״ג. וגם אם לא הי׳ בדומה ממש הרי״ז (בפשטות) לפי שלא הי׳ שינוי המעכב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381122\" data-slug=\"likkutei-torah\" data-id=\"4001381122\">לקו״ת ברכה (צח, ד</a>) „להבין ההפרש שבין משכן לבין בנין שילה כי לכאורה הם שוין ממש בארכן וברחבן וכל הפרטים כמו צורת המשכן כן נעשה בנין שילה”. וראה מאמרי אדה״ז הנחות הר״פ ע׳ פא. ולהעיר מסוטה (ט, סע״א) „זה משה ודוד שלא שלטו כו׳ נגנז אה״מ”. וראה יומא עב, א (סוכה מה, ב): „עצי שטים כו׳ עומדים שעומדין לעולם ולעולמים” (ובפרש״י שם). רבינו בחיי פרשתנו כו, טו״ו. ולפי״ז ג״ז הוא דמות שמשי שמשמש לפניו ית׳. ואף שזהו עפ״י דעת התוס׳ (ד״ה לא אסרה ר״ה כד, ב. ע״ז מג, ב. ד״ה כרובים — יומא נד, ב. מאירי ע״ז (מב, ב. מג, א). ר״ן ע״ז שם) דגם למסקנא לא חזר בו אביי והאיסור ד„לא יעשה אדם בית תבנית כו׳” הוא מטעם דלא תעשון אתי — כדמות שמשי כו׳ — ראה פנ״י ר״ה שם, א ד״ה אמר אביי. בית אפרים שם ד״ה אך מדברי רש״י. הרי עפ״י הכלל דאין להרבות במחלוקת י״ל שאסור גם לשיטת הרמב״ם דמשמע מהמשך ההלכות שהוא מדין מורא מקדש (כמ״ש בשו״ת בית אפרים ומנ״ח שם). וראה רבותינו בעה״ת (תשא ל, לג): „איש אשר ירקח כמוהו, וכן גבי קטורת לפי שאין דרך להשתמש בשרביט של מלך וכן אמרו חז״ל שלא יעשה אדם בית תבנית היכל כו׳”."],["61","61","עפמש״כ הרמב״ם „ובנו שם מקדש” ועפ״י הכלל דילמוד סתום מן המפורש י״ל לכאורה דמקדש דנוב וגבעון הוא כקודמו — שילה. ועפ״י פיה״מ וכו׳ (בהערה 47) הרי״ז אוהל מועד דהמדבר, וא״כ בין משכן שילה בין האוה״מ בלא״ה אסור*. ועפ״י הנ״ל שלהרמב״ם אסור גם לעשות תבנית משכן וכו׳ יומתק שזהו בדוגמת הכלים שבהמשך *) וראה צפע״נ עה״ת ר״פ תשא."]]],[1300161322,"יא. דער ביאור בזה בפנימיות הענינים:\nאינעם תוכן און סדר פון די ג׳ מצות איז חסידות⁶² מבאר, אז „שום תשים עליך מלך” איז די בחי׳ פון יראה, וואורום „מלך” איז ענינו — ירא את הש״י ביותר שאת, ער איז בטל צום אויבערשטן, און דורך דעם מלך וערט נמשך די יראה און ביטול צום גאנצן עם⁶³.\nאון אז מ׳דערגרייכט שוין צו דער בחינה פון יראה, דער ענין פון אתכפיא, דערנאך דארף זיין מחיית עמלק, דער ענין פון „ובערת הרע”, וואס דאס איז דורך אתהפכא; און ערשט דערנאך קען מען, און מען דארף, צוקומען צו דער מדריגה פון יראה עילאה, וואס דאס קומט דורך ביהמ״ק — „ומקדשי תיראו”⁶⁴, וואס די מדרגה פון יראה קומט פון בחי׳ חכמה, דער ענין התורה. און אזוי אויך בכל דור ודור, אויך בזמן הגלות משחרב ביהמ״ק — די ד״א של הלכה⁶⁵.\nאון עפ״ז וועט מען פארשטיין פארוואס דער ציווי אויף בנין ביהמ״ק און אויך דער בנין פון (ערשטן מקדש —) משכן בפועל, האט געדארפט זיין דוקא דורך משה רבינו (און ווי דער רמב״ם איז מדייק „וכבר נתפרש בתורה משכן שעשה משה רבינו”) — וואורום די המשכת הדעת צו יעדער אידן, וואס דורכדעם קומט מען צו צו יראה, איז ע״י משה⁶⁶ (ווי מיר געפינען, אז אויפן פסוק⁶⁷ „ועתה ישראל מה ה״א שואל מעמך כי אם ליראה” פרעגט די גמרא⁶⁸: „אטו יראה⁶⁹ מילתא זוטרתא היא?” און פארענטפערט: „אין לגבי משה מילתא זוטרתא היא”), און דעריבער האט התחלת ענין המלוכה (יראה תתאה) ביז דעם בנין המשכן (יראה עילאה) לאח״ז געדארפט קומען ע״י משה רבינו.\n[נאכמער: דער ענין המשכן והמקדש איז דאך כמרז״ל⁷⁰ „בתוכו לא נאמר אלא בתוכם” בתוך כאו״א מישראל, אז יעדער איד קען (און דארף) אויפטאן צו זיין אליין א משכן ומקדש — „ושכנתי בתוכם” — און דעם כח אויף דעם האט ער פון בחי׳ משה וואס איז דא ביי אים: און ווי דער אלטער רבי⁶⁶ איז עס מסביר, אז לגבי כל אחד ואחד מישראל איז יראה א „מילתא זוטרתא”, ווי עס שטייט אין פסוק „שואל מעמך”].\nאבער לאידך, איז שלימות פון מצות בנין המקדש געווען בבית עולמים, וואורום דער ענין המלכות בשלימות ובגלוי האט זיך אויפגעטאן דורך דוד המלך⁷¹, ביז צו דעם גילוי פון מלכות בתכלית השלימות, וואס וועט זיין ווען „יעמוד⁷² מלך מבית דוד הוגה בתורה",[["","","לזה (בהלכה שם) „שלחן בצורת שלחן ומנורה בצורת מנורה”, שצורתם הוא המפורש בתורה בנוגע למשכן. והטעם שלא כתבו הרמב״ם בפירוש הוא דמכללי הרמב״ם (יד מלאכי כללי הרמב״ם ס״ה) שאינו מביא דינים מחודשים שלא הוזכרו בש״ס."],["62","62","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470198\" data-slug=\"or-hatorah-hb\" data-id=\"8316470198\">אוה״ת בשלח ע׳ תרסו</a>."],["63","63","ראה גם דרמ״צ מצות מינוי מלך."],["64","64","קדושים יט, ל. בהר כו, ב."],["65","65","ברכות ח, א."],["66","66","<a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ״ב</a>."],["67","67","עקב י, יב."],["68","68","ברכות לג, ב."],["69","69","כ״ה בתניא. וכ״מ בע״י. וכ״ה בחדא״ג. עיין יעקב. ועוד. אבל בגמרא לפנינו: אטו יראת שמים."],["70","70","ר״ח (שער האהבה פ״ו ד״ה ושני). של״ה (שער האותיות אות ל׳). ובכ״מ."],["71","71","ראה בארוכה דרמ״צ שם. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470198\" data-slug=\"or-hatorah-hb\" data-id=\"8316470198\">אוה״ת שם ע׳ תרסו</a>."],["72","72","רמב״ם ספי״א מהל׳ מלכים."]]],[1300161323,"ועוסק במצות כדוד אביו כו׳ ויכוף כל ישראל לילך בה ולחזק בדקה וילחום מלחמות ה׳ וכו׳ ובנה מקדש⁷³ במקומו”,\nוואס דעמאלט וועט זיין דער ענין פון מלך בשלימות⁷⁴, און הכרתת זרעו של עמלק בשלימות — עס וועט זיין „השם שלם והכסא שלם”⁷⁵, דער גילוי מלכותו של הקב״ה⁷⁶, און שלימות אין בנין ביהמ״ק⁷⁷, א בנין נצחי וואס „מקדש⁷⁸ אדנ״י כוננו ידיך”⁷⁹, במהרה בימינו בקרוב ממש.\n(משיחת ש״פ דברים תשל״ו)",[["73","73","ראה לעיל הערה 49 שזהו הג׳ ענינים מינוי מלך הכרתת זרעו של עמלק ובנין ביהמ״ק."],["74","74","ראה דרמ״צ שם בסופו."],["75","75","תנחומא (ובאבער) ס״פ תצא. פסיקתא דר״כ ספ״ג. מדרש תהלים ט, ז. פס״ר פי״ב, ט. פרש״י ס״פ בשלח."],["76","76","ראה ברכות נח, סע״א. ובפרש״י שם. חדא״ג שם. מדרש תהלים (באבער) מזמור צז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470198\" data-slug=\"or-hatorah-hb\" data-id=\"8316470198\">אוה״ת שם ע׳ תרסו</a> ואילך (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370380\" data-slug=\"torah-or\" data-id=\"3901370380\">וראה תו״א פה, א</a>: „כסא מלכותו שום תשים עליך מלך כו׳”. צה, ג ואילך. ועוד). וגם מכהנ״ל מוכח מה שנת״ל ס״ו ובהערות שם דשלימות ענין מלחמת עמלק היא ע״י מלך. ושלימות גדר מלך כאשר הוא לוחם מלחמת עמלק. וראה הערה הבאה בבנין ביהמ״ק."],["77","77","וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450668\" data-slug=\"or-hatorah-hb\" data-id=\"8316450668\">אוה״ת שם (ע׳ תרסח</a>), <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450554\" data-slug=\"or-hatorah-hb\" data-id=\"8316450554\">תצא (ע׳ תתרכד</a>) — שכדי שיהי׳ בנין ביהמ״ק צ״ל השם שלם והכסא שלם. ולכן צ״ל תחלה שימחה זרעו כו׳."],["78","78","בשלח טו, יז. ובפרש״י שם. ומסיים: ואימתי יבנה בשתי ידים בזמן שה׳ ימלוך לעולם ועד."],["79","79","אף שזהו בעיקר לדעת רש״י ותוס׳ (סוכה מא, סע״א. פרש״י ר״ה ל, סע״א. תוס׳ שבועות טו, רע״ב ד״ה אין, וכ״מ בזהר ומדרשים), משא״כ לדעת הרמב״ם הנ״ל שמלך המשיח בונה מקדש — כבר נת׳ בכ״מ התיווך בזה, שמשיח יבנה השערים והדלתות — ראה בכהנ״ל <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111106\" data-slug=\"likkutei-sichot\" data-id=\"1300111106\">לקו״ש חי״א ע׳ 98</a> והערה 61. וש״נ."]]],[1300161324,"<h3>תרומה* ד</h3>\nא. אין דעם פסוק וואו עס ווערט געזאגט דער ציווי אויף בנין המשכן והמקדש — „ועשו לי מקדש״<sup data-n=\"1\">1</sup> ווערט אין זעלבן פסוק גלייך אויסגעפירט, אז די כוונה און תכלית פון דעם בנין איז: „ושכנתי בתוכם״, עס זאל זיין השראת השכינה במשכן ומקדש.\nפון די עיקרי העבודות בביהמ״ק איז געווען די עבודת הקרבנות<sup data-n=\"2\">2</sup>, און ווי דער רמב״ם<sup data-n=\"3\">3</sup> זאגט, אז תכלית מצות בנין המקדש איז דאס „לעבודה בו יהי׳ ההקרבה<sup data-n=\"4\">4</sup> והבערת האש תמיד״<sup data-n=\"5\">5</sup>. דערפון איז פארשטאנדיק, אז פון די עיקר׳דיקע כלי המקדש איז געווען דער מזבח החיצון, אויף וועלכן מ׳האט מקריב געווען די קרבנות (וואס וועגן דעם מזבח רעדט זיך אין סוף פון אונזער פרשה<sup data-n=\"6\">6</sup>),\nאון אויך דער מזבח הפנימי<sup data-n=\"7\">7</sup> (וואס וועגן אים שטייט דער ציווי אין סוף פ׳ תצוה<sup data-n=\"8\">8</sup>).\nאויף דעם פסוק „ועשו לי מקדש גו׳״ זאגן חז״ל<sup data-n=\"9\">9</sup>: „בתוכו לא נאמר אלא בתוכם — בתוך כאו״א מישראל״ אז יעדער איד דארף זיין א מקדש, ובמילא איז מובן אז יעדער איד דארף פועל זיין דורך זיין עבודה אז די שכינה זאל שורה זיין כביכול אין דעם „מקדש״ וואס אין אים.\nאיינער פון די ערטער, וואו חז״ל ריידן וועגן ביידע מזבחות און וואו עס איז מודגש זייער שייכות צום משכן ומקדש וואס אין יעדן אידן, איז עס אינעם סיום פון מס׳ חגיגה.\nב. אין (סוף פון) דער לעצטער משנה אין חגיגה ווערט געזאגט: „כל הכלים שהיו במקדש טעונין טבילה (נאך יעדער רגל האט מען געדארפט טובל זיין די כלי המקדש ווייל זיי זיינען טמא געווארן דורך דעם וואס עמי הארץ האבן זיי אנגערירט<sup data-n=\"10\">10</sup> חוץ ממזבח הזהב ומזבח הנחושת מפני שהן כקרקע דברי ר״א, וחכ״א מפני שהן מצופין״.",[["","","*) וסיום מס׳ חגיגה. וראה לקמן סעיף יג ולקמן ס״ע 434 ואילך."],["1","1","פרשתנו כה, ח. סהמ״צ להרמב״ם מ״ע כ׳. רמב״ם ריש הל׳ ביהב״ח."],["2","2","ראה ד״ה באתי לגני הש״ת רפ״ב ורפ״ג. וראה רמב״ן (דרשת תורת ה׳ תמימה — כתבי הרמב״ן ח״א ע׳ קס״ג): ולא שרתה שכינה במשכן אלא ע״י קרבנות .. ובבית המקדש נמי ע״י קרבן נבחר, עיי״ש. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111133\" data-slug=\"likkutei-sichot\" data-id=\"1300111133\">לקו״ש חי״א ע׳ 125</a> ואילך. ובהנסמן שם הערה 63."],["3","3","סהמ״צ שם. ובשורש יב. הל׳ ביהב״ח שם."],["4","4","ולכן לדעת הרמב״ם מצות בנין ביהמ״ק כוללת גם עשיית כלי המקדש המנורה והשלחן והמזבח וזולתם כלם מחלקי המקדש והכל יקרא מקדש (סהמ״צ שם. ובשורש יב שם) — נתבאר כהנ״ל ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111124\" data-slug=\"likkutei-sichot\" data-id=\"1300111124\">לקו״ש שם ע׳ 116</a> ואילך."],["5","5","וגם מה שממשיך „ואליו תהי׳ ההליכה והעלי׳ לרגל״ (סהמ״צ שם) — „וחוגגין אליו שלש פעמים בשנה״ (הל׳ ביהב״ח שם). הרי גם זה שייך לקרבנות — עולת ראי׳, שלמי חגיגה כו׳ (ראה רמב״ם ריש הל׳ חגיגה. ובפ״ב ה״ד שם)."],["6","6","כז, א ואילך."],["7","7","ראה ד״ה באתי לגני שם רפ״ג: „דלהיות שעיקר העבודה במשכן ומקדש .. שזהו ענין עבודת הקרבנות ובפרט מעשה הקטורת״ (שהם על מזבח הזהב). וש״נ."],["8","8","ל, א ואילך. וראה צרור המור ובמפרשי התורה שם."],["9","9","ר״ח (שער האהבה פ״ו ד״ה ושני פסוקים). שלי״ה (ש׳ האותיות אות ל׳. ועוד). ובכ״מ. נסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111117\" data-slug=\"likkutei-sichot\" data-id=\"1300111117\">לקו״ש שם ע׳ 109</a> הערה 10."],["10","10","ראה פרש״י במשנה שם כו, א (ד״ה מעבירין)."]]],[1300161325,"און די גמרא איז מסביר דעת ר״א: פון וואנען ווייס מען אז די מזבחות זיינען ווי קרקע (און דערפאר איז אויף זיי ניט חל קיין טומאה) — „מזבח הנחושת דכתיב<sup data-n=\"11\">11</sup> מזבח אדמה תעשה לי, מזבח הזהב דכתיב<sup data-n=\"12\">12</sup> המנורה והמזבחות איתקוש מזבחות זה לזה״.\nדערנאך שטעלט זיך די גמרא אויף „וחכ״א מפני שהן מצופין״ (אננעמענדיק אז זיי זאגן דערמיט א טעם פארוואס די מזבחות ווערן ניט טמא) און פרעגט: „אדרבה, כיון דמצופין נינהו מיטמאו״ (און רש״י איז מפרש: ווארום ווען ניט דער ציפוי וואלט זיי דאך געדארפט זיין טהור צוליב דעם וואס זיי זיינען „כלי עץ העשוי לנחת״<sup data-n=\"13\">13</sup>); און די גמרא ענטפערט: „אימא וחכמים מטמאין מפני שהן מצופין (אז די חכמים זיינען מחולק מיט ר״א און זיי האלטן אז אויך די מזבחות זיינען טמא געווארן טאקע צוליב זייער ציפוי. נאך א תירוץ ענטפערט די גמרא:) ואב״א רבנן לר״א קאמרי מאי דעתיך משום דמצופין מיבטל בטיל צפויין גבייהו״<sup data-n=\"14\">14</sup>.\nלערנט רש״י: די רבנן זאגן צו ר״א „מאי דעתיך״, אז דאס וואס ר״א דארף אנקומען צום טעם וואס די תורה רופט זיי אן „אדמה״ און נאר דערפאר זיינען זיי טהור — און ס׳איז דערויף ניט גענוג דער טעם וואס זיי זיינען „כלי עץ העשוי לנחת״, ווייבאלד זיי זיינען „מצופין״ און דאס איז זיי מבטל פונעם גדר „עץ״: זאגן דערויף די רבנן אז: „מיבטל בטיל צפויין גבייהו״, אז היות די תורה רופט זיי אן „עץ״ מיינט עס, אז דער ציפוי של מתכת ווערט נתבטל לגבי זיי (זיי באקומען אינגאנצן דעם גדר פון „עץ״) און במילא זיינען זיי ניט מקבל טומאה.\nדער רמב״ם<sup data-n=\"15\">15</sup> אבער לערנט, אז דאס וואס די רבנן זאגן „מפני שהן מצופין״ איז עס (ניט געמיינט ווי א טעם לטמא לויט דעת ר״א, נאר) א טעם לטהר לויט זייער שיטה — ס׳איז ווי דער ספרא זאגט אויפן פסוק<sup data-n=\"16\">16</sup> „כל כלי אשר יעשה מלאכה בהם״: „יכול שאני מרבה את חפויי כלים ת״ל בהם פרט",[["11","11","יתרו כ, כא."],["12","12","במדבר ג, לא."],["13","13","דאינו מקבל טומאה ד„דומיא לשק בעינן כו׳״, כבגמ׳ שם לפנ״ז (כו, ב)."],["14","14","ולכאורה צ״ע, דהרי מדובר כאן בכלים שהיו במקדש ואעפ״כ קוראו מזבח הנחושת וצריך לטעם דאקרי אדמה או דבטל ציפוי לגבי העץ, הרי רק מזבח דמשכן הי׳ מעצי שטים מחופה נחושת (כבפרשתנו שם), אבל של ביהמ״ק הי׳ מאבנים כו׳ (וראה שבת נה, א ובפרש״י ותוס׳ שם, ו„האי רצפה״ (זבחים כז, ב) ו„בניך״ (שם ס, א. וראה פרש״י ותוס׳ שם) שאין בה דין טומאה. ובתויו״ט כאן תירץ: „אילו הי׳ מזבח הנחושת כבימי מרע״ה א״נ אם לעתיד יעשוהו משל נחושת כו׳״. וראה תוס׳ כאן ד״ה מזבח. אבל הל׳ במשנה „כל הכלים שהיו במקדש כו׳״ (ועד״ז כמ״פ לפנ״ז) צע״ק. וברלב״ג (ועוד) למ״א (ח, סד) דגם מזבח שעשה שלמה הי׳ מצופה נחושת. וראה רי״פ פערלא לסהמ״צ רס״ג מנין הפרשיות ר״פ נה נו. אמנם בנוגע למזבח הזהב לדעת הרמב״ם מוכרח לכאורה לפרש (במשנה וגמרא) כאן. כמו שתירץ התויו״ט (בתו׳ הא׳), שהרי הרמב״ם (ביהב״ח פ״א הי״ח) כ׳: „ומזבח הקטורת .. אין עושין אותן אלא מן המתכות בלבד״ (וכ״ה באוה״ח פרשתנו כה, ט סד״ה ואני אומר). או י״ל (בדוחק עכ״פ) דאזיל בזה לשיטתו בדין ציפוי שציפם בטלן (ראה לקמן בפנים ובהערות). אבל לכמה דיעות הי׳ מזבח הזהב של משה גם במקדש (ראה פרש״י זבחים כז, סע״ב). או שגם מזבח הזהב של שלמה הי׳ מחופה זהב, כהכי במ״א ו, כ-כא ובמפרשים שם. וראה צפע״נ עה״ת תצוה ל, יוד. תו״ש מילואים לפ׳ תצוה (חכ״ג). ואכ״מ."],["15","15","פיה״מ כלים פ״א מ״ד. וראה רמב״ם הל׳ מטמאי משכב ומושב פ״א הי״א (בסופו)."],["16","16","שמיני יא, לב."]]],[1300161326,"לחפויי כלים״, אז אויב דער שימוש איז ניט אינעם גוף הכלי, נאר דורכן חיפוי (ציפוי) הכלי, איז די כלי ניט מקבל טומאה.\nאון ווי מ׳איז מבאר<sup data-n=\"17\">17</sup> שיטת הרמב״ם, לערנט ער דעם פשט פון „מיבטל בטיל צפויין גבייהו״, אז, לויט די רבנן איז ציפוי ניט קיין סיבה צו מטמא זיין די כלי (ווי דאס זאגט ר״א), נאר פארקערט, דער ציפוי (פון מתכת) איז א טעם צום מטהר זיין — זייענדיק בלויז א ציפוי צו דער כלי איז ער במילא בטל צו דער כלי און קען דעריבער ניט אויפטאן אין איר דעם דין פון קבלת טומאה; און די כלי ווידער, מצד זיך אליין (בשעת זי האט א בית קבול) קען אויך ניט טמא ווערן, ווייבאלד אז דער שימוש אין איר איז דורך אמצעות הציפוי, און א כלי מצופה ומחופה איז נתמעט פון דין טומאה<sup data-n=\"18\">18</sup>.\nדערפון קומט אויס אז רש״י<sup data-n=\"19\">19</sup> און דער רמב״ם זיינען מחולק אינעם גדר פון דין ציפוי לויט די רבנן. לויט שיטת רש״י קומט אויס, אז א ציפוי פון מתכת ביי כלי עץ איז א סיבה צו מטמא זיין די כלי אויך לפי דעת רבנן (נאר ביי די מזבחות האלטן די רבנן אז זיי זיינען טהור דערפאר וואס די תורה רופט זיי אן „עץ״); און לפי דעת הרמב״ם איז ציפוי כלים בכלל א טעם צו פארמיידן דין טומאה פונעם כלי המצופה כנ״ל<sup data-n=\"20\">20</sup>.\nדארף מען פארשטיין: וואס איז דער טעם וסברא וואס דער רמב״ם לערנט אנדערש (די מחלוקת צווישן ר״א מיט די חכמים) ווי רש״י; ובפרט אז דער לשון הגמרא (ואב״א רבנן לר״א קאמרי כו׳) איז גלאטיקער לפי שיטת רש״י, ווי מפרשים זיינען עס מסביר<sup data-n=\"21\">21</sup>.\nג. עס איז נתפשט דער מנהג<sup data-n=\"22\">22</sup> צו",[["17","17","כ״מ פ״ד מהל׳ כלים ה״ד, בשם הר״י קורקס (הובא בתויו״ט בסוף חגיגה)."],["18","18","מפיהמ״ש שם מובן שכוונת הדרשא בספרא „פרט לחפויי כלים״ ר״ל שזה הכלי לא יגיע השימוש בו בעצמו, אבל באמצעות הכיסוי אשר עליו, שכלי שמצ״ע הי׳ מקבל טומאה — מצד הציפוי טהור. וכמו שמסיים „כאשר חפה אותן ביטל אותן״. אבל בפ״ד מהל׳ כלים שם הביא דרשת הספרא לענין זה שהחפויין עצמם טהורים. ובהמשך לזה כ׳: „וכן כלי עץ כו׳ שיש בהן בית קבול שציפם במתכת טהורים ואין מקבלין טומאה מאחר שציפם ביטלן והציפוי עצמו טהור כמו שביארנו״. אבל גם שם צ״ל דזה שהציפוי מבטל להכלי, הכוונה שמבטל דין טומאתו, וג״ז נלמד מהספרא וכל׳ — „וכו׳״. ואכ״מ."],["19","19","וכ״ה דעת הראב״ד בהל׳ כלים שם. ופי׳ הרא״ש במס׳ כלים שם. ועוד. וכ״ה דעת המאירי כאן, שכ׳ בטעם חכמים „הרי כלי בית המקדש אינם בטלים לגבי צפוים אלא צפוים בטל אצלם״."],["20","20","לפי פי׳ מהר״י קורקס שם דהטעם „מפני שהם מצופים״ — „מיבטל בטל צפויין גבייהו״, היינו „דציפויין לא מיטמאי דבטלים אגב כלי דלא חשיבי כדי שיטמא הכלי בשבילו והכלי בשביל עצמו ודאי אינו טמא כיון שמצופה״, מובן, שהטעם שהמזבחות טהורות הוא רק מפני שמצופין, ובלא״ה היו המזבחות מקבלין טומאה. וכ״מ מפיה״מ שם. אבל לכאורה א״מ דהרי בלא״ה היו טהורין כיון שהם עשויין לנחת וכו׳, וכמ״ש ברע״ב כאן „צפויין בטיל לגביהו והוו ככלי עץ העשויין לנחת שאינן מטמאין״. (ומסיים „כך פי׳ הרמב״ם בהל׳ מטמאי משכב ומושב״). ראה תויו״ט שהקשה עליו דדבריו סותרין זא״ז. וכ״כ במל״מ (כלים שם) ומפרש עפ״ז ל׳ הגמרא „לר״א קאמרי״. ואולי י״ל (בדוחק עכ״פ) דהרמב״ם סמיך על הדרשא דירושלמי (כאן) „איר הילא טעמא דרבנן .. התורה קראת אותו מיטלטל, עיי״ש. אלא שלפי פי׳ הקה״ע ופ״מ בא ר׳ הילא לפרש טעם רבנן שמטמאין ועיי״ש בהמשך הירושלמי. והרמב״ם ס״ל רק עצם הדרשא שהתורה קראן מיטלטל. ולכן צריכים חכמים לפרש דטעם טהרתם מפני שהם מצופים. ואכ״מ."],["21","21","ראה פי׳ הרא״ש כלים שם, שכ׳ על דברי הרמב״ם שם „והוא עיקר במשנה ולא עיין בגמרא״. וראה דברי הר״י קורקס שם „וצריך לדחוק״, ובמל״מ שם."],["22","22","וכבר העירו באחרונים מברכות י, רע״א. ובתוס׳ שם. וראה ספר ויהא ברכה."]]],[1300161327,"פארבינדן — אין א הדרן — סיום המסכת מיט איר התחלה<sup data-n=\"23\">23</sup>, וואס דער טעם דערפון איז ניט לפלפולא ולחדודי בעלמא<sup data-n=\"24\">24</sup>, נאר ווייל זיי האבן טאקע א שייכות וקשר אין תוכן ענינם<sup data-n=\"25\">25</sup> — ועד״ז בנדו״ד — בסיום מס׳ חגיגה מיט התחלתה, וכדלקמן.\nד. דער ביאור אין דעת הרמב״ם קען מען זאגן: דער רמב״ם נעמט אן, אז די מחלוקת דא צווישן רבנן און ר״א — וואס ר״א שמותי הוא: פון תלמידי ב״ש<sup data-n=\"26\">26</sup> — איז פארבונדן<sup data-n=\"27\">27</sup> און איז א לשיטתי׳ און סברא כללית וואס איז א יסוד צו פילע אנדערע פלוגתות צווישן ב״ש און ב״ה<sup data-n=\"28\">28</sup>. ד. ה. היות אז אין א צאל פלוגתות פון ב״ש וב״ה געפינט מען א צד השווה אין זייערע דיעות — און דאס איז אזוי בנוגע פארשידענע סוגיות והלכות אין ש״ס<sup data-n=\"29\">29</sup> — איז מסתבר אז דער יסוד פון זייערע מחלוקת (אין די ערטער) איז ניט מצד דעם באזונדערן תוכן פון יעדער מחלוקת בפ״ע, נאר זיי זיינען אלע מיוסד אויף איין יסוד — וכמסקנת הש״ס בכ״מ אז מ׳גייט לשיטתי׳ 29*).\nולדוגמא — עכ״פ אין פלוגתא בכל סדר:\nה. אין סדר זרעים — אין מס׳ ברכות<sup data-n=\"30\">30</sup> בנוסח הברכה אויף „אש״ במוצש״ק געפינען מיר א פלוגתא צווישן ב״ש און ב״ה: ב״ש אומרים שברא מאור האש וב״ה אומרים בורא מאורי האש. און די גמרא<sup data-n=\"31\">31</sup> איז מסביר זייער מחלוקת „דב״ש סברי חדא נהורא איכא בנורא״ — אין אש איז דא בלויז איין (גוון) אור, און דערפאר דארף מען זאגן „מאור״ בל׳ יחיד. „וב״ה סברי טובא נהורי איכא בנורא, תנ״ה אמרו להם ב״ה לב״ש הרבה מאורות יש באור (אין אש זיינען דא מערערע גוונים: שלהבת אדומה לבנה וירקרקת<sup data-n=\"32\">32</sup>״ — דערפאר דארף מען זאגן „מאורי״ ל׳ רבים.\nעס איז פשוט אז ב״ש וב״ה קריגן ניט אין א מציאות — וואס במציאות זעט מען אז עס זיינען דא איינציקע גוונים אינעם אור, טא ווי זאגן ב״ש אז חדא נהורא איכא בנורא<sup data-n=\"33\">33</sup>?\nנאר דער הסבר דערפון איז: ב״ש האלטן אז ע״פ תורה ווערן ענינים בעיקר באשטימט אויפן יסוד פון זייער תוכן הכללי, ווי זיי ווערן גענומען באם ערשטן כלליות׳דיקן גדר (בליק)<sup data-n=\"34\">34</sup>. (ע״ד",[["23","23","וע״ד מתכיפין התחלה להשלמה („רשות לחתן בראשית״)."],["24","24","שהרי הזהירו עד״ז בתוקף המהר״ל והשל״ה וכו׳ — הובאו בקונט׳ עה״ח פל״א."],["25","25","ולהעיר מספר יצירה פ״א מ״ז: נעוץ סופן בתחלתן ותחלתן בסופן."],["26","26","רש״י (ד״ה שמותי) ותוס׳ (ד״ה דר״א שמותי) — שבת קל, ב. תוד״ה שמותי — נדה ז, ב."],["27","27","ראה תוס׳ ד״ה ואומר ביצה לד, רע״ב שמקשה בפשיטות מפלוגתת ר״א וחכמים, ש„מחלפא שיטתייהו דב״ש וב״ה״."],["28","28","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061070\" data-slug=\"likkutei-sichot\" data-id=\"1300061070\">לקו״ש ח״ו (ע׳ 70</a> ואילך), <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071126\" data-slug=\"likkutei-sichot\" data-id=\"1300071126\">ח״ז (ע׳ 114</a> ואילך), סה״ש תשמ״ח ח״ב (ע׳ 647 ואילך) — עוד סברא כללית ושיטה במחלוקת ב״ש וב״ה. וראה מפענ״צ פרק א׳ סי׳ ג. ועוד."],["29","29","אבל בכ״ז צ״ל צריכותא בכל מחלוקת, שלכן צריך לאשמעינן בכל ענין בפ״ע דפליגי. 29*) ראה שבת לד, ב."],["30","30","נא, ב."],["31","31","שם נב, ב."],["32","32","פרש״י שם."],["33","33","ראה שנו״א להגר״א שם. ועיי״ש שמפרש שתלוי׳ גם במחלקותם דברא ובורא. אבל לכאורה בפשטות (ראה תוס׳ שם ד״ה בברא (ובצל״ח שם דהתוס׳ כתבו כאן לפי המסקנא)), גם למסקנא דבברא ובורא כ״ע לא פליגי נקט ב״ה בורא דלשון קרא עדיף."],["34","34","ואי״ז מצד העדר השקו״ט וכו׳, שהרי אדרבא ב״ש מחדדי טפי מב״ה (יבמות יד, א), חריפי טפי (תוד״ה כאן עירובין ו, סע״ב), אלא שהחריפות הוא יותר בגדר הכללי, או למצוא בכל פרט את הכלל."]]],[1300161328,"הכלל „אין לו לדיין אלא מה שעיניו רואות״<sup data-n=\"35\">35</sup>. די שיטה פון ב״ה איז, אז מ׳דארף זיך בעיקר רעכענען מיט דעם ווי די ענינים ווערן פאנאנדערגעקליבן לויט זייערע פרטים און אופנים, הגם די פרטים זיינען ניט ניכר גלייך און מ׳דארף האבן דרישה וכו׳ — און דווקא דאס איז מכריע אין דיני התורה<sup data-n=\"36\">36</sup>.\nדערמיט איז מובן דער טעם פון זייער מחלוקת: דער דין בא ברכת הנר איז, אז „אין מברכין על הנר עד שיאותו לאורו״<sup data-n=\"37\">37</sup>, דער חיוב פון דער ברכה איז נאר דאן ווען מ׳קען<sup data-n=\"38\">38</sup> הנאה האבן, אדער מ׳האט הנאה בפועל פון דעם אור. די הנאה קומט גלייך ביים דערזען דעם אור בכללות וואס דאמאלסט זעט ער סתם אור, איין ליכט־גוון („חדא נהורא״), דעריבער האלטן ב״ש אז אויך די ברכה דארף זיין אויף דער בריאה<sup data-n=\"39\">39</sup> פון כללות האש: „מאור האש״.\nדאקעגן ב״ה נעמען אן די שיטה, אז ווייבאלד בהתבוננות אינעם אש דערזעט ער כמה מאורות ובפועל קומט דאך די הנאת האור פון די אלע גווני נהורא — דארף דעריבער דער נוסח הברכה זיין „בורא מאורי האש״<sup data-n=\"40\">40</sup>.\nו. אין סדר נשים — אין מס׳ כתובות<sup data-n=\"41\">41</sup>: „כיצד מרקדין לפני הכלה ב״ש אומרים כלה כמות שהיא (לפי יופי׳ וחשיבותה מקלסין אותה — פרש״י) וב״ה אומרים כלה נאה וחסודה. אמרו להן ב״ש לב״ה הרי שהיתה חיגרת או סומא אומרים לה כלה נאה וחסודה והתורה אמרה<sup data-n=\"42\">42</sup> מדבר שקר תרחק אמרו להם ב״ה לב״ש לדבריכם מי שלקח מקח רע מן השוק ישבחנו בעיניו או יגננו בעיניו הוי אומר ישבחנו בעיניו״.\nעס איז דאך פשוט, אז אויך לויט ב״ה איז פאראן דער ציווי „מדבר שקר תרחק״<sup data-n=\"43\">43</sup>, און אז אויך לויט ב״ש, איז בשעת איינער קויפט א „מקח״ דארף מען עס פאר אים משבח זיין<sup data-n=\"44\">44</sup>.\nנאר אויך דא איז דער הסבר, אז זיי גייען לשיטתם: ב״ש האלט, מ׳דארף אלעמאל אננעמען די זאך ווי זי זעט אויס גלייך לויטן כלליות׳דיקן „בליק״; און היות אז ביי אט דער כלה זיינען אט",[["35","35","סנהדרין ו, סע״ב. וש״נ. וראה שו״ת נו״ב או״ח מהדו״ק סל״ה."],["36","36","בסגנון אחר קצת: לב״ש קובע הוא מצב וענין הדבר כמו שהוא לפניו. ולב״ה — סיבת המצב והענין או המסובב שלו — זהו קובע."],["37","37","ברכות במשנה שם."],["38","38","ראה פרש״י שם. ובירושלמי שם ה״ו מחלוקת בגי׳ המשנה. וראה הערה הבאה."],["39","39","ולא על ההנאה (אלא שמברכין בעת ההנאה) — ראה בגמרא שם (נג, ב) ובהערה הבאה."],["40","40","אבל אין לומר שפליגי בפלוגתת האמוראים (שם נג, ב) אם יאותו ממש או לא יאותו ממש אלא שאילו הי׳ עומד בקירוב ומשתמש לאורה, שלב״ש צריך שיהנה ממש ולכן לדעתם צריך לברך „מאור האש״ כי ההנאה היא מכללות אור האש ולא מפרטי הגוונים. וב״ה ס״ל לא יאותו ממש, ולכן מברכין „מאורי האש״ כי הברכה (בעיקר) היא על עצם בריאת מאור האש, ובאור עצמו יש כמה גוונים. כי א) אין לומר שפלוגתת ב״ש וב״ה היא פלוגתת האמוראים, ב) ורבא שס״ל יאותו ממש והלכה כמותו (רמב״ם הל׳ שבת פכ״ט הכ״ה. טושו״ע סי׳ רצ״ח ס״ד (שו״ע אדה״ז ס״ו)) הוא לפי דעת ב״ש. ג) מפורש בגמרא שבברא ובורא כו״ע לא פליגי דברא משמע לשעבר, והיינו שהברכה היא על עצם בריאת האור. ולדעת ב״ש בפרט מברכין בל׳ ברורה ברא לשעבר. ד) בהשגות הראב״ד להמאור (וכ״כ המאירי) שגם לרבא שיאותו ממש אין הכוונה שישתמש לאורו ואח״כ יברך, אלא שיהי׳ קרוב כ״כ כדי שיוכל להשתמש לאורה. אבל ראה שו״ת צפע״נ (דווינסק) ח״ב ס״י (נעתק בכללים בערכו)."],["41","41","טז, סע״ב ואילך. דרך ארץ רבה ספ״ו."],["42","42","משפטים כג, ז."],["43","43","אבל ראה תוס׳ ר״ה ד״ה „ואע״פ שאומר שקר״. וכן משמע מתוד״ה כלה. וד״ה ישבחנה. ריטב״א ועיון יעקב כאן. וראה כלה רבתי רפ״י."],["44","44","ראה תוד״ה ישבחנה שם."]]],[1300161329,"די מעלות פון „נאה וחסודה״ ניט אנזעענדיק, האט קיין ארט ניט איר צו מקלס זיין מיט אט די מעלות, נאר ווי מ׳זעט גלייך — „כלה כמות שהיא״.\nאון ב״ה האלטן, לשיטתם, אז מ׳דארף נעמען אין באטראכט די פרטים, ווי מ׳זעט זיי בהתבוננות: היות אז דער חתן לקח מקח — האט אויסגעקליבן אט די כלה, איז א פשיטות אז אין זיינע אויגן איז זי א „נאה וחסודה״ 44*) [און עפ״ז יומתק דער המשך „מכאן אמרו חכמים לעולם תהא דעתו של אדם מעורבת עם הבריות״, ווארום פון דעם זעט מען אז ווייבאלד אז „אין דיעותיהן שוות״<sup data-n=\"45\">45</sup> — מוז מען יעדן איינעם שאצן לויט זיין באזונדער דעה, וע״ד אל תדין את חברך עד שתגיע למקומו<sup data-n=\"46\">46</sup> (בכל הפירושים שב„מקום״) און דורכדעם קומט מען צו אז מ׳ווערט מעורב אפילו „עם הבריות״].\nבמילא איז אויך מובן אז לדעת ב״ה איז דאס ניט קיין שקר<sup data-n=\"47\">47</sup>, ווארום נאך דער התבוננות בפרטיות זעט מען אז ביחס צו אט דעם חתן איז זי טאקע א „כלה נאה וחסודה״. משא״כ לויט ב״ש, אז דער כלליות׳דיקער גדר וראי׳ איז קובע, קען מען אויף א „חיגרת וסומא״ ניט זאגן „כלה נאה וחסודה״, און במילא גייט דאס אריין אין גדר פון „מדבר שקר תרחק״<sup data-n=\"48\">48</sup>.\nז. אט דער לשיטתי׳ וואס שפיגלט זיך אפ אין די פלוגתות פון ב״ש וב״ה, ווערט נאכמער באגרינדעט און מובן דורכדעם וואס מ׳געפינט דעם לשיטתי׳ בא שמאי והלל אליין — און דאס איז אין צוויי פאלן וואו דער לשיטתי׳ איז מודגש במיוחד: אין ערשטן פאל איז די הדגשה אין דעם וואס צוליב דעם לשיטתי׳ איז שמאי לקולא און הלל לחומרא (בהיפך פון זייער שיטה בכלל)<sup data-n=\"49\">49</sup>, און אין צווייטן איז דאס מודגש דורך „מעשה רב״ — אזוי האבן זיך שמאי והלל אליין געפירט במעשה בפועל.\nאין סדר נזיקין — מס׳ עדיות<sup data-n=\"50\">50</sup> לערנען מיר: שמאי אומר כל הנשים דיין שעתן והלל אומר מפקידה לפקידה אפילו לימים הרבה. שמאי זאגט אז אן",[["","","44*) ראה סוטה מז, א: חן אשה על בעלה (ובפרש״י שם)."],["45","45","ראה ברכות נח, רע״א. סנה׳ לח, א. דרך ארץ פ״ט."],["46","46","אבות פ״ב מ״ד („הלל אומר״). וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310035\" data-slug=\"tanya\" data-id=\"3401310035\">תניא פ״ל</a>."],["47","47","עד״ז כתב בחדא״ג כאן. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381322\" data-slug=\"likkutei-torah\" data-id=\"4001381322\">לקו״ת שה״ש מח, ג</a> בהגהה."],["48","48","והחידוש בשיטתם בכ״א ממקומות הנ״ל (שלכן צריכי לומר שניהם): באם הי׳ מפרש המחלוקת שלהם רק בכלה אפ״ל דבנר גם ב״ש ס״ל כב״ה, כי בכלה, הרי במציאות (רואים ו)ישנן מומין גלויים — חיגרת וסומא (אלא שלגבי דעת האיש (המקדש) היא „נאה וחסודה״), אבל בנר, הרי במציאות ישנם כמה גוונים באש *). ומטעם הנ״ל אם הי׳ נאמר מחלוקתם רק בנר, אפ״ל דבכלה גם ב״ה מודים לב״ש. וכן להיפך י״ל — דבכלה גם ב״ש מודי כיון דהקב״ה שינה מפני השלום (כלה רבתי שם)."],["49","49","ולכן הובא (לקמן בפנים) מחלקותם ממס׳ עדיות — ראה תוי״ט ריש נדה. ועוד: ד„בחירתא היא״ (ברכות כז, א)."],["50","50","בתחילת המסכת (ובריש נדה). *) וגם לדעת ב״ה ישנו חידוש במחלוקת דנר (שלא היו יודעים מדעתם בכלה): שהרי המדובר הוא בבריאת האור (מהקב״ה) (גם אם נאמר דל׳ בורא פי׳ שהוא בורא תמיד) ובפרט שגם לדעת רבא סברי ב״ה בורא נמי ברא (לשעבר) משמע — בריאת האור בשימ״ב (ראה פרש״י שם)) וחילוק המאורות שיש באש אי״ז מצד עצם בריאת האש כ״א תלוי בקירובו וריחוקו מהפתילה או מן העץ (וראה מאירי כאן)."]]],[1300161330,"אשה וואס איז רואה דם איז זי מטמא טהרות וואס זי רירט אן פון דער ראי׳ און ווייטער, אבער ניט די וואס זי האט אנגערירט פאר דער ראי׳. הלל זאגט אז זי איז מטמא אויך די טהרות וואס זי האט אנגערירט פון זינט נאך דער לעצטער טהור׳דיקער בדיקה.\nאון די גמרא<sup data-n=\"51\">51</sup> איז מסביר (אין דעם ערשטן טעם): „שמאי קסבר העמד אשה על חזקתה ואשה בחזקת טהורה עומדת, והלל כי אמר העמד דבר על חזקתו היכא דלית לי׳ ריעותא מגופי׳ אבל איתתא כיון דמגופא קחזיא לא אמרינן אוקמא אחזקתה״.\nוואס דא זעט מען דעם זעלבן קו אין זייערע דעות: שמאי האלט, אז מ׳קוקט אויף א זאך ווי זי זעט זיך (אדער זעט זיך ניט) גלייך פאר די אויגן — און דערפאר איז די שעתה, דער זמן פון דער ראית דם בפועל און ניט אויף פריער, ווען ס׳ניט געווען קיין ראי׳ (און מ׳שטעלט זי דעריבער אויף דער חזקה). הלל האלט אבער אז מ׳באנוגענט זיך ניט מיט׳ן ענין עינים רואות בכלל, נאר מען דארף חוקר זיין פרטי הענין וואס ראתה דם, אז דאס וואס ראתה איצט (שעתה), איז דאס א מסובב, ווייל ס׳איז דא א ריעותא בגופא, די זאך פון דער ראי׳ איז אן ענין טבעי ביי אן אשה<sup data-n=\"52\">52</sup>. און מהאי טעמא קען מען זי ניט שטעלן בחזקת טהרה, און די טהרות זיינען טמא (מספק<sup data-n=\"53\">53</sup> עכ״פ).\nח. אויך אין סדר מועד — מס׳ שבת<sup data-n=\"54\">54</sup> זעט מען אט דעם אונטערשייד אין די שיטות פון שמאי און הלל — אין די דריי פאלן, וועגן א נכרי וואס איז געקומען זיך מגייר זיין:\nאין איין פאל האט דער נכרי געזאגט „גיירני ע״מ שתלמדני (נאר) תורה שבכתב״; אין צווייטן פאל האט ער געזאגט „גיירני ע״מ שתלמדני כל התורה כולה כשאני עומד על רגל אחת״ און אין דריטן פאל האט ער געזאגט „גיירני ע״מ שתשימני כהן גדול״. און אין די אלע דריי פאלן איז שמאי האט זיי דוחף (דוחה) געווען און הלל האט זיי מקבל און מגייר געווען.\nאיז דאך ניט מובן, ממ״נ: ווייבאלד ס׳איז דא דער כלל, אז מ׳דארף זיך אפהאלטן פון מקבל זיין גרים אין א לייכטן אופן — ובפרט אז דא האנדלט זיך וועגן גרים וואס זאגן קלאר אז זייער גירות",[["51","51","נדה ב, סע״א ואילך."],["52","52","ראה פרש״י שם, רע״ב ד״ה כיון. וראה פרש״י שם ד״ה תרתי."],["53","53","ומטעם זה עדיפות במחלקותם דנר, כלה ושבת (דלקמן), כי בנדה: א) זה שלא אוקמינן אחזקתה הוא רק סיג בקדשים, אבל לחולין גם ב״ה מודים דאוקמה לה בחזקת טהרה (ראה תוס׳ ריש נדה. תוד״ה ואב״א — שם ג, א). ב) בגמ׳ שם (ג, א) קאמר עוד טעמים למחלוקת שמאי והלל. אבל: א) ע״י תוד״ה ואב״א שם דגם לפי הטעם דאשה מרגשת כו׳ נמי צריך לטעמא דהעמד אשה על חזקתה (אבל ראה גליון התוס׳ שם). ב) גם לפי המסקנא — דעת רבא שם (ג, ב) דטעמא דשמאי משום בטול פרי׳ ורבי׳ כו׳ (וכ״פ הרמב״ם בפיה״מ, רע״ב וכו׳) מודגשת שיטתי׳ הנ״ל: לדעת שמאי אם יעשו סיג בטהרות לא יבחין האדם בפרט זה ויהי׳ לבו נוקפו ופורש, והלל ס״ל דלביטול פו״ר לא חיישינן, כי האדם יבחין בפרטי הדבר ויבין שמטמאינן לה רק לטהרות כו׳. ראה בגמ׳ שם ובל׳ הרע״ב כאן ובעדיות. אבל להעיר: א) שאין הלכה כהלל, כ״א כחכמים שאומרים „לא כדברי זה ולא כדברי זה אלא מעל״ע כו׳״. ב) ועיקר: דעת שמאי „כל הנשים דיין שעתן״ הוא (כבגמרא שם ג, א) לאפוקי מר״א דרק ד׳ נשים דיין שעתן, והלכה כמותו לגבי ר״י (שם ז, סע״א ואילך), אף שגם בזה י״ל ע״ד הסברא שבמחלוקת שמאי והלל, דר״א ס״ל דבכל ד׳ נשים אוקמינהו אחזקה. ור״י ס״ל רק בבתולה דאלים חזקתה, ראה משנה אחרונה שם. ואכ״מ."],["54","54","לא, א."]]],[1300161331,"איז „ע״מ״, וואס איז א תנאי שלא כדבעי [און בשעת איינער קומט מגייר זיין בכדי צו דערגרייכן דורכדעם א שררה וכיו״ב, אדער ער איז ניט מקבל אויף זיך גאנץ תורה, איז מען אים ניט מקבל]<sup data-n=\"55\">55</sup> — היינט ווי אזוי האט הלל זיי מקבל געווען<sup data-n=\"56\">56</sup>? און אויב ביי אט די גרים איז די קבלת גירות יא געווען כדבעי, און ווי מ׳זעט טאקע בפועל אז זיי זיינען געווארן אמת׳ע גרים — איז ווי קומט עס וואס שמאי האט זיי אפגעשטופט?\nדי הסברה איז כנ״ל: ביי שמאי, לשיטתו, האט מכריע געווען דעם עיניו רואות בכלל, די כלליות׳דיקע משמעות פון זייערע רייד און אופן קבלת הגירות — און ווייבאלד אז דאס איז ניט כדבעי, האט ער דערפאר זיי דוחה געווען. הלל אבער, לשיטתו, האט דן געווען אינעם ענין לויט די פרטים וסיבות הדיבור — און ער האט געזען בזה אז די אלע גרים ווילן זיך מגייר זיין מיט אן אמת<sup data-n=\"57\">57</sup> (און דאס וואס זייער דבור איז בנוסח הנ״ל — איז עס צוליב א זייטיקן טעם — עס פעלט זיי אין ידיעה בגדר דכה״ג וכיו״ב)<sup data-n=\"58\">58</sup>.\nט. אין סדר קדשים — מס׳ חולין<sup data-n=\"59\">59</sup>: „העוף עולה עם הגבינה על השלחן\nואינו נאכל דברי ב״ש וב״ה אומרים לא עולה ולא נאכל״: ב״ש האלטן אז מ׳זעט די זאך (דאס ארויפבריינגען אויפן טיש) כמו שהוא, ווי דאס איז פאר זיך — און ס׳איז דאך ניטא קיין חשש איסור צו ארויפבריינגען אן עוף אויפן טיש צוזאמען מיט גבינה.\nבית הלל אבער האלט — לשיטתם, אז מ׳דארף זיך מתבונן זיין אין פרטים. ובנדו״ד אלס סיבה פון א מסובב וואס וועט דערפון ארויסקומען: דער ארויפבריינגען אויפן טיש איז א סיבה צו א מסובב, ווארום (ווייבאלד אז „יצר לב האדם רע מנעוריו״ 59*), איז) אויב מ׳וועט מתיר זיין ארויפבריינגען ביידע צוזאמען אויפן טיש איז א חשש אז דורך דעם וועט ער סוף סוף אנהויבן זיי עסן צוזאמען<sup data-n=\"60\">60</sup>.\nיו״ד. מהפלוגתות בסדר טהרות — איינע פון זיי (און לפי״ז וועט זיין מובן בנדו״ד):\nאין מס׳ כלים 60*) איז דא א מחלוקת: „מטפחות ספרים בין מצויירות בין שאינן מצויירות טמאות כדברי ב״ש. ב״ה אומרים מצויירות טהורות ושאינם מצויירות טמאות״.\nאיז דער ראגאטשאווער<sup data-n=\"61\">61</sup> מבאר זייער מחלוקת — על יסוד פון דעם וואס דער ראב״ד<sup data-n=\"62\">62</sup> איז מבאר דעם אונטער־",[["55","55","ראה בכ״ז יבמות כד, ב. מז, א. קט, ב. בכורות ל, ב. רמב״ם הל׳ איסו״ב פי״ג הי״ד."],["56","56","ראה חדא״ג כאן. ושם כ׳ לענין הגר שבא ע״מ שיהי׳ כה״ג, דלא גיירוהו הלל תיכף אלא עד לבתר הכי. אבל לכאורה פשוטות ל׳ הגמרא דקאמר „גיירי׳״ כשבאו — בכל הג׳ מאורעות — משמע שהלל גיירם תיכף כשבאו אצלו. וכ״מ מפירש״י ד״ה גיירי׳. וראה תוס׳ שבהערה הבאה."],["57","57","ראה תוס׳ יבמות כד, ב. קט, ב. נסמן בגליון הש״ס שבת שם."],["58","58","ולכאו׳ כן צריך לפרש גם בפרש״י שבת ד״ה גיירי׳, דאל״כ הי׳ מספיק מש״כ „דלא דמיא הא לחורץ מדבר אחד . . הגבורה״."],["59","59","קד, ב (במשנה). 59*) נח ח, כא."],["60","60","לפי פי׳ הרמב״ם פ״ט מהל׳ מאכלות אסורות ה״כ. (עיין לח״מ שם). טושו״ע יו״ד ר״ס פח. וראה פרש״י חולין שם ד״ה אבל הכא. ד״ה גזירה. יד אברהם לשו״ע שם, ועוד. 60*) פכ״ח מ״ד."],["61","61","שו״ת צ״פ נ. י. סי׳ קלו (הובא בצפע״נ עה״ת שמיני ע׳ קו)."],["62","62","בפי׳ לתו״כ הנ״ל. ומביא שם המשנה כלים ספט״ז: זה הכלל העשוי לתיק טמא לחפוי טהור."]]],[1300161332,"שייד צווישן „תיק״ און „חיפוי״, אז א „תיק״ (א שיידל־צודעק) דינט צום באשיצן דאס וואס געפינט זיך אין דעם תיק, און דערפאר ווערט דאס טמא, „משמשי אדם״. ווייל דאס איז בסוג פון אבער א „חיפוי״ (צודעק) נוצט ניט צום שיצן די צוגעדעקטע זאך, נאר דינט בלויז „לנוי״ — דערפאר איז עס ניט טמא:\nאון אין דעם באשטייט די מחלוקת פון ב״ש און ב״ה: מטפחות המצויירות, ווייבאלד זיי זיינען לנוי פון די ספרים, וואס זיינען אין איינגעוויקלט, האבן זיי א דין פון חיפוי, און דערפאר האלטן ב״ה אז זיי זיינען טהור; מטפחות שאינן מצויירות וואס זיינען ניט לנוי ווערן זיי טמא. דאקעגן ב״ש האלטן אז אויך חיפוי כלים איז טמא.\nדער הסבר פון זייער מחלוקת איז פארשטאנדיק עפ״י הנ״ל<sup data-n=\"63\">63</sup>: ב״ש האלטן, אז מ׳קוקט אויף דער זאך לויט איר כללות׳דיקן גדר, (מטפחות), ניט אריינגייענדיק אין צוגעקומענע פרטים — און מיט׳ן כללות׳דיקן עיניו רואות זעט מען אז ביידע מינע „מטפחות״ דינען ווי א כלי־שימוש צו באדעקן און באשיצן די כלים, דעריבער ווערן זיי טמא. לויט ב״ה אבער דארף מען זיך רעכענען מיט די פרטי הדבר — בנדון דידן מיט די פרטים וואס ווייזן דעם צוועק און תכלית השימוש פון יעדער מין באזונדער: מטפחות המצויירות היות אז זייער צוועק איז צוליב׳ן „נוי״ פון די פארדעקטע כלים, האבן זיי א דין פון „חיפוי״ — וואס איז בטל צו דער כלי און וואס האט אויף זיך ניט קיין גדר פון „כלי״<sup data-n=\"64\">64</sup> — און דערפאר ווערן זיי ניט טמא. אבער מטפחות שאינן מצויירות וואס זייער צוועק איז ניט אויף צוצוגעבן נוי אין די כלים, נאר זיי זיינען ווי א „תיק״ וואס נוצט צו באשיצן און פארהיטן די כלי, במילא זיי קענען טמא ווערן.\nאון מען געפינט אז ר״א האלט ווי ב״ש, און די חכמים ווי דעת ב״ה<sup data-n=\"65\">65</sup>.\nיא. לויט דעם אלעם וועט אויך זיין מבואר דער טעם הפלוגתא — לשיטתי׳ — אין דער משנה פון סוף חגיגה הנ״ל:\nדער רמב״ם האלט אז ר״א, וואס איז א תלמיד פון ב״ש, און די רבנן גייען לשיטתם פון ב״ש וב״ה, אין די דערמאנטע פלוגתות:\nר״א האלט אז א ציפוי איז מטמא — ווייבאלד אז דער כלליות׳דיקער ענין פון מזבח איז כשמו (אויך פון יעדער פרט זיינעם — „א פרט פון מזבח הנחושת״) — דאס איז א מזבח הנחושת אדער פון זהב, וואס זיינען מקבל טומאה, און ס׳איז ניט קובע וואס אין פרטיות פון מזבח איז דער נחשת וזהב א ציפוי און א טפל צום מזבח. ובמילא וואלט עס געווען טמא ווען ניט דאס וואס די תורה זאגט אז זיי זיינען פונקט ווי „קרקע״ וואס איז ניט מקבל קיין טומאה.\nדי חכמים האלטן אז מ׳דארף ניט אנקומען צום לימוד פון קרקע: כאטש בכללות ובענינו איז דער מזבח — מזבח",[["63","63","גם לפי פי׳ הרמב״ם והרע״ב שם, יש למצוא קו הנ״ל בשיטות ב״ש וב״ה, דב״ה מחלקים לפרטים: דהמטפחות המצויירות ציורן יעיד עליהם שהן מיוחדים לספרים ואינן משמשי אדם כו׳, וב״ש אין מחלקים (וגם אין מחלקים מהו העיקר השימוש כו׳). ובפרט ע״פ פי׳ משנה אחרונה שם. אבל הבי׳ שבפנים שייך יותר לנדו״ד דסוף חגיגה."],["64","64","ראה פי׳ הר״ש שם „אין תכשיט לכלי״."],["65","65","ראה בהנסמן בצפע״נ שם (ושם נדפס בטעות ר״מ במקום ר״א)."]]],[1300161333,"הנחושת והזהב — א כלי פון מתכת, און דערפאר ווערט ער אזוי אנגערופן, אבער מצד פרטי המזבחות איז דאך די מתכת א ציפוי<sup data-n=\"66\">66</sup>; און א ציפוי, וועלכער ער זאל ניט זיין — פון זהב אדער נחשת כו׳ — איז נאר א טפל און במילא בטל צו דער כלי (און במילא קען די כלי אויך ניט טמא ווערן (צוליב דעם ציפוי)),\nאון די פרטים זיינען מכריע דעם כלל, כנ״ל.\nולכן דארף מען ניט אנקומען צו א לימוד מיוחד פון פסוק אז די מזבחות קענען ניט טמא ווערן, נאר ס׳איז דערויף גענוג דער טעם „מפני שהם מצופים״<sup data-n=\"67\">67</sup>.\nיב. עפ״ז וועט מען אויך פארשטיין דעם קשר צווישן דעם סיום און דער התחלה פון מס׳ חגיגה, וואס דארטן געפינט מען א מחלוקת פון ב״ש וב״ה, און וואס אויך איר נקודת ההסברה איז די זעלבע ווי ביי דער מחלוקת פון ר״א וחכמים בסיום המסכת.\nאין די ערשטע משנה<sup data-n=\"68\">68</sup> לערנען מיר: „ב״ש אומרים הראי׳ שתי כסף והחגיגה מעה כסף וב״ה אומרים הראי׳ מעה כסף, והחגיגה שתי כסף״. ב״ש זאגן אז די עולת ראי׳ וואס מען דארף בריינגען ווען מ׳איז עולה לרגל, דארף זיין ווערט שתי כסף, און די שלמי חגיגה מעגן זיין ווערט ווייניקער — „מעה כסף״. ב״ה זאגן פארקערט, אז די „שלמי חגיגה״ דארפן האבן א גרעסערע שווי ווי „עולת הראי׳״.\nאיז די גמרא<sup data-n=\"69\">69</sup> מבאר אז ב״ש האלטן „שהראי׳ עולה כולה לגבוה משא״כ בחגיגה״ — אז עולת ראי׳ ווייבאלד זי איז אינגאנצן „לגבוה״, דארף זי זיין מער ווערט ווי שלמי חגיגה — אכילת בנ״א. ב״ה אבער זאגן „אדרבה חגיגה עדיפא דאית בה שתי אכילות״<sup data-n=\"70\">70</sup>.",[["66","66","והוא דוגמת מחלוקת ב״ש וב״ה (אהלות פי״א מ״ג): הי׳ אדם נתון שם (תחת הסדק וכלים מצד אחד וטומאה בצד אחר — אם האדם חשוב אהל להביא את הטומאה) ב״ש אינו מביא את הטומאה וב״ה אומרים אדם חלול הוא והצד העליון מביא את הטומאה (ועד״ז שם מ״ד. וראה מפרשי המשנה): דמצד קביעות כללות הדבר, האדם „כמו שהוא״, הרי האדם ברי׳ אחד ומציאות אחת (גוש אחד). אבל מצד הפרטים הרי הוא „עור ובשר תלבישני״, ופנימיותו הוא חלל טפח. ראה משנה אחרונה שם. וראה צפע״נ מהדו״ת נו, סע״ג ואילך, שמבאר מחלוקתם אם גופו של האדם נחשב כגוף אחד, או שהוא מורכב מחלקים *). ועפ״ז הנ״ל י״ל שתלוי בשיטתם הנ״ל."],["67","67","והחידוש בשיטתם כאן: לפי פי׳ הרמב״ם בפיה״מ כלים כב, ומהר״י קורקס שם (הובא בהערה 20) מובן בפשטות החידוש, כי ביחד עם זה שהציפוי פועל ביטול הכלי שלא יטמא, אומרים שהציפוי בטל לגבי הכלי. וגם לפי המובן מדבריו בהל׳ מטמאי משכב ומושב, רע״ב ומל״מ (שבהערה שם), שגם מצ״ע לא היו טמאין כיון שעשויין לנחת, וציפויין בטיל לגביהן שישאר כלי עץ העשוי לנחת — חידוש בשיטתם כאן, שהרי בנדו״ד הציפוי שלהם הוא מצד ציווי התורה שיהי׳ מצופה נחושת וזהב (דבכ״מ הדין — דמצוותי׳ אחשבי״ *). וראה לעיל הערה 14. ומ״מ גם בזה דעתם שקובע העיקר, ואשר גם ציפוי זה בטל וטפל להעיקר."],["68","68","בהמשניות כנדפס בגמרא. ובמשניות הוא מ״ב. ראה לקמן הערה 74."],["69","69","חגיגה ו, א."],["70","70","בטרא שם כ׳ דלב״ה אי״ז שחגיגה עדיפא, אלא שמצד טעם זה שווה הוא לעולת ראי׳, אבל: א) פשטות ל׳ הגמ׳ שם לכאורה לא משמע כן (וראה גם בסוף דבריו בטו״א שמוסברת העדיפות בנדו״ד) וראה בית האוצר מע׳ ב׳ כלל ב׳. ב) ועיקר: לדעת הרמב״ם (שאליבי׳ קיימינן בפנים השיחה) בפיה״מ *) ועיי״ש בצפע״נ שגם בזה ס״ל לר״א כב״ש. *) ראה בכורות י, א. פרש״י ביצה כז, ב — ד״ה חלה. וראה אנציקלופדיא תלמודית מע׳ איסורו חשובו."]]],[1300161334,"ד. ה. ווי מען קוקט אויף דעם ענין הקרבנות בכללות דארף אויסקומען אז א קרבן וואס מען בריינגט אינגאנצן לגבוה, דארף ער זיין ווערט מער ווי א קרבן וואס איז בלויז טיילווייז לגבוה (שיטת ב״ש). אבער מצד פרטי הדבר, איז „אדרבא״ א פארקערטע מסקנא: אכילת<sup data-n=\"71\">71</sup> כהנים (און אויך אכילת בעלים<sup data-n=\"72\">72</sup> פונעם קרבן איז אויך א מצוה, ובמילא איז אויך זייער אכילה אן ענין פון „גבוה״<sup data-n=\"73\">73</sup>, קומט אויס אז „אדרבא חגיגה עדיפא״ (שיטת ב״ה) האבענדיק „שתי אכילות״ לגבוה און דערפאר דארף זי זיין מער ווי „עולת ראי׳״<sup data-n=\"74\">74</sup>.\nיג. לויט דעם ביאור הנ״ל אין דער סברא פון די רבנן (ע״פ דעת הרמב״ם) איז אויך פארשטאנדיק — בסיום המסכת — דער שייכות וקשר צווישן די צוויי מימרות אין דער גמרא, אז „אין",[["","","(וכ״ה ברע״ב) זהו טעם ב״ה שסוברים דשלמים יהיו הדמים שלהם יותר, ולא קאמר טעם אחר. ומה שלא פי׳ הטעם שאיתא בגמ׳ לב״ה (שחגיגה עדיפא שישנה לפני הדיבור כו׳ דכתיב ויזבחו זבחים שלמים (משפטים כד, ה)) — אולי י״ל, כי ס״ל שדבר זה אם פרשה זו נאמרה לפני מ״ת (ראה פרש״י חגיגה שם) הוא במחלוקת שנוי׳ (כמ״ש הרמב״ן שם (פסוק א׳)). וי״ל שסוגיא זו אתיא כמ״ד שקודם מ״ת נאמרה, אבל ההלכה היא שלאחר מ״ת נאמרה, כסדר הפרשיות (כהרמב״ן שם. וראה אברבנאל: נחלקו המפרשים .. חכמי צרפת . . אבל חכמי ספרד קיימו וקבלו שהי׳ זה אחר מ״ת כסדר הפרשיות), ולכן מפרש טעם ב״ה אליבי׳ דכ״ע [ולהעיר שבתוס׳ רי״ד לחגיגה שם מפרש זה „שישנה לפני הדיבור״ דהיינו לפני „וידבר ה׳ אליו מאהל מועד״ (דר״פ ויקרא)]. אבל עדיין צע״ק מדוע לא הביא טעם השני שבגמ׳ (הן לב״ש והן לב״ה) „ועוד מצינו שריבה בהן הכתוב כו׳״. ואולי כי ס״ל (כדמשמע מפשטות הלשון) שזהו רק טעם נוסף. וראה מה שמסיים שם בפיה״מ „ואלו הראיות והתשובות וטענות יקצר המקום הזה מלהגידם״. ועוד ועיקר — מכללי הרמב״ם שמביא (באם אין נפק״מ לדינא) קרא ודרשה היותר פשוטה (יד מלאכי כללי הרמב״ם אות ד). ואכ״מ."],["71","71","בפירש״י שם (ו, א) „שתי אכילות — מזבח ואדם״. ובפיה״מ להרמב״ם (ועד״ז ברע״ב): לפי שיש בהם חלק לשם וחלק לבעלים וחלק לכהנים. אבל צע״ק אם אפשר לפרש הביאור שבפנים לפי דעת הרמב״ם (בפיה״מ), שהרי אין מפורש בדעתו אם גם אכילת בעלים מצוה — ראה הנסמן בהערה הבאה."],["72","72","ראה הנסמן לעיל ע׳ 104 בהערה 24."],["73","73","להעיר דכהנים (ובעלים) משלחן גבוה קא זכו — ביצה כא, א. פרש״י שם ד״ה כהנים (וראה תוס׳ שם ד״ה אבל. ועוד). ובפרש״י סוכה (ט, א ד״ה על): שלמי חגיגה . . דזכו בהו בתר הכי משלחן גבוה כעבד הנוטל פרס."],["74","74","וי״ל השייכות דסיום המס׳ גם למחלוקת הא׳ ב״ש וב״ה במשנה: איזהו קטן כל שאינו יכול לרכוב על כתפיו של אביו ולעלות מירושלים להר הבית דברי ב״ש וב״ה אומרים כל שאינו יכול לאחוז בידו של אביו ולעלות מירושלים להר הבית כו׳. ובפרש״י: אבל מכאן ואילך אע״פ שאינו חייב מן התורה הטילו חכמים על אביו ועל אמו לחנכו במצות. וראה שם תוד״ה איזהו. ובגמ׳ שם ו, א: דכללות הענין הוא, שאביו חייב לחנכו במצות — להביאו לעזרה, א״כ אם אא״פ לו לאביו להביאו (כקטן, לא כטף) פשוט שאין חיוב (וזהו השיעור שאינו יכול לרכוב על כתפיו), אבל כשאביו יכול להביאו — באיזה אופן שיהי׳ — להקטן מחוייב בזה. אמנם כשמתבונן בפרטי הדבר, הרי תוכן ענין החינוך הוא לא חינוך סתם, אלא — באופן שקיום המצוה דהקטן בקטנותו — יחנכו וירגילו לעשות מצוה זו בגדלותו, ולכן כל שאינו יכול לאחוז בידו של אביו ולעלות כו׳ — דכה״ג בגדלותו פטור — גם מטעם חינוך קטן פטור (כבפרש״י במשנה ד״ה שלש רגלים). אבל אם יכול לאחוז ולהלוך ברגלים שלו מחויב, שהרי אז עושה הקטן המצוה כמו בגדלותו. וראה בגמ׳ שם ו, א ובפרש״י וטו״א בהסוגיא שם. ואכמ״ל. *) וידוע השקו״ט אם הקטן נמי מחוייב בדבר או שרק האב חייב לחנכו, בפרש״י ותוס׳ ברכות מח, א. ועוד. ואכ״מ."]]],[1300161335,"אור של גהינום שולטת״ אין „תלמידי חכמים״ ו„פושעי ישראל״, און זייער המשך ושייכות צום ענין פון ציפוי המזבח:\nנאך דער משנה און גמרא וועגן די מזבחות אין מקדש — וואס דורך הקרבת הקרבנות אויף זיי ווערט אויפגעטאן דער „ושכנתי בתוכם״ אין מקדש — און לאחרי ווי די גמרא איז מסביר די דיעה פון די רבנן (לדעת הרמב״ם) אז מ׳קוקט זיך איין אין פרטי הדבר זעט מען א ציפוי, וואס איז בטל צום עיקר הכלי, איז בהמשך לזה בריינגט די גמרא די מימרות בנוגע דעם „ושכנתי בתוכם״ בתוך כאו״א מישראל (כנ״ל ס״א), וואס יעדער איד טוט אויף דורך עבודה אין זיין מקדש הפרטי, און דערין איז אויך דא סברא הנ״ל:\nאז מ׳איז זיך מתבונן — כפס״ד בית הלל — אין פרטי הענינים, ווערט קלאר, אז אפילו די ענינים בלתי רצויים — אפילו דאס וואס מען זעט ביי פושעי־ישראל — זיינען זיי ניט דער עיקר פון זיין מהות; דאס איז ניט מער ווי א ציפוי, א צוגעגעבענער<sup data-n=\"75\">75</sup> צודעק<sup data-n=\"76\">76</sup>, וואס איז טפל ובטל צו זיין עצם מהות, דער עצם ופנימיות פון א אידן איז אזוי ווי א מזבח<sup data-n=\"77\">77</sup> — טוב וקדושה, און דערפאר איז ניט שייך אז דער „אור של גהינום״ זאל שולט זיין אין זיי<sup data-n=\"78\">78</sup>.\nיד. ענין הנ״ל איז אויך מתאים מיט דער כלליות׳דיקער שיטה פון ב״ה ווי מ׳דארף קוקן אויף א אידן — וכמודגש אין דער אויבענדערמאנטער מחלוקת פון ב״ש וב״ה, אז ב״ש זאגט „כלה כמות שהיא״ און ב״ה זאגט „כלה נאה וחסודה״ (און ס׳איז אויך מרומז אין די נעמען „שמאי״ און „הלל״):\nס׳איז ידוע<sup data-n=\"79\">79</sup> אז הקב״ה און כנס״י ווערן אנגערופן „חתן וכלה״. האלט ב״ש<sup data-n=\"80\">80</sup> וואס שמאי איז מל׳ „השם אורחותיו״ — „שם״ לויטן אפטייטש פון שאצן און מעסטן די דרכים<sup data-n=\"81\">81</sup> — אז מ׳דארף מדקדק זיין און אפשאצן גענוי<sup data-n=\"82\">82</sup> דעם אופן ההנהגה פון אידן ווי זיי פירן זיך בפועל („כלה כמות שהיא״), און בהתאם דערמיט איז די הנהגה מיט זיי:\nאבער ב״ה — וואס איז מל׳<sup data-n=\"83\">83</sup> „בהלו נרו״, זיי באלייכטען און דאס איז קובע אויך בנוגע לפועל בעוה״ז די פנימיות פון יעדער זאך — זאגן ב״ה אז בפנימיות איז יעדער איד טוב, „כלה נאה וחסודה״. און די הוכחה והסברה אין דעם: משל לאדם „שלקח מקח .. מן השוק ישבחנו בעיניו כו׳״ — ווייבאלד דער אויבערשטער האט גענומען דעם „מקח״, ער האט בוחר געווען אין אידן, איז דאך ברור אז בעצם איז דער מקח טוב וקדושה, איי אין חיצוניות זעט זיך",[["75","75","ראה רמב״ם הל׳ גירושין ספ״ב."],["76","76","ראה מאמר ש״פ בראשית תרנ״ט „כמ״ש בס׳ ההפרש בין ישראל לעכו״ם . . משא״כ ישראל הם בעצם טוב ומה שיש בהם איזה רע הוא דבר נוסף לבד על העצם כו׳״."],["77","77","ראה לקו״ש ח״ג ע׳ 911 ואילך. ושם גם החילוק דמזבח הנחושת והזהב בישראל."],["78","78","עפ״ז יש לבאר כמה דיוקים בהמימרות דר״א ור״ל — נתבארו בארוכה לקמן ע׳ 435 ואילך."],["79","79","במדרז״ל בכ״מ. וכל שה״ש מיוסד ע״ז."],["80","80","בהבא לקמן במחלוקת ב״ה וב״ש — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381321\" data-slug=\"likkutei-torah\" data-id=\"4001381321\">לקו״ת</a> ד״ה ת״ר כיצד מרקדין (שה״ש מח, ב ואילך). אלא ששם מבואר הוא לענין כלות הנפש דישראל, עיי״ש."],["81","81","מו״ק ה, סע״א. סוטה ה, ב."],["82","82","דב״ש שרשם מבחי׳ הגבורות — ראה לקו״ת שם."],["83","83","איוב כט, ג."]]],[1300161336,"עס ניט אן — ענדערט עס אבער ניט זיין אמת׳ע מציאות און בפנימיות ובעצם איז ער טוב — ווייבאלד ס׳איז זיכער אז דער „חתן״ (זה הקב״ה) האט אויסגעקליבן און גענומען דעם מקח איז דאס געוויס א „כלה נאה וחסודה״!\nנאר דערביי פארדערט זיך דער תנאי (כהמשך הגמרא בכתובות) „מעורבת עם הבריות״: בשעת מ׳איז מעורב עם הבריות, מ׳האט א נאענטע הכרה און וויסן פון דעם מעמד ומצב אין עוה״ז מיט אלע זיינע נסיונות וכו׳, איז דעמאלט א דבר ברור אז מ׳וועט צוקומען און דערגרייכן צום אמת, אז ס׳איז „כלה נאה וחסודה״.\nטו. און דאס איז די הוראה פאר יעדערן: בשעת מ׳זעט אויף א צווייטן אידן אן ענין בלתי רצוי ר״ל, קען מען טראכטן ביי זיך אז יענער איז אין א מצב און ציור פון „חיגרת או סומא״ ר״ל, איז ווי קען ער האבן מיט אים א מגע ומשא? — זאגן דערויף ב״ה: פארוואס קוקסטו אויף אים בלויז מיט עיני בשר? אל תבט אל מראהו! ווייבאלד דער אויבערשטער האט אים אויסגעקליבן און גענומען אלס א „מקח״ איז זיכער אז ער איז א „כלה נאה וחסודה״. און ווייבאלד מ׳האט עס דיר באוויזן דארפסטו פארשטיין, אז דאס איז צוליב „בהלו נרו״ — העלפן אנטפלעקן אין אים זיין פנימיות.\nאון דורך דער עבודה אין זמן הגלות כשיטת ב״ה דוקא — ווארום ס׳איז דאך הלכה כב״ה<sup data-n=\"84\">84</sup>, און ס׳איז גאר ניט קיין הו״א צו פירן זיך כשיטת ב״ש<sup data-n=\"85\">85</sup> — אז מ׳קוקט ניט אויף א אידן ווי ער זעט אויס בעיני בשר, נאר מ׳דערזעט די פנימיות פון א אידן, אז ס׳איז א כלה נאה וחסודה, ובמילא טוט מען מיט יעדן אידן אויף ארויסברײנגען זיין פנימיות בגלוי —\nאיז מען זוכה צו די נישואין<sup data-n=\"86\">86</sup> פון אידן מיט׳ן אויבערשטן, און דעמאלט קען שוין זיין און עס וועט זיין הלכה כב״ש<sup data-n=\"87\">87</sup>, ווארום „ואת רוח הטומאה אעביר מן הארץ״<sup data-n=\"88\">88</sup>, וועט מען זען אויך בגילוי ובעיני בשר אז יעדער איד („כלה כמות שהיא״) איז א „כלה נאה וחסודה״.\n(משיחת כ״ף מנחם אב, תשל״א)",[["84","84","עירובין יג, ב."],["85","85","דב״ש במקום ב״ה אינה משנה — ברכות לו, רע״ב. וש״נ."],["86","86","שמו״ר ספט״ו."],["87","87","ראה מד״ש לאבות פ״ה מי״ט. מק״מ לזוה״א יז, ב. לקו״ת קרח ד״ה ויקח קרח ספ״ד. תוספות חדשים לאבות בתחלתו."],["88","88","זכרי׳ יג, ב."]]],[1300161337,"<h3>תרומה ה</h3>\nא. אינעם אופן עשיית „הנרות\" פון דער מנורה, איז דאָ אַ מחלוקת אין גמרא<sup data-n=\"1\">1</sup>: לויט איין דיעה זיינען די נרות געווען אַ טייל פון דער מנורה, ווייל דאָס וואָס די מנורה דארף זיין „מקשה\"<sup data-n=\"2\">2</sup> (און ניט „פרקים (ממש)\"<sup data-n=\"3\">3</sup> איז כולל אויך די נרות; אַ צווייטע דיעה איז, אַז די „נרות\" זיינען געווען אַ באַזונדער זאַך פון דער מנורה, נאָר פאַר דער הדלקה האָט מען זיי אַרויפּ־געשטעלט אויף די קני המנורה [און דער סדר פון הטבת (ניקוי) הנרות איז געווען, אַז „מסלקן (פון דער מנורה) ומניחן באוהל ומקנחן כו'\"<sup data-n=\"4\">4</sup>].\nאון די גמרא פאַרבינדט עס מיט דער פלוגתא, צי דאָס וואָס עס שטייט ביי דער מנורה<sup data-n=\"5\">5</sup> „ככר זהב טהור יעשה אותה את כל הכלים האלה\" מיינט אויך די „נרות\", אַז אויך זיי „באות מן הככר\" (און לפי\"ז זיינען זיי געווען „מקשה\"); אָדער נאָר די מנורה אליין איז „באה מן הככר\", אָבער ניט די נרות (און לפי\"ז זיינען די נרות ניט געווען „מקשה\").\nדער רמב\"ם<sup data-n=\"6\">6</sup> פסק'נט להלכה: „מנורה הבאה זהב תהי' כולה ככר עם נרותי' ותהי' כולה מקשה .. שהנרות קבועין במנורה והם מכלל הככר\".\nב. שוין גערעדט פיל מאָל, אַז רש\"י בפירושו על התורה איז מפרש ע\"ד הפשט, אפילו ווען עס איז ניט מתאים מיט חלק ההלכה שבתורה — און דאָס זעט מען באופן בולט אין שיטת פירושו בנדו\"ד.\nווי געזאָגט, פאַרבינדט די גמרא די פלוגתא צי „נרות\" דארפן זיין „מקשה\" (מיט דער מנורה) מיט דער פלוגתא צי זיי זיינען „באות מן הככר\". און ווי דער רמב\"ן<sup data-n=\"7\">7</sup> זאָגט: „על דעת כולם לא יבוא במשקל הככר אלא גוף המנורה במה שהוא עמה מקשה\" — און דערפאַר איז ער מסביר, אַז לויט דער דיעה (אין ברייתא דמלאכת המשכן<sup data-n=\"8\">8</sup> אַז די מלקחים און מחתות „באות מן הככר\", זיינען זיי ניט קיין „כלים נפרדים\" פון דער מנורה, נאָר אַ טייל פון דער מנורה [מלקחים — „הם שעושין על פי הנרות טס של זהב כו'\", און מחתות — „הם ספלים שתחת כל נר ונר כו'\"].\nרש\"י אָבער זאָגט — בפירושו אויפן „ככר זהב טהור\"<sup data-n=\"5\">5</sup>: „שלא יהי' משקלה עם כל כלי' אלא ככר כו'\", און פאַר דעם<sup data-n=\"9\">9</sup> טייטשט ער: „ומלקחי', הם הצבתים כו'\", „ומחתותי', הם כמין בזיכין קטנים שחותה בהן כו'\" — קומט אויס (לדעתו) אַז אויך די כלים הנפר־דים פון דער מנורה זיינען פון דעם ככר<sup data-n=\"10\">10</sup> —",[["1","1","מנחות פח, ב. ברייתא דמלאכת המשכן פ\"ט. וראה רמב\"ן פרשתנו כה, לט. ועוד."],["2","2","פרשתנו כה, לא. לו."],["3","3","ראה פרש\"י ורש\"י כת\"י מנחות שם ד\"ה של פרקים. פרש\"י ד\"ה מסלקן."],["4","4","מנחות שם."],["5","5","פרשתנו שם, לט."],["6","6","הל' ביהב\"ח פ\"ג ה\"ד. שם ה\"ז."],["7","7","פרשתנו שם."],["8","8","נסמן לעיל הערה 1."],["9","9","שם, לח."],["10","10","בראַ\"ם, גו\"א ועוד — שכוונת רש\"י ב„כל כלי'\" היא רק ל„נרות'\", עיי\"ש. אבל כמדובר כמה פעמים, רש\"י כתב פירושו בסגנון ברור גם לבן חמש"]]],[1300161338,"וטעמו י\"ל: דער פירוש הפשוט<sup data-n=\"11\">11</sup> פון: א) מלקחיים און מחתה — בכ\"מ אין תנ\"ך — איז אַ כלי נפרד פון דער זאַך בא וועלכע מען נוצט עס — לדוגמא בא דעם מזבח<sup data-n=\"12\">12</sup>. ב) „ככר זהב טהור יעשה אותה את כל הכלים האלה\"<sup data-n=\"5\">5</sup> איז, אַז „אותה\" — די מנורה — און „כל הכלים האלה\"<sup data-n=\"13\">13</sup> — אלע כלים וואָס ווערן דערמאָנט אין פסוק<sup data-n=\"14\">14</sup> — דארפן געמאַכט ווערן פון דעם „ככר זהב טהור\"<sup data-n=\"15\">15</sup>.\nעל פי זה, וויבאלד אַז לויט פרש\"י איז דער תנאי פון „מקשה\" ניט פארבונדן מיטן שיעור פון „ככר זהב טהור\", קומט אויס, אַז פון דעם וואָס די „נרות\" האָבן געדארפט זיין פון דעם „ככר\" איז (לשיטתו) ניטא קיין הוכחה אַז זיי האָבן געמוזט זיין „מקשה\" (מיט דער מנורה).\nג. בהשקפה ראשונה זעט אויס, אַז רש\"י האַלט אַז דער ציווי „מקשה\" ביי מנורה איז כולל אויך די „נרות\": אויף „מקשה תיעשה המנורה\"<sup data-n=\"16\">16</sup> איז רש\"י מפרש „שלא יעשנה חוליות ולא יעשה קני' ונרותי' איברים איברים ואח\"כ ידביקם<sup data-n=\"17\">17</sup> .. אלא כולה באה מחתיכה אחת כו' ומפריד הקנים אילך ואילך\". און וויבאלד אַז מ'טאָר ניט מאַכן די נרות „איברים איברים ואח\"כ ידביקם\", מיינט עס לכאורה, אַז די נרות מוזן מלכתחילה געמאַכט ווערן „מקשה\" מיט דער מנורה.\nאָבער כד דייקת שפיר, איז דאָס ניט מוכרח: רש\"י זאָגט נאָר, אַז „מקשה תיעשה המנורה\" איז שולל אַז די מנורה זאָל ניט זיין אין אַן אופן פון „איברים איברים ואח\"כ ידביקם\" (ד.ה. די מנורה דארף ניט זיין צונויפגעקלעפט פון באַזונדערע טיילן) — און אין דעם זאָגט רש\"י, אַז פונקט ווי די קני המנורה האָבן ניט געטארט זיין „איברים איברים ואח\"כ ידביקם\", אזוי טאָר מען אויך ניט מדבק זיין די נרות צו דער מנורה [ווייל דאָן וואָלט די מנורה ניט געווען „מחתיכה אחת\"];\nאָבער וועגן דעם, צי די נרות קענען זיין און בלייבן באַזונדערע חלקים פון דער מנורה — נאָר מ'שטעלט זיי אַרויף אויף די ראשי הקנים — רעדט ניט רש\"י: אין דעם אופן איז דאָך די מנורה „מקשה\", זי איז „מחתיכה אחת\"<sup data-n=\"18\">18</sup>, ס'איז גאָרניט דבוק צו דער מנורה.\nעפ\"ז איז אויך פאַרענטפערט פאַר־וואס באַם סיום פירושו דערמאָנט רש\"י נאָר די קנים און ניט די נרות.\nד. וויבאלד מען געפינט ניט קלאָר<sup data-n=\"19\">19</sup> אין פרש\"י ווי זיין שיטה איז אין דעם,",[["","","למקרא, מבלי ליתן מקום לטעות מהי כוונתו. ומכיון שכתב „עם כל כלי'\", הרי פשוטו, כולל הכל — גם מלקחי' ומחתותי'. וכפי' הרמב\"ן בכוונת רש\"י [ושם, דמ\"ש רש\"י „כן הוא פשוטו של מקרא\". וראה גם ראב\"ע לקמן פסוק מ']. וראה נימוקי שמואל לרמב\"ן שם."],["11","11","משא\"כ בלימוד ע\"ד הדרש וההלכה י\"ל שרק הפרט ד„זהב טהור\" קאי על „את כל הכלים האלה\" — ראה מנחות וברייתא דמלאכת המשכן שם. רמב\"ן שם."],["12","12","ישעי' ו, ו. פרשתנו כז, ג ובפרש\"י."],["13","13","ומש\"נ „את כל הכלים האלה\" הוא כמו „ואת\", וכמפורש בויקהל לז, כד."],["14","14","וי\"ל בנוגע ל„כל כלי שמנה\" (במדבר ד, ט)."],["15","15","וכן מוכח מזה שהציווי ד„ככר\" נאמר רק בסוף הפרשה לאחרי הציווי על עשיית הכלים."],["16","16","פרשתנו כה, לא."],["17","17","ראה ברייתא דמלאכת המשכן שם. ספרי בהעלותך ח, ד."],["18","18","„וכולה באה מחתיכה אחת\" — היינו המנורה עם קני'."],["19","19","דוחק גדול לומר שסומך שיבינו זה מהשמטתו „נרות\" בסיום הד\"ה."]]],[1300161339,"און ער זאָגט אויך ניט אויף דעם „איני יודע\" (ווי ער זאָגט אין אנדערע ערטער<sup data-n=\"20\">20</sup>, וואו דער פירוש אין פסוק איז ניט קלאָר), דארף מען זאָגן, אַז אין לימוד הפשט איז עס אזוי פשוט, אַז רש\"י דארף עס ניט אויסטייטשן אין זיין פירוש — מען זעט עס אָפן און קלאָר אין די פסוקים אַליין.\nאיז דער ביאור אין דעם:\nדער סדר אין דער פרשה פון מלאכת המנורה איז: פריער<sup data-n=\"21\">21</sup> קומט דער ציווי „ועשית מנורת זהב גו' מקשה גו' ירכה וקנה גביעי' כפתורי' ופרחי' ממנה יהיו\" (דערנאָך איז דער פסוק מפרט ווי מ'מאַכט די קני המנורה גביעי' וכו', און איז מסיים: כפתוריהם וקנותם ממנה יהיו כולה מקשה אחת זהב טהור). און ערשט דערנאָך שטייט: „ועשית את נרותי' שבעה גו' ומלקחי' ומחתתי' גו' ככר זהב טהור גו'\" [און אזוי אויך אין פ' ויקהל<sup data-n=\"22\">22</sup>, וואו עס װערט דערציילט ווי מ'האָט געמאַכט די מנורה בפועל, שטייען די אלע פרטים מיט'ן זעלבן סדר].\n— פון דעם וואָס דער ציווי „ועשית את נרותי' גו'\" שטייט נאָך די פרטים ופרטי פרטים פון דער עשי' פון גוף המנורה און נאָכן ציווי „כולה מקשה אחת גו'\", איז מובן, אַז לויט פשוטו של מקרא (דרך פירוש רש\"י על התורה), זיינען „נרותי'\" באַזונדערע זאַכן וואָס געהערן ניט צום גוף המנורה<sup data-n=\"23\">23</sup> — זיי זיינען אין דעם סוג פון „מלקחי' ומחתותי'\" וועגן וועלכע מ'זאָגט אַן גלייך נאָך נרותי'.\nה. נאָך אַ הוכחה אויף דעם: אין פ' פקודי, וואו עס װערט דערציילט<sup data-n=\"24\">24</sup> ווי מען האָט געבראַכט דעם משכן צו משה'ן, שטייט<sup data-n=\"25\">25</sup>: „את המנורה הטהורה את נרותי' גו'\" — איז בשלמא אויב מ'וועט לערנען אַז די נרות זיינען געווען נפרדים פון דער מנורה, איז מובן וואָס דער פסוק טיילט זיי אויס באַזונדער אין דעם סדר ההבאה<sup data-n=\"26\">26</sup>;\nאויב אָבער די נרות זיינען געווען „מקשה\" מיט דער מנורה, האָט דאָך קיין אַרט ניט צו זאָגן, אַז מ'האָט געבראַכט<sup data-n=\"27\">27</sup> די מנורה און (אויך) נרותי' — בריינגענדיק די מנורה װערן במילא געבראַכט אויך די נרות [פונקט ווי עס פאַסט ניט צו זאָגן אַז מ'האָט געבראַכט די מנורה און די קנים, גביעים וכו'].\nו. עפ\"י הנ\"ל — אַז לויט שיטת רש\"י בפירושו עה\"ת זיינען די נרות ניט נכלל אינעם ציווי פון „מקשה\" — װעט װערן פאַרענטפערט כמה שינוים (לגבי דאָ) און תמיהות אין פירוש רש\"י אין פ' ויקהל (וואו די תורה רעדט נאָכאמאָל וועגן מלאכת המשכן):",[["20","20","תולדות כה, ה. ועוד (נסמנו ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051001\" data-slug=\"likkutei-sichot\" data-id=\"1300051001\">לקו\"ש ח\"ה ע' 1</a> שוה\"ג הא' להערה 2)."],["21","21","פרשתנו שם, לא ואילך."],["22","22","לז, יז ואילך."],["23","23","כ\"כ גם באוה\"ח לעיל פסוק לו [ושם: דלכו\"ע (במנחות שם) אין הנרות מקשה, עיי\"ש. ואכ\"מ] ור\"ש בהעלותך, ובחזקוני פסוק לז: כתב עשית לנרות ללמדך שהם היו כלים לבדם ונעים ונדים היו מן הקנים. ולהעיר: כמבואר בפנים [דלפרש\"י הנרות לא היו מגופה של מנורה] מפורש הוא בפרש\"י דה\"ב (ד, כ. הובא באוה\"ח בהעלותך שם) — אבל י\"א (שם הגדולים להחיד\"א ע' רש\"י) שפירוש דה\"י אינו מרש\"י."],["24","24","לט, לג ואילך."],["25","25","שם, לז."],["26","26","והטעם למה מפרט „נרותי'\" — מובן מהמבואר לקמן בפנים — בסופו."],["27","27","מה שנפרטו בפ\"ע בויקהל (לה, יד) בנוגע לעשייתם — י\"ל שהוא מפני חשיבותם כדלקמן בפנים שם. ועד\"ז יש לדחוק בנוגע ל„וכסוי\" (במדבר ד, ט)."]]],[1300161340,"אין פסוק<sup data-n=\"28\">28</sup> „ואת מנורת המאור ואת כלי' ואת נרותי'\" שטעלט זיך רש\"י אויף „נרותי'\" און איז מפרש: „לוציני\"ש<sup data-n=\"29\">29</sup> בלעז בזיכים שהשמן והפתילות נתונין בהן\".\nאיז ניט פאַרשטאַנדיק:\n(א) אויף די ווערטער „את נרותי'\" אין אונזער פרשה<sup data-n=\"30\">30</sup> (וואו די נרות המנורה ווערן דערמאָנט צום ערשטן מאָל) טייטשט רש\"י: כמין בזיכין שנותנין בתוכן השמן והפתילות — היינט וויבאלד רש\"י האָט שוין אין אונזער פרשה אָפגעטייטשט דעם פירוש פון נרות, פאַרוואָס דארף עס רש\"י נאָכאמאָל איבערחזר'ן אין פ' ויקהל<sup data-n=\"31\">31</sup>?\n(ב) די תמי' איז נאָך גרעסער: רש\"י אליין זאָגט (אין פ' ויקהל<sup data-n=\"32\">32</sup>) מיט טעלעכע פסוקים פריער: „כבר פירשתי נדבת המשכן ומלאכתו במקום צוואתם\"\n— און מהאי טעמא איז דאָרט רש\"י ניט מפרש די (רובא דרובא פון די) ענינים דנדבת ומלאכת המשכן (סיידן אין פאַל ווען דאָרט קומט צו אַ חידוש וואָס מ'קען ניט וויסן פון „מקום צוואתם\"<sup data-n=\"33\">33</sup>), ווייל ער פאַרלאָזט זיך אויף דעם וואָס ער האָט שוין פריער מפרש געווען —",[["28","28","שם."],["29","29","כ\"ה בדפוסי רש\"י לפנינו. ובדפוסים הראשונים וכת\"י רש\"י — בכמה שינויים. ובכמה מהם — „לוצי\"ש\", כבפרש\"י תצוה (ל, ז), במדבר (שם). ועד\"ז הוא בפרש\"י שבת כב, ב ד\"ה נר. ובפרש\"י ביצה (כב, א ד\"ה שרגא): נר של חרס קרויזיל בלעז. וראה פרש\"י מנחות שם ד\"ה נר של מקדש. ואכ\"מ."],["30","30","כה, לז. וראה פרש\"י לעיל פסוק לא (וצ\"ע למה כופל רש\"י כאן הפירוש דנרות'. וכן — טעם השינויים. ואכ\"מ)."],["31","31","ומה שבפ' תצוה (שם) מפרש רש\"י „הנרות, לוצי\"ש בלעז כו'\" — י\"ל שאין כוונת רש\"י לפרש תיבת „הנרות\", כ\"א לתרץ: מזה שנאמר שם „בהטיבו את הנרות\" ותיכף בפסוק שלאח\"ז „ובהעלות אהרן את הנרות\", משמע, שקאי על אותם הנרות, וקשה: „בהטיבו את הנרות\" קאי על הכלי, ו„ובהעלות אהרן את הנרות\" קאי על האור — ע\"ד (בהעלותך ח, ב ובפרש\"י) בהעלותך את הנרות „ע\"ש שהלהב עולה\" — (הפתילות) כו'*)? ומבאר רש\"י, דזה שהכלי נק' נרות הוא כמו „לוצי\"ש בלעז\" — שתיבה זו פירושה (ושרשה) ענין האור — והיינו שהכלי נק' ע\"ש האור (השמן והפתילות) שבה, כדלקמן בפנים ס\"ט. וראה ד\"ה ת\"ר נ\"ח תרמ\"ג פ\"א: ושניהם הם כוונה אחת לענין זה שעיקר קיום האור הוא ע\"י הנר כו', עיי\"ש. בפ' במדבר שם מפרש רש\"י עוה\"פ „נרותי', לוצי\"ש בלע\"ז שנותנין בהן השמן והפתילות\". ומפרש שם ג\"כ עוה\"פ „מלקחי'\" ו„מחתותי'\" — ובאופן אחר מפירושו בפרשתנו (כה, לח). ואכ\"מ. *) מש\"נ בפרשתנו (כה, לז) „ועשית את נרותי' גו' (ותיכף לאח\"ז) והעלה את נרותי'\" — אינה קושיא כ\"כ, כי אפשר לפרש (בדוחק עכ\"פ) „והעלה את נרותי'\" (לא — הדלקת הנרות, כ\"א) — שימת הנרות על ראשי הקנים שיהי' „והאיר על עבר פני'\", כפי' הרשב\"ם וחזקוני שם. ועיין פרש\"י (וראב\"ע) שם."],["32","32","לה, ה."],["33","33","או לתרץ הפסוק, וכמו בפרש\"י לה, יד: ואת שמן המאור, אף הוא צריך חכמי לב כו'. ומה שמפרש רש\"י (שם, יג) „לחם הפנים, כבר פרשתי ע\"ש שהיו לו פנים לכאן ולכאן כו'\" — דלכאורה: א) הפירוש מיותר *). ב) ובפרט שרש\"י עצמו מתחיל ומדגיש „כבר פרשתי\" — י\"ל שכוונת רש\"י לשלול הטעות דמש\"נ „לחם הפנים\" (בתוספת ה\"א **)) — דלא כמש\"נ „במקום צוואתם\" (פרשתנו כה, ל) „לחם פנים\" (בלי ה\"א) — פירושו לחם שמניחים „לפני'\" („בפנים\"), ע\"ד פי' תיב\"ע, ראב\"ע וחזקוני תרומה שם. ולכן מפרש רש\"י ד„הפנים\" פירושו „ע\"ש שהיו לו פנים כו'\", ומש\"נ „הפנים\" הוא כי „כבר פרשתי כו'\" (היינו שכבר מפורש לעיל — ובמילא ידוע ע\"ד זה), ולכן נאמר „הפנים\" בה\"א הידיעה. *) במשכיל לדוד (ועד\"ז בשפ\"ח), דקשה לרש\"י למה צריך ע\"ז חכמי לב — אבל מזה שרק על הפסוק שלאח\"ז כותב רש\"י „(ואת שמן המאור) אף הוא צריך חכמי לב כו'\" משמע, דבהכתובים עד שם לא זו היא קושיית רש\"י. **) להעיר מפרש\"י ויצא לא, יג."]]],[1300161341,"היינט וויבאלד אַז רש\"י האָט שוין דעם פירוש פון „נרות\" געזאָגט „במקום צוואתם\" — פאַרוואָס חזר'ט ער איבער דעם פירוש דוקא נאָכאמאָל?\n(ג) פאַרוואָס איז רש\"י מוסיף ומקדים „לוציני\"ש בלע\"ז\" — דלכאורה, ממנ\"פ: אויב דער פירוש „בזיכין וכו'\" איז ניט מספיק און עס פאַדערט מ'זאָל וויסן דעם „לעז\", האָט דאָך רש\"י געדארפט עס בריינגען דאָרט וואו ער זאָגט דעם פירוש פון „נרות\" צום ערשטן מאָל (אין אונזער פרשה)<sup data-n=\"34\">34</sup>; און אויב מ'דארף דערצו ניט אָנקומען, ווייל ס'איז גענוג דער אָפטייטש „כמין בזיכין כו'\", פאַר־וואָס דארף ער דעם „בלעז\" מוסיף זיין אין פ' ויקהל?\nז. וועט מען דאָס פאַרשטיין בהקדים נאָך אַ דיוק אין דעם פרש\"י — ובהקדם: מ'האָט שוין פיל מאָל גערעדט וועגן דעם וואָס יעדער וואָרט (און אות) אין פרש\"י על התורה איז בתכלית הדיוק; און אַז דאָס איז ניט נאָר בנוגע די ווער־טער פון גוף הפירוש; אויך די ווער־טער וואָס ער איז מעתיק פון פסוק אינעם דיבור המתחיל זיינען בדיוק.\nאיינער פון די ערטער, וואו מען זעט עס אין אַ בולט'דיקן אופן (ווי מדויק ס'איז דער דיבור המתחיל פון רש\"י), איז אין דעם אויבנדערמאָנטן פירוש רש\"י:\nאין פסוק הנ\"ל — „ואת מנורת המאור ואת כלי' ואת נרותי' ואת שמן המאור\" — שרייבט רש\"י דריי באַזונדערע ד\"ה: (א) „ואת כלי', מלקחים ומחתות\". (ב) „נרותי', לוציני\"ש וכו' (כנ\"ל)\". (ג) „ואת שמן המאור, אף הוא צריך חכמי לב כו'\".\nזעט מען אַ שינוי בולט: אין דעם ערשטן און לעצטן דיבור המתחיל איז רש\"י מעתיק פון פסוק אויך דעם וואָרט „ואת\", דאקעגן אין דעם צווייטן ד\"ה איז ער מעתיק נאָר דעם וואָרט „נרותי'\" און ניט דעם וואָרט „ואת\".\nח. עפ\"י הנ\"ל — אַז לויט פרש\"י זיינען די נרות ניט געווען אין כלל פון „מקשה\" — איז עס מובן:\nוויבאלד אַז לשיטתו זיינען די „נרות\" ניט פון דער מנורה גופא, דארף מען זאָגן, אַז ווען דער פסוק זאָגט „ככר .. (יעשה) אותה את כל הכלים האלה\"<sup data-n=\"35\">35</sup>, זיינען די נרות נכלל ניט אין „אותה\" (די מנורה) נאָר אין „כל הכלים האלה\" — די נרות זיינען פון די כלי המנורה.\nבשעת מען קומט אָבער צו פרשת ויקהל וואו דער פסוק זאָגט „ואת מנורת המאור ואת כלי' ואת נרותי'\", װערט לפי\"ז שװער: וויבאלד עס שטייט שוין „ואת כלי'\" וואָס איז כולל אויך די נרות — פאַרוואָס שטייט „ואת נרותי'\" באַזונדער?\nכדי דאָס צו פאַרענטפערן, שטעלט זיך רש\"י אויף „ואת כלי'\" און איז מפרש — „מלקחים ומחתות\", און גלייך דער־נאָך איז ער מעתיק פון פסוק „נרותי'\" און איז דערביי משמיט דעם וואָרט „ואת (נרותי')\" — מיט דער כוונה צו מדגיש זיין דערמיט, אַז מ'דארף לערנען דעם פסוק כאילו ווי עס וואָלט פאַר „נרותי'\" ניט געשטאַנען דער וואָרט „ואת\" — ווייל „נרותי'\" איז (אויך) אַ פרט פון „ואת כלי'\"<sup data-n=\"36\">36</sup>, ד.ה. דער פירוש פון פסוק איז: „ואת כלי' (וואס זיי זיינען) מלקחים מחתות נרותי'\".",[["34","34","וכרשב\"ם פרשתנו כאן."],["35","35","ועד\"ז בפ' תשא ל, כז. לא, ח. ויקהל לז, כד."],["36","36","משא\"כ „שמן המאור\". שלכן מעתיק רש\"י תיבת „ואת\" בד\"ה שלאח\"ז — „ואת שמן המאור\" — אף שלגוף פירושו שם אין נוגע תיבת „ואת\"."]]],[1300161342,"ט. עס בלייבט דאָך אָבער ניט פאַר־שטאַנדיק: פאַרוואָס דארף דער פסוק טאַקע אויסטיילן „נרותי'\" פון צווישן די כלי המנורה?\nאויף דעם זאָגט רש\"י — „לוציני\"ש בלעז\", וואָס דער שרש פון דעם וואָרט „בלעז\" — מיינט ליכטיקייט, און דער טעם פאַרוואָס די נרות ווערן אָנגערופן ע\"ש האור, איז (ווי רש\"י איז ממשיך) „בזיכים שהשמן והפתילות נתונין בהן\", ד.ה. ווייל אין זיי דריקט זיך אויס דער מכוון און תכלית פון דעם עצם המנורה — צו שאַפן ליכטיקייט<sup data-n=\"37\">37</sup> [וואָס ווערט געשאַפן פון (דאָס וואָס איז אין) די נרות („שהשמן והפתילות נתונין בהן\"<sup data-n=\"38\">38</sup>)].\nאון וויבאלד אַז די נרות זיינען דער עיקר פון דער גאַנצער מנורה — איז פאַרשטאַנדיק פאַרוואָס דער פסוק טיילט זיי אויס באַזונדער פון די (אַנדערע) כלי המנורה<sup data-n=\"39\">39</sup>.\n(משיחת ש\"פ ויק\"פ תשל\"ז)",[["37","37","ואף שאין צריך לאורה (פרש\"י בהעלותך ח, ב) — מ\"מ מובן, שענינה של המנורה הוא אור וכמש\"נ שמן למאור, ושמה מוכיח: מנורת המאור."],["38","38","ובזה מתורץ ג\"כ שינוי לשון רש\"י בפרשתנו לגבי פ' ויקהל: בפרשתנו — „כמין בזיכין שנותנין בתוכן השמן והפתילות\" (שמדבר ע\"ד פעולת האדם — „שנותנין כו'\"), ובפ' ויקהל — „בזיכים שהשמן והפתילות נתונין בהן\" (מדבר ע\"ד „השמן והפתילות (שהם) נתונין בהן\"), כי בפרשתנו מבאר צורת הנרות ותפקידם („כמין בזיכין כו'\"), ובפ' ויקהל — שהנרות הם מקור ומקום האור (מפני „שהשמן והפתילות נתונין בהן\")."],["39","39","ועפ\"ז מובן מה שדוקא בפ' ויקהל מוסיף רש\"י „בזיכים כו'\" ולא בפ' תצוה שרק מביא ה„לעז\" (כנ\"ל הערה 31): בפ' תצוה מבאר פירוש החיבה, ולזה די הפירוש דה„לעז\" של נרות שהוא ע\"ש האור; משא\"כ בפ' ויקהל שכוונת רש\"י לבאר שהנרות הם עיקר המנורה (שלכן נפרטו בפ\"ע), ולכן מסביר איך שהנרות הם ענין האור („שהשמן והפתילות נתונין בהן\")."]]],[1300161343,"<h3>תצוה</h3>\nא. ביים ציווי¹ „ועשית את מעיל האפוד גו׳“ זאגט דער פסוק²: „שפה יהי׳ לפיו סביב מעשה ארג כפי תחרא יהי׳ לו לא יקרע“ — שטעלט זיך רש״י אויף די ווערטער „לא יקרע“ און איז מפרש: „כדי שלא יקרע והקורעו עובר בלאו וכו׳“ (וכדלקמן ס״ב).\nאיז ניט פארשטאנדיק: פון דעם וואס רש״י זאגט (אין אנהויב פון זיין פירוש) אז „לא יקרע“ מיינט „כדי שלא יקרע“, איז קלאר אז רש״י נעמט אן, אז „לא יקרע“ איז ניט קיין ענין (וציווי) פאר זיך, נאר ס׳איז א נתינת טעם אויף דעם וואס שטייט פריער אין פסוק — „שפה יהי׳ לפיו גו׳ כפי תחרא גו׳ (כדי ש)לא יקרע“ —\nהיינט ווי איז רש״י מוסיף בהמשך לזה (און מיט א וא״ו המוסיף) „והקורעו עובר בלאו“, וואס לויט דעם זיינען די ווערטער „לא יקרע“ (ניט א נתינת טעם³, נאר) א ציווי, א לאו בפ״ע?\nנאך שטארקער איז די תמי׳: אין גמרא⁴ שטייט טאקע — „אמר רחבא אר״י המקרע בגדי כהונה לוקה שנאמר לא יקרע. מתקיף לה רבא״ ודלמא הכי קאמר רחמנא נעביד לי׳ שפה כי היכי דלא ניקרע. מי כתיב שלא יקרע“. ד. ה. אז דאס טייטשן „לא יקרע“ — „כי היכי דלא ניקרע“, איז בסתירה צום זאגן אז ס׳איז א לאו.\n[און דערפאר געפינט מען טאקע אין מפרשי התורה⁵ צוויי שיטות: אנדערע טייטשן אז „לא יקרע“ איז בלויז א נתינת טעם אויף פריער, און אנדערע טייטשן אז ס׳איז א לאו בפ״ע].\nאיז תמוה: ווי איז עס רש״י מצרף צוויי פארקערטע פירושים אין איין און דעם זעלבן פירוש⁶?\nב. דערנאך איז רש״י ממשיך: „שזה ממנין⁷ לאוין שבתורה וכן ולא⁸ יזח החושן⁹ וכן לא יסורו ממנו¹⁰ הנאמר בבדי הארון¹¹“.",[["1","1","פרשתנו כח, לא."],["2","2","שם, לב."],["3","3","שהרי ע״ד הפשט אין מסתבר לומר שטעם המצוה הוא גם ציווי בפ״ע. השק״ט בזה ע״ד ההלכה — ראה סהמ״צ להרמב״ם שורש ה׳ ובנ״כ שם. וראה באמ״ח בפירש״י כאן."],["4","4","יומא עב, א."],["5","5","ראה פי׳ הרס״ג עה״ת. פי׳ הר״א בן הרמב״ם. מנחה בלולה. ועוד. ובת״א כאן*: „דלא יתבזע“. משא״כ בתיב״ע (וכן בתרגום ירושלמי) כאן**: „לא יתבזע“. ועוד."],["6","6","בצידה לדרך כאן כ׳ „ומה שפרש״י אחר כך והקורעו עובר בלאו כו׳ או אן קאמר“ (ועד״ז כ׳ בס׳ זכרון כאן) — אבל קשה לפרש כן כוונת רש״י, דא״כ הול״ל „ד״א“ וכיו״ב (כדרכו בכ״מ)."],["7","7","בדפוס ב׳ דרש״י ובכמה כת״י דרש״י (וכ״ה בלב שמח שנסמן בהערה 17): שזה אחד מן הלאוין שבתורה. וראה לקמן הערה 29."],["8","8","בכמה דפוסים (כולל דפוס א׳ וב׳) דרש״י: „לא“. אבל בכתוב נאמר „ולא“."],["9","9","פרשתנו שם, כח."],["10","10","תרומה כה, טו."],["11","11","הטעם שרש״י מקדים הכתוב דפרשתנו *) אבל עוד גירסא בת״א כאן — „לא יתבזע“. וראה בארוכה בנתינה לגר. ועוד. וכן יש ב׳ גירסאות בתרגום ד„ולא יזח“ (וכן לקמן בפקודי לט, כא. כג) — הובאו בחו״ש — משא״כ ב„לא יסורו“ מתרגם „לא־יעידון“. וראה לקמן בשוה״ג להערה 18. **) משא״כ בפקודי (שם, כג): „דלא יתבזע“ (וראה לקמן הערה 19). אבל ב„לא יזח“ (בפרשתנו ובפ׳ פקודי (שם, כא)): „ולא יתפרק“."]]],[1300161344,"אין פשטות קומט אויס, אז מיט דער הוספה „שזה ממנין לאוין שבתורה“ איז רש״י אויסן צו ברענגען א ראי׳ אז „לא יקרע“ איז א לאו — כאטש די משמעות הכתוב איז (ווי רש״י טייטשט בתחילת פירושו) „כדי שלא יקרע“.\nאיז ניט מובן: רש״י׳ס פירוש איז דאך מיוסד אויף פשוטו של מקרא¹² — איז פון וואנעט נעמט רש״י פון פשטות הכתובים אז „לא יקרע“ איז „ממנין לאוין שבתורה“?\n[אמת טאקע, אז דער ענין פון מנין המצות בכלל ווערט שוין געבראכט אין פירוש רש״י עה״ת¹³ — און במילא, האט דאס אן ארט אין פשוטו של מקרא, אבער ס׳איז לכאורה ניטא קיין הכרח אין פשטות הכתובים אז דער לאו¹³* „לא יקרע“ גייט אריין אין דעם מנין¹⁴].\nג. נאך מער ניט פארשטאנדיק איז דער סיום פון פירוש רש״י „וכן ולא יזח החושן וכן לא יסורו ממנו הנאמר וכו׳“.\nמפרשים¹⁵ זאגן, אז מיטן אראפ־ברענגען די צוויי פסוקים איז רש״י אויסן צו ברענגען א דוגמא לפירושו אז „לא יקרע“ איז סיי א לאו בפ״ע און סיי א נתינת טעם („כדי שלא יקרע“) —\nווארום אויך אין יענע פסוקים איז דער פירוש הפשוט אין „ולא יזח“ און „לא יסורו“ — „כדי שלא יזח“, „כדי שלא יסורו“, און דאך זיינען זיי לאוין בפ״ע און ווערן אריינגערעכנט אין מנין הלאוין.\nאיז ניט פארשטאנדיק [נוסף אויף דער שאלה (ע״ד הנ״ל ס״ב): אויף דארטן, פון וואנעט נעמט רש״י פון פשטות הכתובים אז זיי זיינען „ממנין לאוין שבתורה“?]:\nאויף די פסוקים „ולא יזח“ און „לא יסורו“ שטעלט זיך ניט רש״י צו אויסטייטשן אז זיי זיינען א נתינת טעם און א לאו בפ״ע — איז ממ״נ: אויב ס׳איז דא א שוועריקייט אין טייטשן „לא יקרע“ סיי אלס טעם און סיי אלס לאו, האט דאך רש״י געדארפט זיך אפ־שטעלן אויף „לא יסורו“ און „ולא יזח“ וואס שטייען פריער אין חומש¹⁶; און אויב רש״י האלט אז אין אט דעם פירוש איז ניטא קיין שוועריקייט [ואדרבה: ס׳איז אויף אזוי פיל פשוט, אז רש״י דארף דאס גארניט מפרש זיין ווייל דער „בן חמש“ וועט זיך אליין כאפן אויפן פירוש] — פארוואס דארף רש״י דאס באווארענען אין אונזער פסוק (און נאך ברענגען ראיות לפירושו)?\nד. אויף דער ערשטער שאלה (דלעיל ס״א) פארענטפערן מפרשים¹⁷: לפי פשוטו של מקרא דארף אויס־קומען, אז „לא יקרע“ (און אזוי אויך „ולא יזח“ און „לא יסורו“) איז ניט קיין ציווי, נאר א נתינת טעם אויף פריער; אבער אויב דאס וואלט געמיינט בלויז א",[["","","להכתוב דפ׳ תרומה (הקודמו) — כי „ולא יזח“: א) נאמר על אתר (בהפסק איזה פסוקים). ב) מדובר ג״כ בבגדי כהונה. וראה לקמן בפנים ס״י טעם בפנימיות העניינים."],["12","12","פרש״י בראשית ג, ח. ובכ״מ."],["13","13","וישלח לב, ה. משפטים כד, יב. וראה גם פרש״י שלח טו, לט. 13*) להעיר מתודה״ק רבי (סוטה ג, א)."],["14","14","ולהעיר, שלדעת הבה״ג „לא יקרע“ אינו ממנין המצות — אף שמנה „לא יסורו“ ו„ולא יזח“. וראה הגהה לריטב״א יומא שם. ביאור הרי״פ פערלא לסהמ״צ רס״ג מל״ת ריב־ריד (רלח, ג). ועוד."],["15","15","ש״ח (בשם הגר״א). וראה באמ״ח (לאחי המהר״ל) לפירש״י כאן. ועוד."],["16","16","וראה במרגניתא טבא לסהמ״צ שורש ה׳."],["17","17","ש״ח (בשם הגר״א). נחלת יעקב (נעתק במרגניתא טבא שם). באר יצחק (בפרש״י כאן). לב שמח לסהמ״צ שם. נתינה לגר כאן. וראה רמב״ן בהשגותיו לסהמ״צ שם."]]],[1300161345,"נתינת טעם, האט געדארפט שטיין „שלא יקרע“ (ווי די גמרא פרעגט טאקע). דערפון וואס ס׳שטייט „לא יקרע“ (און אזוי אויך „ולא יזח“¹⁸ און „לא יסורו“) איז געדרונגען, אז די תורה איז דערמיט מרמז א צוויי־ענדיקן באדייט: א) די פשטות משמעות הכתוב — א נתינת טעם אויף פריער; ב) א ציווי — „לא יקרע“.\nעס בלייבט אבער שווער (כדלעיל ס״ג): פארוואס איז רש״י ניט מפרש אט דאס אלעס פריער אויף „לא יסורו“ און „ולא יזח“?\nה. איז דער ביאור אין דעם: על דרך הפשט דארף אויסקומען, אז „לא יסורו“ און „ולא יזח“ זיינען ניט קיין נתינת טעם, נאר בלויז א ציווי ולאו בפ״ע — ווארום, ווי געזאגט פריער, אויב ס׳איז א נתינת טעם האט געדארפט שטיין „שלא יסורו“, „שלא יזח“¹⁹ (וכקושיית הגמרא);\nאון הגם עס שטייט ניט בלשון „לא תסירום“ (אדער „ולא תזיח“) — וואס וואלט געמיינט א ציווי אויפן מענטשן: דו זאלסט זיי ניט אפטאן, נאר — „לא יסורו“, אז די בדים זאלן ניט אפגעטאן ווערן פון די טבעות (און אזוי אויך „ולא יזח“)²⁰ —\nקען עס געטייטשט ווערן ווי א ציווי: דער מענטש דארף זיך משתדל זיין אז די בדים זאלן ניט אפגעטאן ווערן פון די טבעות (ועד״ז ביי „ולא יזח“); און ע״ד ווי דער ציווי אין אנהויב פסוק²¹ „בטבעות הארון יהיו הבדים“ — וואס איז א ציווי, הגם דער פסוק רעדט ניט וועגן פעולת האדם, נאר וועגן די בדים („בטבעות הארון יהיו הבדים“).\nא שינוי איז אבער אין אונזער פסוק, וואו עס שטייט „לא יקרע“ (קו״ף קמוצה ורי״ש צרוי׳)²² — בנין נפעל וואס דעמאלט — אויב דאס איז א ציווי ווי „ולא יזח“ און „לא יסורו“ — דארף זיין א שינוי און א הוספה מער ווי בא זיי אין דעם ציווי „לא יקרע“, ווי רש״י טייטשט (בא כל מלאכה לא יעשה בהם²³): אפילו ע״י אחרים²⁴. ד״ה אז „ולא יזח“ און „לא",[["18","18","במרגניתא טבא שם (וראה גם רש״ש ליומא שם) כ׳ דהוא״ו ד„ולא יזח“ משמש כש״ין, ולכן פשוט דהוא נתינת טעם* [וקושיית הגמרא (שם) „מי כתיב שלא יזח“ מפרש באו״א, עיי״ש] — אבל (נוסף לזה דאם כן ס״ל לרש״י הו״ל לפרש (ב„ולא יזח“) ולא לסתום — הרי) בפירש״י כאן מפורש „והקורעו עובר בלאו כו׳ וכן ולא יזח“, היינו ש„ולא יזח“ הוא לאו, ולפי דבריו למה צריכים לדחוק שהוא (גם) לאו?"],["19","19","ואף דבמש״כ לקמן (פקודי לט, כא) „וירכסו גו׳ להיות על חשב האפוד ולא יזח החושן גו׳“ *) — ועד״ז לא תהי׳ סתירה מפרש״י שופטים (יז, טז) „שלא ישיב“ משא״כ „לא יסורו“ דליכא וא״ו — הוא ציווי (וב„לא יקרע“ שפרש״י „כדי שלא יקרע“ — אף שליכא וא״ו — יש לחלק ע״פ המבואר לקמן בפנים). ולהעיר דבפקודי (לט, כא. כג) נאמר „ולא יזח“ ו„לא יקרע“ בדרך סיפור (ראה הערה הבאה והערה 27), משא״כ אצל הבאת הבדים בטבעות בפ׳ ויקהל (לז, ה) לא נאמר „לא יסורו“. מוכרח לפרש שאינו ל׳ ציווי (כ״א המשך שלפניו), שהרי זהו חלק מהסיפור דעשיית המשכן וכליו — הרי מובן דבמקום שאפשר מתאים יותר לפרש שהוא ל׳ ציווי (מכיון שלא נאמר „שלא גו׳“). ופשוט דאין לפרש (עכ״פ בדרך הפשט) שכוונת הכתוב היא לשני ענינים — הן לאו והן נתינת טעם — כשאין הכרח בדבר."],["20","20","ראה נתינה לגר כאן. חו״ש כאן. וע״ד ההלכה — ביאור הרי״פ פערלא לסהמ״צ רס״ג שם."],["21","21","תרומה שם."],["22","22","ראה דבק טוב כאן."],["23","23","בא יב, טז. וראה רמב״ן שם."],["24","24","החילוק דיקרע יעשה יאכל (ק, ע, א — בקמץ) וכו׳ (לגבי יזח, יסורו וכו׳) — שהם מדגישים „באיזה אופן שיהי׳“ או בל׳ רש״י (שבפנים) „אפילו ע״י אחרים“, „שום אכילה“ (רש״י פסחים כא, ב ד״ה לא), משא״כ הנ״ל דאין מדברים עד״ז."]]],[1300161346,"וואס די תורה שרייבט „לא יקרע“ (און ניט „שלא יקרע“) נאר בכדי מוסיף צו זיין א לאו.\nט. פון די „ענינים מופלאים“ ע״ד ההלכה אין דעם פירוש רש״י: דער רמב״ם³⁹ פסק׳נט „הקורע פי המעיל לוקה שנאמר לא יקרע והוא הדין לכל בגדי כהונה שהקורען דרך השחתה לוקה“. פון פשטות לשון הרמב״ם קומט אויס, אז ס׳איז דא א חילוק צווישן אלע בגדי כהונה און דעם מעיל: ביי אלע בגדי כהונה איז מען לוקה נאר „הקורען דרך השחתה“, אבער „הקורע פי המעיל לוקה“ — בכל אופן⁴⁰.\nזיינען אחרונים⁴¹ מסביר דעת הרמ־ב״ם: דאס וואס הקורע כל בגדי כהונה לוקה, איז עס מצד דעם לאו פון „לא⁴² תעשון כן גו׳“⁴³ (און דער לאו איז נאר „דרך השחתה“⁴⁴); משא״כ ביי מעיל, קומט־מלקות מצד דעם לאו „לא יקרע“ — און ביי דעם לאו איז מען חייב מלקות בכל ענין.\nווי רש״י לערנט אבער אין פשטות הכתובים, אז דער פסוק איז מוסיף דעם לאו „לא יקרע“ ניט צוליב מוסיף זיין א נייעם איסור, נאר בכדי דאס זאל אריין־גיין אין „מנין לאוין שבתורה“,\nדארף לפי זה אויסקומען, אז לשיטת רש״י (בפירושו על התורה) איז ניטא קיין חילוק אין דעם אופן הקריעה צווישן דעם מעיל און אנדערע בגדי כהונה⁴⁵.\nיוד. פון דעם יינה של תורה אין פירוש רש״י:\nלכאורה איז ניט מובן (בפנימיות הענינים⁴⁶): פארוואס ברענגט רש״י די ראי׳ פון „ולא יזח“ וואס שטייט אין אונזער סדרה פאר דער ראי׳ פון „לא יסורו“ וואס שטייט אין דער פריערדי־קער סדרה?\nאויך: פארוואס איז רש״י מוסיף נאכאמאל דעם ווארט „וכן⁴⁷ לא יסורו כו׳“?\nאיז דערפון מובן, אז דער לאו „לא יסורו“ איז נאך א חידוש און א גרעסערער חידוש ווי דער לאו „ולא יזח“, וואס דעריבער ברענגט אים רש״י",[["","","יזח“ ו„לא יסורו“], אלא שהם גם לאוין (מכיון שלא נאמר „שלא כו׳“), ולפ״ז גם הוספת לאוין אלה הוא רק מפני „שזה ממנין לאוין כו׳“."],["39","39","הל׳ כלי המקדש פ״ט ה״ג. ושם ה״י: וכל המזיח חושן כו׳ דרך קלקול לוקה. אבל בבדים כתב סתם „שהמסיר כו׳ לוקה“ (שם ספ״ב)."],["40","40","כ״כ בקרבן חגיגה סי׳ סח (הובא במל״מ שם). אבל לדעת כמה (ראה מל״מ שם. קרית ספר שם. רי״פ פערלא שם. ועוד) כוונת הרמב״ם היא דגם במעיל אינו לוקה כ״א „דרך השחתה“. וכן משמע דעת החינוך (מצוה קא), כמ״ש במנ״ח שם."],["41","41","מנ״ח שם (ומפרש כן כוונת הכס״מ). צפע״נ על הרמב״ם — הפלאה בהשמטות (נד, ב). ונעתק בצפע״נ עה״ת כאן."],["42","42","ראה יב, ד."],["43","43","ואף שביומא שם איתא „המקרע בגדי כהונה לוקה שנאמר לא יקרע“ — ראה מנ״ח שם, דלדעת ר״ל בזבחים (צה, א) הלאו דלא יקרע הוא רק במעיל, והרמב״ם פסק כר״ל. ולכאורה כ״ה ע״פ פשש״מ — שיטת רש״י בפירושו עה״ת — שהרי לא נזכר בפרש״י דגם בשאר בגדי כהונה עובר על לא יקרע. וכן כתב „והקורעו“ — המעיל."],["44","44","ראה כס״מ שם. ועוד."],["45","45","אף שאת״ל דע״ד הפשט המקרע בגדי כהונה א״ע משום „לא תעשון גו׳“, ונמצא דהמקרע בגדי כהונה עובר רק בעשה (דלכבוד ולתפארת), ובמעיל לוקה משום לא יקרע (את״ל דהלאו דלא יקרע הוא רק במעיל, כנ״ל הערה 43) — בכ״ז, י״ל דאין זה הוספה באופן פעולת האיסור כ״א רק בחומר האיסור. ואדרבא ע״ד הפשט, כל קריעה — באיזה אופן שהוא — היא היפך ד„לכבוד ולתפארת“."],["46","46","משא״כ ע״ד הפשט — ראה לעיל הערה 11."],["47","47","ובדפוס שני דרש״י וברש״י כת״י — ליתא."]]],[1300161347,"נאך „ולא יזח“ און איז דערפאר מוסיף נאכאמאל „וכן“.\nדער ביאור אין דעם: דער לאו „לא יקרע“ איז ניט קיין חידוש גדול. ס׳איז א פארשטאנדיקע זאך אז מ׳טאר ניט מקלקל זיין די בגדי כהונה.\nדערנאך זאגט רש״י „וכן ולא יזח החושן“: אויך דאס אפרוקן דעם חושן מעל האפוד — כאטש ס׳איז דערין ניטא קיין קלקול — איז אויך א לאו; אבער אויך דאס קען מען פארשטיין, ווי דער פסוק אליין איז דארט ממשיך⁴⁸: „ונשא אהרן את שמות בני ישראל בחשן המשפט על לבו גו׳ לזכרון לפני ה׳ תמיד“.\nס׳איז אבער לכאורה אינגאנצן ניט מובן דער טעם פון „בטבעות הארון יהיו הבדים לא יסורו ממנו“: די בדי הארון זיינען געמאכט געווארן בכדי מ׳זאל דעם ארון קענען ארומטראגן ממקום למקום — צוליב וואס דארפן די בדים זיין בטבעות הארון אלעמאל? אדרבא בפשטות האט דער סדר געדארפט זיין אז מ׳זאל זיי אריינלייגן אין די טבעות ווען מ׳וועט דארפן דעם ארון טראגן?\nדעריבער זאגט רש״י (נאכאמאל) „וכן לא יסורו ממנו הנאמר בבדי הארון“: אויך דאס ארויסנעמען די בדים פון די טבעות איז א לאו, און פונקט אזא לאו ווי דער לאו פון צערייסן און מקלקל זיין בגדי כהונה.\nיא. וואס איז טאקע דער טעם וואס „לא יסורו ממנו“? זאגט דערויף דער ספר החינוך⁴⁹: „נצטוינו לבל נסיר בדי הארון ממנו פן נהי׳ צריכים לצאת עם הארון לשום מקום במהירות ואולי מתוך הטרדא וחפזון לא נבדוק יפה להיות בדים חזקים כל הצורך כו׳ אבל בהיותם בו מוכנים לעולם ולא יסורו ממנו יעשו אותן חזקות כו׳“.\nאון דערפון קומט ארויס א הוראה נפלאה אין עבודת כאו״א:\nאין דעם ארון זיינען געלעגן די לוחות, וואס דאס איז דער ענין התורה, און אין לשון חינוך⁵⁰: הארון משכן התורה.\nאויך א איד וואס לערנט תורה איז בדוגמת „הארון“ — ער איז אן ארט און „משכן התורה“: קען א איד ביי זיך טראכטן: אין דער צייט וואס ער דארף זיך אפגעבן מיטן לימוד התורה, ובפרט אויב „תורתו אומנתו“, דארף ער דאך זיין אינגאנצן איבערגעגעבן צום לימוד און זיין מובדל פון אלעס ארום זיך — וואס פאר אן ארט האט עס דעמאלט צו טראכטן וועגן א צווייטן איד?\nאויף דעם איז די הוראה פון די בדי הארון: אפילו ווען דער ארון געפינט זיך אין קדשי קדשים — דער מקום הכי מקודש בעולם (וואס דערפאר קען אהין אריינגיין נאר דער כהן גדול און נאר ביום הכיפורים) — אויך דאן מוזן די בדים זיין „מוכנים לעולם“, בכדי מ׳זאל מיט זיי קענען ברענגען דעם ארון „במהירות“ צו דעם ארט וואו מ׳האט אים געדארפט האבן. און נאכמער: דאס ארויסנעמען די בדים פון די טבעות פארמאגט אין זיך די זעלבע הארבקייט ווי צערייסן און מקלקל זיין בגדי כהונה!\nאון אזוי איז אויך אין דעם ענין פון",[["48","48","כח, כט."],["49","49","מצוה צו. וראה עוד טעמים בד״ז (לבעה״ת) תרומה שם. מו״נ ח״ג ספמ״ה. ועוד."],["50","50","שם."]]],[1300161348,"תורה: וויפל עס זאל זיין א איד׳ס אריינגעטאנקייט אין לימוד התורה, דארף ער אלעמאל זיין „מוכן“ אויף צו ברענגען תורה ווען נאר און וואו נאר מ׳זאל דאס דארפן, און דוקא אין אן אופן פון „מהירות“⁵¹, צו נאך אידן און נאך אידן.\n(משיחות ש״פ תצוה תשל״ב)",[["51","51","ראה הפס״ד (שו״ע יו״ד ר״ס רמז) בנוגע לצדקה גשמית: ומאד יש ליזהר כו׳ אם לא יתן לו מיד כעובדא דנחום איש גם זו. ובפרט ע״פ המבואר במק״א דהבאת עובדא בשו״ע דמרן (ועד״ז בשו״ע אר״ח סק״י ס״ו), שהוא ספר פס״ד בלבד, אומר דרשני."]]],[1300161349,"<h3>תצוה ב</h3>\nא. בנוגע דעם מעיל, זאגט דער פסוק¹ „ועשית על שוליו רמוני תכלת גו׳ על שוליו סביב ופעמוני זהב בתוכם סביב”.\nאיז רש״י מפרש, אז כאטש די רמונים זיינען געווען „עגולים וחלולים”², איז אבער דער פשט פון „ופעמוני זהב בתוכם” [ניט אז די פעמונים האבן זיך געפונען אינעם חלל פון די רמונים, נאר] „ביניהם³ סביב, בין שני רמונים פעמון אחד דבוק ותלוי בשולי המעיל”.\nפרעגט דערויף דער רמב״ן⁴: לויט רש״י׳ס פשט קומט אויס אז „לא היו הרמונים משמשין כלום”⁵; און אויב זיי זיינען געווען בלויז „לנוי” — „למה היו עשויים כרמונים חלולים יעשם כמין תפוחי זהב”? ענטפערט דער רא״ם⁶: לא ידעתי למה בחר התפוחים יותר מן הרמונים.\nמפרשים⁷ זיינען מבאר, אז די קשיא פון רמב״ן איז בנוגע דעם פרט פון „חלולים”⁸: וויבאלד אז די פעמונים זיינען ניט געהאנגען אינעם חלל פון די רמונים, צוליב וואס האט מען געמאכט רמונים חלולים?\nעס בלייבט אבער ניט מובן: אויב אז דעם רמב״ן׳ס קשיא איז נאר וועגן דעם פרט פון „חלולים” — פארוואס דער־מאנט ער דא בכלל און איז נאך משנה (אנשטאט „רמונים” —) „תפוחים” („יעשם כמין תפוחי זהב”)⁹?\nב. לכאורה קען מען דאס מסביר זיין: מען געפינט אז אין דער מנורה זיינען געווען — לנוי — גביעים כפתורים ופרחים¹⁰; און די כפתורים זיינען געווען „כמין תפוחים”¹¹; און ווי־באלד אז די רמוני המעיל האבן גענוצט (לדעת רש״י) בלויז „לנוי” — האבן זיי אויך געדארפט זיין (ניט בדמות רמונים, נאר) „כמין תפוחים” (בדומה צום נוי (שבדמות פרי) פון דער מנורה).\nעס בלייבט אבער ניט פארשטאנדיק:\nא) דאס גופא דארף האבן א ביאור — מיט וואס איז „נוי” פארבונדן דוקא מיט „תפוחים”?",[["8","8","ולהעיר שהרא״ם לא העתיק תיבת „חלולים” שברמב״ן. וראה הערה הבאה."],["9","9","ואולי י״ל כי תכשיטים בדמות רמונים בימיהם היו עשויים חלולים (משא״כ תפוחים). וגם כוונת הרא״ם בקושייתו „למה בחר כו׳” היא — למה בחר תכשיט מלא (תפוחים) יותר מתכשיט חלל (רמונים). אבל עדיין אינו גלאטיק כל צרכו, כי למה לי׳ להרמב״ן בכלל להוסיף התיבות „יעשם כמין תפוחי זהב” ולא הסתפק במש״כ „למה היו עשויים כרמונים חלולים”."],["10","10","תרומה כה, לא (וברש״י שם ד״ה גביע״)."],["11","11","רש״י שם ד״ה כפתורי׳."],["1","1","פרשתנו כח, לג."],["2","2","לשון רש״י ד״ה רמוני."],["3","3","רש״י ד״ה בתוכם סביב (ועד״ז בפרש״י פסוק לד). וכ״ה בת״א כאן. רשב״ם, ראב״ע (בשם „קדמונינו ז״ל”) ועוד."],["4","4","פסוק לא."],["5","5","כי לדעת רש״י הפעמונים הם „זגין עם ענבלין שבתוכם” — ולא כדעת התוס׳ (סוף קנים) שאע״פ שהרמונים היו תלוין בשולי המעיל אצל הפעמונים (כדעת רש״י), הקול יצא ע״י שנוגפים הפעמונים אל הרמונים (ולא מהפעמונים עצמם). וראה חזקוני ומדרש לקח טוב כאן. רשב״ם פסוק לה."],["6","6","בפרש״י כאן."],["7","7","נמוקי שמואל. *) ובפקודי (לט, כה) תרגם „בגו רמוניא”. ובתיב״ע פרשתנו ופקודי שם: במצעיהון, במציעות רומניא. ואכ״מ."]]],[1300161350,"ב) לדעת רש״י — וואס איז דער טעם וואס ביים מעיל זיינען געווען רמונים (לנוי) און ביי דער מנורה תפוחים?\nג. וועגן צוועק פון די פעמוני המעיל זאגט דער פסוק¹²: „ונשמע קולו בבואו אל הקודש”; און אויף אזויפיל איז דאס געווען נוגע אין דער עבודה פון כהן גדול, אז דורך דעם („ונשמע קולו”¹³) ווערט ער אויסגעהיט פון „ולא ימות” וואס „מכלל¹⁴ לאו אתה שומע הן”¹⁵.\nדארף מען פארשטיין: פארוואס איז „ונשמע”, דער קלינגען פון די פעמונים א הכרח „בבואו אל הקודש”? לכאורה איז אדרבה — „לא ברעש ה׳”, נאר ב„קול דממה דקה”¹⁶; און ווי מ׳זעט עס ביים כהן גדול גופא, אז זיין כניסה לפני ולפנים (ביום הכפורים) איז געווען דוקא אן (די בגדי זהב¹⁷, ובמילא אן דעם מעיל מיט) דעם קול הפעמונים¹⁸.\nדער רמב״ן¹⁹ איז מסביר, אז „הבא בהיכל מלך פתאום חייב מיתה”, און דער קול הפעמונים איז אזוי ווי א „נטילת רשות”²⁰ אריינצוגיין און טאן די עבודה\n[און דאס וואס דער כה״ג דארף ניט קיין „נטילת רשות” ביים אריינגיין ביוהכ״פ לפני ולפנים — דלכאורה וואלט זיך עס געפאדערט במכל שכן וק״ו — איז דער טעם²¹, ווייל ביוהכ״פ ווייזט ארויס דער אויבערשטער די מעלה פון אידן „שלא הצריכן הכתוב לשליח”²² (זיי דארפן ניט אנקומען צו די פעמונים „להשמיע קול כאדם ששולח שליח להודיע שהוא בא”²³)].\nלויט דעם פירוש²⁴ קומט אויס, אז דער „ונשמע קולו” פון די פעמונים איז ניט קיין חלק פון דער עבודה, נאר בלויז א הקדמה והכנה צו דער עבודה:\nוויבאלד אבער אז יעדער פרט בשייכות דער עבודה פון כהן גדול איז בתכלית הדיוק ובמכש״כ אזא וואס איז פארבונדן מיט עונש מיתה, כנ״ל — און די פעמונים האבן משמיע קול געווען אויך בשעת העבודה גופא²⁵ — איז",[["12","12","לקמן פסוק לה."],["13","13","הראב״ע (בפי׳ הקצר) ובחיי כאן מביא פירוש ד„ונשמע קולו” קאי על קול תפלתו של אהרן. אבל בפשטות קאי על קול הפעמונים (כפי הרשב״ם, רמב״ן (פסוק מג) וכו׳ עה״פ). גם לפרש״י שהתיבות „ולא ימות” קאי על הנכנס מחוסר בגדים — מ״מ, התיבות „ונשמע קולו” הם טעם על הפעמונים, כמ״ש במפרשי רש״י. וראה הערה הבאה."],["14","14","לשון רש״י עה״פ. — ברש״י שם, ש„ולא ימות” קאי על הנכנס מחוסר בגדים. וראה רא״ם (וגו״א) שם, שלרש״י „ולא ימות” דבוק עם מלת לשרת. אבל מזה שנאמרה אזהרה זו גבי המעיל, ובהמשך להפעמונים — מובן, שעיקר החידוש בהציווי הוא בנוגע להמעיל ופעמונים, וכמ״ש בגו״א כאן: ולא תאמר כי אין הפעמונים מעכבים שאינה רק לנוי כו׳ ואם נכנס במעיל בלא פעמונים חייב מיתה כו׳."],["15","15","ראה רמב״ן (לקמן פסוק מג). רקאנטי, בחיי, אוה״ח ועוד עה״פ."],["16","16","מ״א יט, יא־יב."],["17","17","אחרי טז, ד. תו״כ (ורש״י) עה״פ. ר״ה כו, א. ועוד."],["18","18","אבל להעיר מרש״י יומא (מד, סע״ב) דביוהכ״פ הי׳ „טבעת .. שמקשקש ומשמיע קול משום ונשמע קולו בבואו וגו׳”. וראה ר״ח, תוס׳ ותוי״ט שם."],["19","19","פרשתנו שם. רקאנטי ובחיי שם. וראה ר״ח ותוי״ט יומא נב, רע״א. וראה ויק״ר פכ״א, ח. ועוד."],["20","20","לשון הרקאנטי ובחיי שם."],["21","21","בחיי שם. והוא ע״פ (פי׳ הר״ח ותוי״ט) יומא שם."],["22","22","יומא שם."],["23","23","לשון התוי״ט (ועד״ז בר״ח) שם."],["24","24","ועד״ז לטעם הב׳ שברמב״ן וכו׳ שם. הטעם שבאברבנאל פרשתנו. ועוד."],["25","25","להעיר מגו״א שם, ד„בבואו אל הקודש גו׳ ובצאתו” פירושו מביאתו עד צאתו, היינו כל זמן העבודה."]]],[1300161351,"מסתבר, אז „ונשמע קולו” איז אן ענין וואס איז נוגע דער עבודה גופא²⁶.\nד. איינער פון די ביאורים אין דעם:\nדער כהן גדול האט געטאן זיין עבודה אלס שליח פון כלל ישראל; און דאס מיינט במילא, אז „בבואו”, אין זיין אריינגיין „אל הקודש”, „נעמט” ער מיט זיך אריין דעם גאנצן כלל ישראל „אל הקודש”.\nעס איז פארשטאנדיק און ערקלערט בכמה מקומות בארוכה²⁷, אז די עבודה פון בעלי תשובה — וואס איז מצד ה„ריחוק”, ער אנטלויפט פון רע — איז מיט א רעש, אזוי ווי איינער וואס אנט־לויפט פון סכנת מות — מיט געשרייי און שטורעם.\nועד״ז איז עס אין דעם סוג עבודה פון יעדן אידן, אפילו פון דעם וואס האט ניט קיין עבירות ר״ל: בשעת ער טראכט זיך אריין ווי אזוי ער איז „רחוק” פון אלקות — צי דערפאר וואס דער נפש הבהמית איז נאך ביי אים בתקפו²⁸ ובמילא איז ער א יש ודבר נפרד פון אלקות; אדער אפילו מצד דעם הרגש המציאות פון זיין טוב — נפש האלקית (טאקע א מציאות דקדושה — אבער פארט א מציאות, ניט ביטול²⁸*) — ווערט ער נתעורר מיט א קול רעש גדול²⁹ צו „אנטלויפן” פון דעם מצב\n[מ׳האט געפרעגט ביים בעש״ט וועגן דעם וואס חסידים מאכן תנועות וכו׳ ביים דאווענען — האט ער געענט־פערט²⁹*, אז דאס איז בדוגמא ווי איינער וואס טרינקט זיך אין ים מאכט ער אלערליי תנועות אויף ראטעווען זיך און שרייט בכל כחו אז מען זאל אים ראטעווען, און זיכער לאכט קיינער ניט פון זיינע תנועות און געוואלדן].\nס׳איז קיין סתירה ניט פון פסוק „לא ברעש ה׳” — ווייל דער דיוק אין דעם איז „לא ברעש הוי׳”³⁰: כדי צו זיין א כלי צום שם הוי׳ (שלמעלה מן העולמות) דארף די עבודה זיין אין דער בחי׳ פון „קול דממה דקה” בתכלית הביטול³¹; משא״כ ווען די עבודה איז (נאך) פאר־בונדן מיט אנטלויפן פון „ישות” ו„מציאות” — וואס זי דערגרייכט צו דער בחי׳ פון שם אלקים³², וואס גיט אן ארט אויף מציאות — די עבודה איז, כנ״ל, פארבונדן דוקא מיט רעש וכו׳³³.\nאון דאס איז דער טעם וואס די עבודה פון כהן גדול א גאנץ יאר איז געווען אין אן אופן פון „ונשמע קולו גו׳”³⁴ — ווייל",[["","","29*) ראה גם כתר שם טוב סי׳ רטו."],["30","30","המשך תער״ב פרק שצט."],["31","31","ראה תקו״ז בהקדמה (ג, ב) — שהו״ע תפלת העמידה, קודש הקדשים. ולהעיר מיל״ש ואתחנן שם."],["32","32","ובשם הוי׳ עצמו — רק באותיות הו״ה, ולא באות יו״ד דעיקר שם הוי׳ הוא היו״ד (תקו״ז שם. המשך תער״ב שם)."],["33","33","ראה סה״מ תש״ח (ע׳ 22), דגם ביטולו של היש הוא ברעש דוקא."],["34","34","אבל אין לומר שה„ונשמע קולו” דהכה״ג הוא ה„רעש” שעליו איתא „אית רעש דייתי (הוי׳) תמן” (תקו״ז תי״ח (לה, ב). אוה״ת לנ״ך ע׳ תא. המשך תער״ב שם) [אלא שעבודת יוהכ״פ בקודש הקדשים היא למעלה (גם) מרעש זה, ולכן היא בקול דממה דקה (ראה הערה 31)] — כי רעש זה הוא בחי׳ קלא פנימאה דלא אשתמע (המשך תער״ב שם), וכאן נאמר „ונשמע קולו”, בחי׳ קלא דאשתמע, כמפורש בזהר (ח״ב רלא, א)."],["26","26","להעיר גם מבעה״ט כאן, ד„ונשמע קולו” קאי על (כללות) ענין העבודה."],["27","27","סה״מ תרצ״ט ע׳ 2 ואילך. סה״מ תש״ב ע׳ 3 ואילך. סה״מ ה׳שי״ת ע׳ 4 ואילך."],["28","28","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא פי״ג</a>. 28*) ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל״ה (מד, סע״א</a> ואילך), ובארוכה — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091210\" data-slug=\"likkutei-sichot\" data-id=\"1300091210\">לקו״ש ח״ט ע׳ 210</a> ואילך."],["29","29","להעיר מיל״ש ואתחנן (רמז תתכה): שהמלאכים .. בקול גדול הן מקלסין .. למה שהן רחוקים מן הקב״ה כו׳."]]],[1300161352,"ער דארף „אריינעמען” מיט זיך „אל הקודש” אויך די אידן וואס זייער סדר העבודה, כניסה לקודש, איז בקול רעש כו׳; ווי ס׳איז אויך מרומז אין דעם וואס די פעמונים זיינען געווען בשולי (בתחתית) המעיל — דער ענין פון „ונשמע קולו” איז פארבונדן מיט די נידעריקע³⁵ מדריגות פון אידן, וואס זייער עבודה איז מצד הריחוק, כנ״ל.\nאון דערביי איז די אזהרה „ונשמע קולו גו׳ ולא ימות” — אז אין דעם איז תלוי דער כללות החיות פון כהן גדול: אויב ביי אים איז ניטא דער „ונשמע קולו” — ער ווייל ניט כולל זיין אין זיין עבודה אט די אידן³⁶ וועלכע זיינען אין בחי׳ „שולי המעיל” (אפילו ווען דאס איז דערפאר וואס ער ווייל האלטן ביי דער העכערער עבודה פון „קול דממה דקה”) — ווערט בטל ר״ל זיין מציאות (מיט זיין עבודה); ווייל די שלימות פון כלל ישראל איז תלוי אין דער עבודה וואס נעמט ארום אלע ששים רבוא ישראל³⁶*, פון ראשיכם שבטיכם גו׳ ביז חוטב עציך ושואב מימיך.\nה. דאס איז אבער נאר ביי דער עבודה פון כהן גדול במשך כל השנה, ווען כניסתו און עבודתו איז נאר אין „קודש” — דארט איז פאראן אן ארט פאר די חילוקי דרגות אין אידן, פון ראשיכם שבטיכם גו׳ ביז חוטב עציך ושואב מימיך, און דערפאר איז ונשמע — עס איז ברעש;\nמשא״כ די עבודה פון כהן גדול ביום הכפורים אין קודש הקדשים איז אן א רעש¹⁸, ווייל דעמאלט³⁷ זיינען די אידן כמלאכים³⁸, די התגלות פון דער התקשרות עצמית פון אלע אידן מיטן אויבערשטן³⁸*; און וויבאלד אז יעדער איד, אפילו די וואס זיינען שייך צו „שולי המעיל”, שטייען דאן בתכלית הקירוב וההתאחדות מיט אלקות — יחידה ליחדך — איז אויך זייער כניסה לקודש הקדשים (דורך דעם כהן גדול) ניט ווי א רחוק שנעשה קרוב [וואס דאן איז עס מיט א רעש כו׳], נאר בתכלית הביטול, בקול דממה דקה.\nו. ע״פ כהנ״ל וועט אויך זיין פאר־שטאנדיק דער חילוק צווישן שיטת הרמב״ן (אז „אם לנוי .. יעשם כמין תפוחי זהב”) און שיטת רש״י (אז אין דעם פאל דארפן זיין „רמונים” [לנוי]):\nאידן זיינען געגליכן סיי צו „תפוח”³⁹ און סיי צו „רמון”. דער חילוק צווישן זיי איז: דער דמיון צו תפוח איז מתאים צו אידן ווי זיי זיינען ברום המעלה⁴⁰; און בחי׳ „רמון” איז בשייכות צו אידן וואס געפינען זיך בשפל המצב „כפלח הרמון רקתך — ריקנין שבך”⁴¹, אבער אויך זיי זיינען אנגעפילט מיט טוב וקדושה —",[["37","37","טאו״ח סתר״ו (מפדר״א פמ״ו). שם (ושו״ע אדה״ז) סתרי״ט, ס״ט (מדב״ר פ״ב, לו). רמ״א ושו״ע אדה״ז שם סו״ס תרי (וראה דב״ר שם — הוצאת ליבערמאן)."],["38","38","וגם במלאכים — האופנים וחיות הקודש ברעש גדול כו׳ משבחים כו׳ (וראה לעיל הערה 29) — לכן גם ביוהכ״פ ישנה עבודה (בחוץ, שהיא) במעיל ונשמע קולו. 38*) ראה בארוכה לקו״ש ח״ד ע׳ 1153 ואילך."],["39","39","שבת פח, סע״א (אבל בתוס׳ שם דהיינו אתרוג). שהש״ר פ״ב, ג (א). זח״ב (רע״מ) קכ, ב. ועוד."],["40","40","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380289\" data-slug=\"likkutei-torah\" data-id=\"4001380289\">לקו״ת בחוקותי מט, ד</a>. אוה״ת נח (נח, א־ב. וש״נ). ועוד."],["41","41","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560034\" data-slug=\"or-hatorah-hb\" data-id=\"8316560034\">שה״ש ד, ג</a>. ברכות נז, א. וש״נ. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830122\" data-slug=\"or-hatorah-hb\" data-id=\"8158830122\">אוה״ת</a> בראשית (כרך ג׳) תפג, ב. במדבר ע׳ קכב. ועוד."],["35","35","להעיר מזהר שם, דאיצטריך קלא דאשתמע וברכאן ישרון על עלמא. וראה אור החמה לזהר שם."],["36","36","להעיר מרמ״א (או״ח רסתקפ״א): צריך שיוציא כל אדם בתפלתו ואם כו׳ גם כו׳. 36*) ראה דב״ר פ״ז, ח."]]],[1300161353,"ווי דער המשך וסיום פון דעם מרז״ל „אפילו ריקנין שבך מלאים מצות כרמון”.\nאין פירוש רש״י, פשוטו של מקרא — וואו די אידן ווערן געזען ווי זיי זיינען בפשטות (בחיצוניות) — זעט מען די אידן שב„שולי המעיל” אין א דרגא פון „ריקנין”; און דעריבער האבן געדארפט זיין דוקא „רמונים”⁴² — צו באווייזן, אז אויך די „ריקנין” [און אפילו די וואס זיינען נידעריקער דערפון — „אפילו פושעי ישראל”⁴³] זיינען אריין מיטן כהן גדול „אל הקודש”, זיי זיינען א טייל פון כלל ישראל, און נאכמער — מלאים מצות כרמון.\nאין פירוש הרמב״ן, וואו עס זיינען דא (ניט נאר „פשטים”, נאר) אויך „דברים נעימים .. ליודעים חן”⁴⁴, איז דארט מודגש די פנימיות פון אידן, וואס מצד דעם האט א איד קיין שייכות ניט צו חטא, ועמך כולם צדיקים⁴⁵ —\n[ומהאי טעמא איז דער רמב״ן מפרש אז דער „ונשמע קולו” איז נאר א הכנה צו דער עבודה שלאחרי׳⁴⁶ פון כהן גדול און ניט קיין ענין אין דער עבודה גופא — ווייל זיין כניסה לקודש, אויך אלס שליח פון כלל ישראל, איז אין א דרגא פון עבודת הצדיקים, בקול דממה דקה⁴⁷]\nאון דאס איז די קושיא (לויט זיין פירוש): „ואם לנוי .. יעשם כמין תפוחי זהב” — אויב די „רמונים” זיינען (ניט צוליב שמוש, נאר) אויף ארויסברענגען די שיינקייט, די מעלה פון בני ישראל („לנוי”) — דארף מען מדגיש זיין ניט די מעלה וואס איז מרומז אין „רמון” [„ריקנין שבך מלאים מצות כרמון”]⁴⁸, נאר דעם עילוי פון אידן מצד פנימיותם, וואס יעדער איד איז ווי א „תפוח זהב”⁴⁹ (און ניט קיין „ריקן” ח״ו),\nע״ד ווי אין דער מנורה — וואס אירע ז׳ נרות זיינען מרמז אויף (אידן ווי זיי זיינען) די ז׳ מדרגות אין עובדי ה׳⁵⁰ — זיינען געווען אין יעדער נר „כמין תפוחים” (כנ״ל סעיף ב׳).\nז. אע״פ אז בפשטות ובחיצוניות איז די עבודה אינעם אופן פון „ונשמע קולו” נידעריקער פון דער עבודה ב„קול דממה דקה” — אעפ״כ איז דא אין איר, אין דער עבודה ברעש, אויך א מעלה לגבי דער עבודה בביטול:\nדי עבודה ב„קול דממה דקה” איז מיט א הגבלה. אמת, דער עובד שטייט טאקע מיט א ביטול, דאס איז אבער אין אן אופן פון אור בכלי, מיט א התיישבות.\nמשא״כ די עבודה פון „ונשמע קולו”, איז דער רעש גדול גופא א באווייז, אז ער איז ארויס פון די הגבלות פון „כלים”, ער קען ניט מגביל זיין די התפעלות און דעריבער קומט עס ארויס אין א צעקה וקול⁵¹. און דאס איז איינער",[["48","48","ומכש״כ שאין מקום לעשותם רמונים חלולים — היפך דמלאים מצות כרמון."],["49","49","עפ״ז תומתק הוספת הרמב״ן „(תפוחי) זהב”, וגם בזה משנה מ„(רמוני) תכלת גו׳” (ודוחק לומר דנקט לישנא דקרא משלי (כה, יא)) — להדגיש העילוי וחשיבות דבנ״י."],["50","50","לקו״ת ר״פ בהעלותך."],["51","51","וכמבואר במעלת עבודת האופנים שהיא ברעש גדול לגבי עבודת השרפים, ועד״ז הוא העילוי"],["42","42","להעיר מ<a class=\"ft-cite\" href=\"#/read/torah-or/3901370358\" data-slug=\"torah-or\" data-id=\"3901370358\">תו״א פ, סע״ג</a>."],["43","43","כלשון חז״ל — עירובין יט, א. חגיגה בסופה. וצע״ק מ״ש בתו״א שם ד„ריקנים אין פי׳ פושעים ומורדים ח״ו”. וראה לקמן ע׳ 437 הערה 25."],["44","44","לשון הרמב״ן בה„פתיחה” לפירושו עה״ת בסופה."],["45","45","ישעי׳ ס, כא."],["46","46","וגם ה„ונשמע קולו” שבאמצע העבודה (דהולכת הדם וכיו״ב), י״ל דכוונתו ההכנה לחלק העבודה שלאח״ז (דההולכה ולהזריקה)."],["47","47","או — כנ״ל הערה 34."]]],[1300161354,"פון די טעמים על דעם וואס „מקום שבע״ת עומדין אין צד״ג יכולין לעמוד בו”⁵² — ווייל דוקא אין דעם „רעש” פון עבודת התשובה זאגט זיך ארויס דער בל״ג פון נשמה.\nח. פון כל הנ״ל איז דא א הוראה מיוחדת פאר דורנו זה — דרא דעקבתא דמשיחא:\nעס זיינען פאראן אזעלכע וואס טענה׳ן: הן אמת, אז מצד דעם שפל המצב פון אונזער דור מוז מען זיך פאר־נעמען מיט הרבצת התורה והחזקת היהדות וכו׳: און אז מ׳קען זיך ניט מסתפק זיין מיט זיצן אין די אייגענע ד׳ אמות (אפילו אין די ד׳ אמות של תורה) און ווארטן ביז מ׳וועט זיך ווענדן צו אים און בעטן ער זאל מפיץ זיין תורה וכו׳, נאר מ׳דארף ארויסגיין אין „דרויסן”, אין חוצה און געפינען אידן „נדחים” און פון זיי „מאכן בעלי תשובה” —\nוואס איז אבער דער הכרח צו טאן אט די ארבעט מיט א קול רעש גדול? פאר־וואס איז אזוי נויטיק צו ארויסגיין אין גאס און דארט אויסרופן בקול רם, אז אידן זאלן לייגן תפילין, אנקלאפן מזוזות אויף די טירן, געבן צדקה וכיו״ב — א הנהגה וואס מ׳געפינט ניט א שטורעם בזה אין די פריערדיקע דורות?!\nאיז דער ענטפער אויף דעם: לויט אלע סימנים פון סוף מס׳ סוטה זעט מען אז מיר געפינען זיך איצט אין דרא דעקבתא דמשיחא — אין דער דרגא היותר תחתונה — „שולי המעיל”; דארף מען וויסן זיין, אז בשולי המעיל דארפן זיין די „פעמונים”⁵³ — אז די כניסה פון דעם סוג אידן „אל הקודש”, תחת כנפי השכינה איז אויסגעשטעלט אין אן אופן פון „ונשמע קולו”; ואדרבה — דוקא אין דעם „רעש” פון עבודת התשובה איז דער תכלית העילוי, כנ״ל.\nט. נאך אן ענין אין דעם:\nבשעת מ׳זעט אז ביי „עוברי רצונו” איז דא „קול המונה של רומי”⁵⁴ — אלע ענינים פון לעו״ז ווערן געטאן ניט בחדרי חדרים, נאר מיט דעם גרעסטן פרסום ורעש —\nאיז דער וועג צו מבטל זיין דעם שטורעם פון סטרא אחרא — „במינה ודוגמתה .. מיני׳ ובי׳ אבא לשדי׳ בי׳ נרגא”⁵⁵, ד.ה. דורכדעם וואס אויך די עבודה פון „עושי רצונו” איז אין אן אופן פון „ונשמע קולו” און דוקא אין דעם ארט וואו עס געפינט זיך „קול המונה של רומי”:\nאון דאס וועט ברענגען צו „מה לעוברי רצונו כך לעושי רצונו עאכו״כ”⁵⁴ — אז ביי אידן וועט זיין „יושבין בטח והשקט”⁵⁴ על אדמתם, דורך „יתקע בשופר גדול”⁵⁶ דוקא, דורך דעם „קול מבשר מבשר ואומר” — מבשר הגאולה, בקרוב ממש.\n(משיחת ש״פ תצוה תשל״ה)",[["","","בהאהבה של נה״ב לגבי אהבת נה״א (מצ״ע) — ראה לקו״ת ד״ה האזינו (הג׳) פ״א־ד (ושם פ״ד, שזהו העילוי דעבודת התשובה). ובכ״מ."],["52","52","ברכות לד, ב. רמב״ם הל׳ תשובה פ״ז ה״ד."],["53","53","וראה סה״מ תש״ב (ריש ע׳ 7): הנרדמים הצריכים הקיצה והוא ע״י רעש וקול כו׳."],["54","54","לשון הגמרא — סוף מכות."],["55","55","<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא רפל״א</a>."],["56","56","ישעי׳ כז, יג. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">לקו״ת ר״ה</a> ד״ה והי׳ ביום ההוא (נח, א ואילך). עטרת ראש שער ר״ה כב, א ואילך."]]],[1300161355,"<h3>תצוה — ז' אדר*</h3>\nא. ס'איז ידוע אז ז' אדר, יום פטירת משה רבינו<sup data-n=\"1\">1</sup>, פאלט אויס (ברוב השנים) בסמיכות צו פ' תצוה; און ווי עס שטייט אין ספרים<sup data-n=\"2\">2</sup> דער רמז אויף דעם אין פ' תצוה, אז משנולד משה איז דאס די איינציקע סדרה אין דער תורה (נאך פ' שמות<sup data-n=\"3\">3</sup> וואו עס ווערט ניט דערמאנט משה'ס נאמען<sup data-n=\"4\">4</sup>, און דערין איז מרומז די הסתלקות פון משה בז' אדר.\nאון דאס איז אויך מתאים מיט דעם וואס שטייט אין מגן אברהם<sup data-n=\"5\">5</sup>, אז בשנה מעוברת (כבשנה זו) איז דער תענית ז' אדר באדר ראשון — וואַרום ז' אדר ראשון דוקא איז בסביבות פון פרשת תצוה.\nדארף מען פארשטיין: ז' אדר איז אויך דער טאג פון לידת משה<sup data-n=\"6\">6</sup>, ווי די גמרא<sup data-n=\"7\">7</sup> זאגט: „הקב\"ה יושב וממלא שנותיהם של צדיקים מיום ליום ומחודש לחודש\"<sup data-n=\"8\">8</sup> — היינט פארוואס איז ניט מרומז אין פרשת תצוה אויך לידתו של משה ?\nב. אין פשטות קען מען זאגן, אז אויך לידת משה איז מרומז אין דער סדרה — אין דעם וואס דער נאמען פון דער סדרה איז „ואתה תצוה\"<sup data-n=\"9\">9</sup>, וואס",[["","","*) שענינו באדר ראשון — ראה בפנים סעיף א' (ממגן אברהם). וראה לקו\"ש חכ\"י ע' 204 בהערה."],["1","1","מגילה יג, ב. וש\"נ. מאמר האחרון במגילת תענית. טושו\"ע או\"ח סי' תקף ס\"ב. וראה לקמן בפנים."],["2","2","מאור עינים פרשתנו (ועוד). וכמובן אין בזה סתירה להטעם (זח\"ג רמו, א ועוד — ראה לקמן הערה 4) שזהו מפני שאמר משה מחני נא מספרך — כי עדיין טעמא בעי למה דוקא בפ' תצוה (ואדרבה — לכאורה צ\"ל בפרשיות שלאחרי אמירת מחני נא). — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211173\" data-slug=\"likkutei-sichot\" data-id=\"1300211173\">לקו\"ש חכ\"א ע' 173</a> ואילך."],["3","3","פי' הרא\"ש הדר זקנים (משנולד משה עד משנה תורה). בעה\"ט ריש פרשתנו („משעה שנולד משה\" — ובחצע\"ג הוסיפו כבפי' הרא\"ש)."],["4","4","זח\"ג רמו, א. מדרש הנעלם בזהר חדש שה\"ש קרוב לתחלתו ד\"ה פתח ואמר („האי). פי' הרא\"ש (הדר זקנים), בעה\"ט ופענח רזא ריש פרשתנו. רבותינו בעה\"ת תשא לב, לב. ועוד. וראה לקו\"ש חי\"ב ע' 674 ואילך."],["5","5","או\"ח שם סק\"ח. מתשובת מהרי\"ל סל\"א. וכ\"ה בתה\"ד סרצ\"ד. וראה שו\"ת מהר\"י מינץ ס\"ס. רמ\"א סתקס\"ח ס\"ז (ובנ\"כ שם וש\"נ). ובמהרי\"ל שם, דאף שמת באדר הסמוך לניסן מתענין באד\"ר. אבל במג\"א ממשיך „ועיין בילקוט יהושע דף ד' ע\"ב דאיכא מ\"ד שהיתה מעוברת ומת באדר\"ר\" (והוא ביל\"ש שם רמז טו. ממכילתא בשלח טז, לה). והנה צויין באחרונים דעות אלו שצ\"ל באדר שני (הח\"צ (בשאילת יעב\"ץ ח\"א סקי\"ז). היעב\"ץ בסידורו. פתח עינים (ר\"ה, יא). חת\"ס חאו\"ח סקס\"ג. שו\"ת ויען יצחק חיו\"ד סל\"ט. שכיות החמדה לר\"ד פארדו. ועוד) — אבל כבר כתבו בערוך השלחן, במשנה ברורה, ארחות חיים החדש (ועוד) דנוהגין להתענות בראשון. והרי במדינות אלו היו רוב מנין דבנ\"י בדורם."],["6","6","מגילה שם. וש\"נ."],["7","7","קידושין לח, א."],["8","8","ועפ\"ז מובן שבשנה מעוברת ענינו דלידת משה הוא באדר\"ר. וראה סוטה יב, ב דלחד מ\"ד נולד בז' אדר\"ר. וראה שאילת יעב\"ץ שם דלמ\"ד זה כצ\"ל ביום מיתתו שנפטר בז' אדר לפי שהקב\"ה ממלא שנותיהן של צדיקים כו'. וראה לקמן הערה 63."],["9","9","ראה מגילה כט, סע\"ב: „חל להיות בואתה תצוה\", ושם יש לדחוק שהכוונה להתחלת קריאת היום. אבל בזח\"ג שם מפורש „דלא מדכר בפרשת ואתה תצוה\". וכ\"ה בזח\"ח שם (ברוב הדפוסים) „ואיהי פרשת ואתה תצוה\". וכ\"ה בסדר תפלות להרמב\"ם. הל' תפלה פי\"ג הכ\"ב (אבל ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071112\" data-slug=\"likkutei-sichot\" data-id=\"1300071112\">לקו\"ש ח\"ז ע' 100</a> שוה\"ג להערה 3). ובכ\"מ בפרש\"י — תרומה כה, ו־ז. צו ח, ב. ה."]]],[1300161356,"דאס גייט<sup data-n=\"10\">10</sup> אויף משה רבינו<sup data-n=\"11\">11</sup>. און ווי־באלד אז דער שם הסדרה איז מרמז אויפן תוכן פון דער גאנצער סדרה — קומט אויס, אז אין דער גאנצער סדרה איז מרומז דער ענין פון (לידת) משה.\nאפילו לויט די דעות און לויט מנהג ישראל (און ווי געדרוקט בחומשים) אז זי ווערט אנגערופן „תצוה\" — איז דאס דאך לשון יחיד לנוכח — בהמשך צו „וידבר<sup data-n=\"12\">12</sup> ה' אל משה לאמר\" שבהתחלת הענין, און — אויך גלייך נאך „תצוה\" — „אהרן אחיך\".\nמען דארף אבער פארשטיין, ווי שטי־מען ביידע רמזים הנ\"ל: פון איין זייט, איז אין דער סדרה ווערט אינגאנצן ניט דערמאנט משה'ס נאמען (וואס ווייזט, אז אין דער סדרה איז ניטא ענינו של משה); און פון דער צווייטער זייט, איז יעדער ווארט פון דער סדרה הייסט א ווארט פון פרשת „ואתה תצוה\" וואס גייט אויף משה ?\nג. וועט מען דאס פארשטיין בהקדם לבאר ענין התענית פון ז' אדר — דלכאורה דארף מען פארשטיין: פאר־וואס האט מען קובע געווען ז' אדר (בלויז) אלס יום התענית מצד מיתת משה<sup data-n=\"13\">13</sup>, מען געפינט דאך אין גמרא<sup data-n=\"14\">14</sup> די שאלה ווענען איינעם וואס זאגט „כמשה בשבעה באדר\" צי דאס איז אן\nענין פון קבלת נזירות, און תוספות<sup data-n=\"15\">15</sup> איז מסביר די שאלה, אז „ביום הוולדו דהיינו בז' אדר שמחו שמחה גדולה וביום מותו כו' רבים נדרו בנדר ורבו נזירים בישראל מחמת צער והוא אמר בסתם אהא היינו כמו שהי' בדורו של משה בז' באדר ביום מותו ונזירות קבל עלי' או כיום הוולדו קאמר ושמחה קבל עלי\"\".\nזעט מען דאך אז ז' אדר איז (געווען) אויך א יום שמחה<sup data-n=\"16\">16</sup>, היינט פארוואס איז ער נקבע געווארן בלויז אלס יום תענית ?\n[מ'קען ניט זאגן אז דער ספק אין גמרא איז צי ער האט געמיינט ז' אדר ווי דאס איז לאחר מיתת משה און ער האט מקבל געווען נזירות, אדער ער האט געמיינט ז' אדר בחיי משה בעלמא דין וואס דעמאלט איז דאס געווען א יום שמחה<sup data-n=\"17\">17</sup> מצד לידתו — אבער איצטער איז דער טאג לכל הדיעות א יום תענית —",[["10","10","להעיר מחומת אנך להחיד\"א ריש פרשתנו „ולכבוד מרע\"ה נאמרה פרשה זו בלשון הזה ואתה תצוה כו'\". מאור עינים שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021398\" data-slug=\"likkutei-sichot\" data-id=\"1300021398\">לקו\"ש ח\"ב ע' 675</a>. חכ\"א וחכ\"י שם."],["11","11","והרי זוהי הסדרה היחידית שמודגש בשמה עניינו של משה. משא\"כ פ' „כי תשא\", „נשא\" ועוד — אף שהכוונה למשה אין בזה ההדגשה ד(יתור) התיבה „ואתה תצוה\" (ולא „ותצוה\")."],["12","12","ר\"פ תרומה. ראה חומת אנך שבהערה 10."],["13","13","טושו\"ע שם."],["14","14","נזיר יד, א."],["15","15","שם ד\"ה אמר כמשה. ועד\"ז בפי' הרא\"ש."],["16","16","להעיר שמצינו שמחה ביום הולדת יצחק זמן רב אחר פטירתו (תנחומא ס\"פ פקודי). ועד „שחשב הקב\"ה לערב שמחת המשכן בשמחת היום שנולד בו יצחק אבינו\" (תנחומא שם)."],["17","17","כדמשמע לכאורה מלשון התוס' „דביום הוולדו דהיינו בז' באדר שמחו שמחה גדולה\" (ובשטמ\"ק בשם הר' עזריאל „ביום שנולד משה דאכלו ושתו והדו\")*. וצע\"ק הרי „ותצפנהו ג' ירחים\" ומי ידע אז ששמח, לבד עמרם וב\"ב. ולכאורה דוחק לומר שלהם כיוון באמרו „כמשה בשבעה באדר\" — ואולי ותצפנהו רק מהמצרים. *) וכמו שמפרש בזה שמת (שאין כוונתו לז' אדר עתה לאחר מיתת משה, כ\"א „ביום מותו בז' באדר מסתמא רבים נדרו בנדר ורבו נזירים בישראל\". ועד\"ז בפי' הרא\"ש „ביום שנפטר כו'\". וכ\"ה בשטמ\"ק בשם הר' עזריאל."]]]]});
